__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"lorePack",{enumerable:!0,get:function(){return v}});var s=r(d[0]),t=r(d[1]),n=r(d[2]),o=r(d[3]),l=r(d[4]),c=r(d[5]),u=r(d[6]),h=r(d[7]),w=r(d[8]),p=r(d[9]);const v={entries:{...s.chapters1,...t.chapters2,...n.classes,...o.races,...l.zones1,...c.zones2,...u.instances1,...h.instances2,...w.items,...p.terms},eras:{creation:{title:"Les titans et les Dieux tr\xe8s anciens",when:"Avant l\u2019histoire \xe9crite"},"ancient-kalimdor":{title:"L\u2019empire kaldorei",when:"Dix mille ans et plus avant la Porte des T\xe9n\xe8bres"},"elder-kingdoms":{title:"Les anciens royaumes",when:"Environ 7 000 \xe0 200 ans avant la Porte des T\xe9n\xe8bres"},draenor:{title:"Les orcs de Draenor",when:"Les d\xe9cennies pr\xe9c\xe9dant la Porte des T\xe9n\xe8bres"},"first-war":{title:"La Premi\xe8re Guerre",when:"L\u2019ouverture de la Porte des T\xe9n\xe8bres (an 0)"},"second-war":{title:"La Deuxi\xe8me Guerre",when:"Quelques ann\xe9es apr\xe8s la Porte des T\xe9n\xe8bres"},interwar:{title:"L\u2019entre-deux-guerres",when:"Les ann\xe9es qui suivirent la Deuxi\xe8me Guerre"},"third-war":{title:"La Troisi\xe8me Guerre",when:"Environ vingt ans apr\xe8s la Porte des T\xe9n\xe8bres"},"new-homes":{title:"De nouveaux foyers en Kalimdor",when:"Les ann\xe9es qui suivirent la Troisi\xe8me Guerre"},classic:{title:"L\u2019\xe8re de World of Warcraft",when:"An 25 apr\xe8s la Porte des T\xe9n\xe8bres, l\u2019\xe9poque de Forever"},beyond:{title:"Apr\xe8s Classic",when:"Extensions ult\xe9rieures (hors de Forever)"}},categories:{chapter:"L\u2019histoire de Warcraft",class:"Classes",race:"Races",zone:"Zones",instance:"Donjons et raids",item:"Objets l\xe9gendaires",term:"Glossaire"},notice:"Texte original \xe9crit pour WoW Forever Path. Les faits ont \xe9t\xe9 v\xe9rifi\xe9s aupr\xe8s des sources indiqu\xe9es ; les pages de warcraft.wiki.gg (CC BY-SA 4.0) et les articles de Blizzard ont servi de r\xe9f\xe9rences, sans reprise de leur texte. World of Warcraft et Blizzard sont des marques de Blizzard Entertainment, Inc."}},1574,[1593,1594,1595,1596,1597,1598,1599,1600,1601,1602]);
__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"chapters1",{enumerable:!0,get:function(){return s}});const s={"chapter:titans-and-old-gods":{title:"Les titans et les Dieux tr\xe8s anciens",summary:"Avant tout royaume mortel, les titans du Panth\xe9on combattirent les Dieux tr\xe8s anciens pour l\u2019\xe2me d\u2019un jeune monde, et Azeroth en porte encore les cicatrices.",when:"Avant l\u2019histoire \xe9crite",body:["Bien avant que les mortels ne tiennent des archives, les titans parcouraient l\u2019immensit\xe9 obscure du cosmos : des \xe2mes-mondes devenues des g\xe9ants vivants. Les plus nobles d\u2019entre eux s\u2019unirent au sein du Panth\xe9on et fouill\xe8rent les \xe9toiles \xe0 la recherche d\u2019\xe2mes-mondes endormies semblables \xe0 la leur. Au c\u0153ur d\u2019Azeroth, ils en per\xe7urent une aux promesses extraordinaires, mais des puissances plus sombres l\u2019avaient trouv\xe9e avant eux.","Les seigneurs du Vide avaient pr\xe9cipit\xe9 leurs serviteurs, les Dieux tr\xe8s anciens, sur ce jeune monde. Y'Shaarj, C'Thun, Yogg-Saron et N'Zoth enfonc\xe8rent leurs corps dans la cro\xfbte et b\xe2tirent l\u2019Empire noir, avec pour g\xe9n\xe9raux les seigneurs \xe9l\xe9mentaires du feu, de la terre, de l\u2019air et de l\u2019eau. \xc0 l\u2019arriv\xe9e du Panth\xe9on, ses arm\xe9es forg\xe9es par les titans bris\xe8rent les citadelles de l\u2019empire. Le Haut-P\xe8re Aman'Thul arracha Y'Shaarj du sol, mais le coup ouvrit une plaie d\u2019o\xf9 s\u2019\xe9coulait le sang arcanique du monde. Les titans comprirent que tuer les autres risquait de tuer Azeroth elle-m\xeame.","Les gardiens choisirent donc des prisons. C'Thun, Yogg-Saron et N'Zoth furent encha\xeen\xe9s au plus profond de la terre, et les seigneurs \xe9l\xe9mentaires furent bannis dans le plan \xc9l\xe9mentaire, dont les royaumes comprennent Skywall et les Terres de Feu. Les gardiens apais\xe8rent la plaie sanglante en un lac scintillant, le Puits d\u2019\xe9ternit\xe9, fa\xe7onn\xe8rent montagnes et mers, et laiss\xe8rent derri\xe8re eux des chambres fortes titaniques comme Uldaman. Apr\xe8s la chute d\u2019un monstrueux proto-dragon nomm\xe9 Galakrond, le Panth\xe9on \xe9leva cinq grands dragons au rang d\u2019Aspects pour prot\xe9ger le monde, puis repartit vers les \xe9toiles."]},"chapter:sargeras-and-the-burning-legion":{title:"Sargeras et la L\xe9gion ardente",summary:"Le plus grand champion du Panth\xe9on perdit foi en la cr\xe9ation et leva une croisade d\xe9moniaque pour la r\xe9duire en cendres ; Azeroth devint la proie qu\u2019il convoitait le plus.",when:"Bien avant les elfes de la nuit",body:["Sargeras \xe9tait le champion du Panth\xe9on, le titan qui traquait les d\xe9mons \xe0 travers le cosmos et les enfermait sur un monde-prison nomm\xe9 Mardum. Au fil d\u2019\xe2ges de guerre, il d\xe9couvrit ce que voulaient vraiment les seigneurs du Vide : corrompre une \xe2me-monde et donner naissance \xe0 leur propre titan noir. Convaincu que la cr\xe9ation \xe9tait irr\xe9m\xe9diablement vici\xe9e, il jugea plus cl\xe9ment de tout br\xfbler.","Il brisa la prison de Mardum et lib\xe9ra ses d\xe9mons, qui form\xe8rent les premiers rangs de la L\xe9gion ardente. Sur le monde d\u2019Argus, il offrit savoir et pouvoir aux \xe9r\xe9dars ; leurs chefs Kil'jaeden et Archimonde accept\xe8rent, tandis que le proph\xe8te Velen s\u2019enfuit avec ceux qui refusaient, le peuple qu\u2019on appellerait plus tard les draene\xef. Le Panth\xe9on tenta d\u2019arr\xeater son ancien champion et p\xe9rit de sa main.","D\xe8s lors, la L\xe9gion passa de monde en monde, men\xe9e par Sargeras et servie par les \xe9r\xe9dars, les seigneurs de l\u2019effroi appel\xe9s nathrezim et d\u2019innombrables d\xe9mons mineurs. Azeroth comptait plus que la plupart des mondes : une \xe2me-monde encore endormie, d\xe9j\xe0 marqu\xe9e par les Dieux tr\xe8s anciens. \xc0 l\u2019\xe9poque de World of Warcraft, la L\xe9gion l\u2019avait envahie deux fois, et ses murmures avaient fa\xe7onn\xe9 l\u2019histoire des elfes, des orcs et des humains."]},"chapter:rise-of-the-kaldorei":{title:"L\u2019essor des Kaldorei",summary:"Les trolls r\xe9gnaient sur l\u2019antique Kalimdor jusqu\u2019\xe0 ce qu\u2019une tribu attir\xe9e par le Puits d\u2019\xe9ternit\xe9 devienne les elfes de la nuit, dont la reine Azshara b\xe2tit un empire d\u2019une magie stup\xe9fiante.",when:"Environ 15 000 \xe0 10 000 ans avant la Porte des T\xe9n\xe8bres",body:["Dans les \xe2ges qui suivirent le d\xe9part des titans, Kalimdor formait un seul grand continent. Men\xe9s par les Zandalari, les trolls livr\xe8rent une longue guerre aux aqir, des \xeatres insecto\xefdes, vestiges des serviteurs des Dieux tr\xe8s anciens, et les repouss\xe8rent aux confins nord et sud du territoire, o\xf9 leurs descendants deviendraient les n\xe9rubiens et les qiraji. Apr\xe8s la victoire, les trolls se divis\xe8rent en empires rivaux, comme ceux des Gurubashi et des Amani.","Une tribu troll choisit une voie plus paisible. Elle s\u2019installa sur les rives du Puits d\u2019\xe9ternit\xe9 et, au fil des g\xe9n\xe9rations, le pouvoir du Puits la transforma : son peuple grandit, v\xe9cut plus longtemps, v\xe9n\xe9ra la d\xe9esse lunaire \xc9lune et se nomma kaldorei, \xab enfants des \xe9toiles \xbb. Guid\xe9s par le demi-dieu Cenarius et d\u2019autres esprits anciens de la nature, ils \xe9clips\xe8rent bient\xf4t leurs cousins trolls.","Leur plus grande souveraine fut la reine Azshara, ador\xe9e de son peuple et servie par les Bien-n\xe9s, une aristocratie de sorciers qui puisaient toujours plus de pouvoir dans le Puits. Son palais de Zin-Azshari se dressait sur ses rives, et son empire s\u2019\xe9tendait sur tout Kalimdor. Mais la soif de magie des Bien-n\xe9s envoya des ondes bien au-del\xe0 du monde, et quelque chose d\u2019immense, dans le N\xe9ant distordu, les per\xe7ut."]},"chapter:war-of-the-ancients":{title:"La guerre des Anciens",summary:"Azshara ouvrit la voie \xe0 la L\xe9gion ardente, et le monde faillit p\xe9rir avant que le Puits d\u2019\xe9ternit\xe9 ne se d\xe9chire.",when:"Environ 10 000 ans avant la Porte des T\xe9n\xe8bres",body:["Sargeras murmura \xe0 Azshara et \xe0 ses Bien-n\xe9s, leur promettant un monde refait \xe0 leur image. Ils le crurent et, gr\xe2ce au Puits d\u2019\xe9ternit\xe9, ouvrirent un portail \xe0 la L\xe9gion ardente. Men\xe9s par Archimonde et Mannoroth, les d\xe9mons d\xe9ferl\xe8rent sur Kalimdor et se mirent \xe0 massacrer les Kaldorei m\xeames sur lesquels r\xe9gnait la reine.","La r\xe9sistance se rassembla autour de chefs inattendus : Malfurion Hurlorage, le premier elfe de la nuit \xe0 apprendre le druidisme aupr\xe8s de Cenarius ; son fr\xe8re jumeau Illidan, un sorcier dou\xe9 ; et Tyrande Murmevent, pr\xeatresse d\u2019\xc9lune. Les demi-dieux de la nature et la plupart des vols draconiques combattirent \xe0 leurs c\xf4t\xe9s. L\u2019Aspect noir Neltharion offrit une arme, l\u2019\xc2me des dragons, mais la retourna contre ses alli\xe9s ; cette trahison lui vaudrait le nom d\u2019Aile-de-mort.","Quand Sargeras lui-m\xeame tenta de franchir le portail, Malfurion et ses alli\xe9s perturb\xe8rent le sort des Bien-n\xe9s. Instable, le Puits implosa, et la Fracture s\u2019ensuivit : la mer engloutit Zin-Azshari, Kalimdor se brisa, et une temp\xeate appel\xe9e le Maelstr\xf6m se mit \xe0 tourner l\xe0 o\xf9 se trouvait le Puits. Azshara et sa cour disparurent sous les flots, pour revenir un jour sous la forme des nagas. De ce continent unique naquirent les terres connues aujourd\u2019hui sous les noms de Kalimdor, des royaumes de l\u2019Est et de Norfendre."]},"chapter:the-long-watch-of-hyjal":{title:"La longue veille d\u2019Hyjal",summary:"Les survivants firent pousser un Arbre-Monde au-dessus d\u2019un second Puits, emprisonn\xe8rent Illidan sous terre et mont\xe8rent la garde pendant dix mille ans.",when:"\xc0 partir d\u2019environ 10 000 ans avant la Porte des T\xe9n\xe8bres",body:["Les elfes de la nuit qui avaient \xe9chapp\xe9 \xe0 la Fracture se r\xe9unirent sur le mont Hyjal. Ils y d\xe9couvrirent qu\u2019Illidan avait emport\xe9 des fioles de l\u2019eau de l\u2019ancien Puits et en avait vers\xe9 une partie dans un lac de montagne, cr\xe9ant un nouveau Puits d\u2019\xe9ternit\xe9. Craignant qu\u2019il ne rappelle un jour la L\xe9gion, Malfurion et Cenarius emprisonn\xe8rent Illidan dans les Barrow Deeps, une prison souterraine o\xf9 la gardienne Maiev Chantelombre le surveillerait pendant dix mille ans.","Trois Aspects, Alexstrasza, Ysera et Nozdormu, r\xe9pondirent en faisant pousser Nordrassil, l\u2019Arbre-Monde, au-dessus du nouveau Puits. Ses racines scell\xe8rent les eaux, et sa b\xe9n\xe9diction accorda l\u2019immortalit\xe9 aux elfes de la nuit et aux druides un lien avec le R\xeave d\u2019\xe9meraude, o\xf9 beaucoup dormirent des si\xe8cles durant. Tyrande dirigeait les S\u0153urs d\u2019\xc9lune et les Sentinelles, qui gardaient les for\xeats pendant que les druides r\xeavaient. La magie arcanique fut proscrite chez les Kaldorei.","Tous les Bien-n\xe9s n\u2019ob\xe9irent pas. Certains furent exil\xe9s de l\u2019autre c\xf4t\xe9 de la mer et fond\xe8rent Quel'Thalas ; d\u2019autres, les Shen'dralar, se cach\xe8rent dans la cit\xe9 d\u2019Eldre'Thalas, dans l\u2019actuel F\xe9ralas. Ses ruines sont aujourd\u2019hui connues sous le nom de Hache-Tripes."]},"chapter:exiles-of-quelthalas":{title:"Les exil\xe9s de Quel'Thalas",summary:"Des Bien-n\xe9s bannis travers\xe8rent la mer, allum\xe8rent le Puits de soleil et b\xe2tirent un royaume elfique dans les for\xeats septentrionales de Lordaeron.",when:"Environ 6 800 ans avant la Porte des T\xe9n\xe8bres",body:["Longtemps apr\xe8s la Fracture, un groupe de Bien-n\xe9s ne pouvait toujours pas renoncer aux arcanes. Leurs sorts inconsid\xe9r\xe9s d\xe9cha\xeen\xe8rent des temp\xeates sur Orneval, et les elfes de la nuit finirent par les bannir. Men\xe9s par Dath'Remar Haut-Soleil, les exil\xe9s firent voile vers l\u2019est \xe0 travers la Grande mer et err\xe8rent des ann\xe9es sur le nouveau continent, en qu\xeate d\u2019une terre o\xf9 la magie coulait avec force.","Vers 6 800 ans avant la Porte des T\xe9n\xe8bres, ils la trouv\xe8rent au nord de Lordaeron. Dath'Remar versa une fiole vol\xe9e d\u2019eau du Puits d\u2019\xe9ternit\xe9 dans un lac situ\xe9 sur un nexus de lignes telluriques, et le Puits de soleil s\u2019embrasa. Autour de lui s\u2019\xe9lev\xe8rent Quel'Thalas et sa capitale, Lune-d\u2019argent. Vivant sous le soleil plut\xf4t que sous la lune, les exil\xe9s chang\xe8rent au fil des si\xe8cles et devinrent les hauts-elfes, les quel'dorei.","La terre n\u2019\xe9tait pas vide. Elle abritait d\u2019antiques ruines sacr\xe9es pour les trolls amani, qui attaqu\xe8rent les nouveaux venus en nombre \xe9crasant. Les elfes les repouss\xe8rent par la magie et dress\xe8rent Ban'dinoriel, une barri\xe8re de pierres runiques qui tint les Amani \xe0 distance. Pendant quelque quatre mille ans, Quel'Thalas prosp\xe9ra derri\xe8re elle, tandis que les trolls attendaient leur vengeance."]},"chapter:arathor-and-the-troll-wars":{title:"Arathor et les guerres des Trolls",summary:"Les tribus \xe9parses de l\u2019humanit\xe9 s\u2019unirent sous le roi Thoradin, et une alliance avec les elfes brisa l\u2019empire amani au pied des montagnes d\u2019Alterac.",when:"Environ 2 800 ans avant la Porte des T\xe9n\xe8bres",body:["Pendant des mill\xe9naires, les tribus humaines des royaumes de l\u2019Est se combattirent entre elles tandis que des pillards amani frappaient depuis le nord. Vers 2 800 ans avant la Porte des T\xe9n\xe8bres, Thoradin, de la tribu des Arathi, comprit qu\u2019une humanit\xe9 divis\xe9e serait an\xe9antie. Par des mariages, des promesses et des conqu\xeates, il unit les tribus en un royaume, Arathor, et b\xe2tit sa capitale, la cit\xe9-forteresse de Strom, dans les actuelles hautes-terres Arathies.","Ranim\xe9s avec l\u2019aide des Zandalari, les Amani assaillirent Quel'Thalas en masse. Les elfes se tourn\xe8rent vers Arathor. En \xe9change de soldats humains, ils accept\xe8rent d\u2019enseigner la magie \xe0 cent humains choisis, les premiers mages humains. Ensemble, elfes et humains \xe9cras\xe8rent l\u2019arm\xe9e amani au pied des montagnes d\u2019Alterac, et le feu des mages dispersa les trolls si compl\xe8tement que leur empire ne s\u2019en remit jamais.","Par gratitude, les elfes de Quel'Thalas jur\xe8rent fid\xe9lit\xe9 \xe0 la lign\xe9e des rois d\u2019Arathor. Strom prosp\xe9ra, et son peuple se r\xe9pandit dans tout le nord. Les Amani se rel\xe8veraient bien des fois, et dans les Hinterlands et les hautes-terres Arathies, des tribus de trolls des for\xeats hantent encore les ruines de cette vieille guerre."]},"chapter:guardians-and-the-seven-kingdoms":{title:"Les Gardiens et les sept royaumes",summary:"La magie humaine attira les d\xe9mons : les mages fond\xe8rent donc Dalaran et choisirent des Gardiens pour combattre en secret, tandis qu\u2019Arathor se divisait en sept royaumes.",when:"Les mill\xe9naires qui suivirent les guerres des Trolls",body:["La magie se r\xe9pandit dans Arathor plus vite que la sagesse. Les sorts des mages amincirent les murs du monde et attir\xe8rent l\u2019attention des d\xe9mons ; les hauts-elfes et les mages humains form\xe8rent donc le Conseil de Tirisfal. En secret, le conseil choisit un Gardien unique pour d\xe9tenir leur pouvoir r\xe9uni et traquer les agents de la L\xe9gion ardente.","Les mages b\xe2tirent aussi leur propre cit\xe9, Dalaran, o\xf9 r\xe9gnerait le Kirin Tor. Pendant ce temps, les h\xe9ritiers d\u2019Arathor s\u2019\xe9loign\xe8rent de Strom et, au fil des si\xe8cles, l\u2019empire se scinda en sept royaumes humains : Lordaeron, Stromgarde, Gilneas, Alterac, Kul Tiras, Dalaran et, au sud, Hurlevent, longtemps appel\xe9 le royaume d\u2019Azeroth.","La plus c\xe9l\xe8bre des Gardiens fut Aegwynn, qui terrassa en Norfendre un avatar de Sargeras lui-m\xeame et scella son corps dans un tombeau sous la mer. Elle ne sut jamais que l\u2019esprit du titan noir s\u2019\xe9tait gliss\xe9 en elle. Quand elle donna naissance \xe0 un fils, Medivh, l\u2019esprit passa en lui, et le dernier Gardien grandit avec un tra\xeetre cach\xe9 dans son \xe2me. Depuis sa tour de Karazhan, il ouvrirait un jour la porte aux orcs."]},"chapter:war-of-the-three-hammers":{title:"La guerre des Trois Marteaux",summary:"Les trois clans nains de Forgefer se disput\xe8rent le tr\xf4ne, et un thane-sorcier vaincu invoqua Ragnaros, qui br\xfbla la terre jusqu\u2019\xe0 former le mont Rochenoire.",when:"Environ 230 ans avant la Porte des T\xe9n\xe8bres",body:["Sous les neiges de Dun Morogh, les nains creus\xe8rent Forgefer, un royaume de pierre et d\u2019artisanat dont les racines remontaient aux terrestres des titans. Trois clans le partageaient dans une paix fragile : les Barbe-de-bronze, les Marteau-hardi et les Sombrefer, \xe9pris de sorcellerie. \xc0 la mort du haut roi Modimus Courbenclume, quelque 230 ans avant la Porte des T\xe9n\xe8bres, leur rivalit\xe9 \xe9clata en guerre civile.","Les Barbe-de-bronze l\u2019emport\xe8rent et chass\xe8rent les autres. Les Marteau-hardi b\xe2tirent Grim Batol \xe0 l\u2019est, et les Sombrefer fond\xe8rent leur propre royaume au sud, dans les Carmines. Le thane-sorcier Thaurissan ne put accepter la d\xe9faite. Il frappa ses deux rivaux \xe0 la fois, mais ses arm\xe9es furent bris\xe9es, et son \xe9pouse Modgud tomba \xe0 Grim Batol.","En d\xe9sespoir de cause, Thaurissan se tourna vers une puissance sup\xe9rieure et invoqua Ragnaros, le seigneur du Feu, un seigneur \xe9l\xe9mentaire que les titans avaient emprisonn\xe9. L\u2019arriv\xe9e du seigneur du Feu tua le thane, d\xe9chira la terre pour former la gorge des Vents br\xfblants et les steppes Ardentes, et fit surgir le mont Rochenoire, o\xf9 les Sombrefer survivants devinrent ses esclaves. Les Marteau-hardi abandonn\xe8rent Grim Batol, devenue maudite, pour les Hinterlands. Leurs voisins gnomes, dont la cit\xe9 de Gnomeregan se trouvait tout pr\xe8s, devinrent de fid\xe8les amis de Forgefer."]},"chapter:corruption-of-the-orcs":{title:"La corruption des orcs",summary:"Sur la lointaine Draenor, Kil'jaeden transforma les clans chamaniques des orcs en une Horde sanguinaire li\xe9e par le sang d\xe9moniaque.",when:"Les d\xe9cennies pr\xe9c\xe9dant la Porte des T\xe9n\xe8bres",body:["Sur le monde de Draenor, les orcs vivaient en clans fiers de chasseurs et de chamans, honorant leurs anc\xeatres et les esprits des \xe9l\xe9ments. Ils partageaient leur monde, non sans tensions, avec les draene\xef, ces \xe9r\xe9dars qui avaient fui Argus avec Velen. Kil'jaeden n\u2019avait jamais cess\xe9 de traquer ces exil\xe9s, et il vit dans les orcs une arme.","D\xe9guis\xe9 en esprit de la d\xe9funte \xe9pouse de Ner'zhul, le seigneur d\xe9mon murmura au vieux chaman et le dressa contre les draene\xef. Quand Ner'zhul h\xe9sita, Kil'jaeden trouva un \xe9l\xe8ve plus docile en Gul'dan, qui fonda le Conseil des ombres secret et enseigna aux orcs la magie gangren\xe9e ; ce furent les premiers d\xe9monistes. Les \xe9l\xe9ments se turent, et la verte terre des orcs commen\xe7a \xe0 mourir.","Lors d\u2019un grand rassemblement, les chefs de clan burent le sang du seigneur des ab\xeemes Mannoroth, et Grom Hurlenfer, du clan Chanteguerre, but le premier. Emplie d\u2019une fureur d\xe9moniaque, la Horde unie s\u2019abattit sur les draene\xef et les extermina presque. Seul le clan Loup-de-givre de Durotan resta en partie \xe0 l\u2019\xe9cart. Une fois le massacre termin\xe9, Gul'dan avait besoin d\u2019une nouvelle guerre, et le ma\xeetre de Kil'jaeden en tenait d\xe9j\xe0 une pr\xeate sur Azeroth."]},"chapter:the-first-war":{title:"La Porte des T\xe9n\xe8bres et la Premi\xe8re Guerre",summary:"Medivh aida les orcs \xe0 ouvrir la Porte des T\xe9n\xe8bres, et la Horde d\xe9ferla sur le royaume de Hurlevent.",when:"An 0 : la Porte des T\xe9n\xe8bres s\u2019ouvre",body:["Guid\xe9s par Medivh, alors poss\xe9d\xe9, les d\xe9monistes de Gul'dan et le Gardien ouvrirent une faille entre Draenor et Azeroth dans le Noir Mar\xe9cage, ce marais qui se fl\xe9trit plus tard pour devenir les terres Foudroy\xe9es. Les orcs se d\xe9vers\xe8rent par ce que l\u2019on appela la Porte des T\xe9n\xe8bres, et leurs \xe9claireurs d\xe9couvrirent bient\xf4t les riches champs du royaume d\u2019Azeroth, l\u2019actuel Hurlevent.","Le roi Llane Wrynn et son champion Anduin Lothar r\xe9sist\xe8rent pendant des ann\xe9es. Khadgar, l\u2019apprenti m\xeame de Medivh, d\xe9couvrit la trahison de son ma\xeetre et, avec Lothar et la demi-orque Garona, affronta le Gardien \xe0 Karazhan et le tua. La victoire vint trop tard. Les bandes de guerre de la Horde mirent le royaume \xe0 feu et \xe0 sang, et au sein de la Horde, le rus\xe9 Orgrim Marteau-du-Destin abattit Main-Noire et devint chef de guerre.","Garona, li\xe9e par les sorts de Gul'dan, assassina le roi Llane, et la cit\xe9 de Hurlevent tomba et br\xfbla. Lothar rassembla les survivants, parmi lesquels Varian, le jeune fils de Llane, et les conduisit par-del\xe0 la mer jusqu\u2019\xe0 Lordaeron. Loin \xe0 l\u2019est, dans les Riverglades, une r\xe9gion qui n\u2019existe que dans Forever, la Horde rasa le village de Sunnyglade et emmena ses survivants en esclavage."]},"chapter:the-second-war":{title:"La Deuxi\xe8me Guerre",summary:"Les royaumes humains, les elfes, les nains et les gnomes s\u2019unirent dans l\u2019Alliance de Lordaeron et bris\xe8rent la Horde de Marteau-du-Destin au pic Rochenoire.",when:"Environ cinq \xe0 six ans apr\xe8s la Porte des T\xe9n\xe8bres",body:["L\u2019avertissement de Lothar poussa le roi Terenas Menethil de Lordaeron \xe0 r\xe9unir les royaumes humains. Ils form\xe8rent l\u2019Alliance de Lordaeron, avec Lothar pour commandant supr\xeame ; les nains de Forgefer, les gnomes et, fid\xe8les \xe0 leur vieux serment envers la lign\xe9e d\u2019Arathor, les hauts-elfes de Quel'Thalas les rejoignirent. Pour donner espoir aux soldats, l\u2019archev\xeaque Alonsus Faol fonda les chevaliers de la Main d\u2019argent, les premiers paladins, avec Uther le Porteur de Lumi\xe8re \xe0 leur t\xeate.","La Horde de Marteau-du-Destin s\u2019\xe9tait elle aussi renforc\xe9e. Des ogres, des trolls amani men\xe9s par Zul'jin et des sapeurs gobelins combattaient aux c\xf4t\xe9s des orcs ; le clan Gueule-de-dragon utilisa l\u2019\xc2me des dragons d\u2019Aile-de-mort pour asservir des dragons rouges \xe0 Grim Batol ; Gul'dan cr\xe9a les premiers chevaliers de la mort. La Horde envahit Khaz Modan, incendia une partie de Quel'Thalas et assi\xe9gea la capitale de Lordaeron.","Au moment d\xe9cisif, Gul'dan trahit Marteau-du-Destin et prit la mer pour faire surgir la tombe de Sargeras, emmenant avec lui deux clans, les Stormreaver et le Marteau du cr\xe9puscule. Affaiblie, la Horde se replia sur le mont Rochenoire. Lors de la bataille du pic Rochenoire, Marteau-du-Destin tua Lothar, mais Turalyon, son lieutenant, brisa la Horde, et Khadgar d\xe9truisit la Porte des T\xe9n\xe8bres. Les orcs survivants furent parqu\xe9s dans des camps d\u2019internement. Dans les Riverglades de Forever, des ogres du Marteau du cr\xe9puscule et des orcs Stormreaver fuyant la tombe trouv\xe8rent un nouveau foyer."]}}},1593,[]);
__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"chapters2",{enumerable:!0,get:function(){return n}});const n={"chapter:beyond-the-dark-portal":{title:"Au-del\xe0 de la Porte des T\xe9n\xe8bres",summary:"Ner'zhul rouvrit la Porte et d\xe9chira Draenor, et Kil'jaeden fit du vieux chaman le roi-liche.",when:"Peu apr\xe8s la Deuxi\xe8me Guerre",body:["Gul'dan mort et la Horde emprisonn\xe9e, le vieux Ner'zhul rassembla les orcs rest\xe9s sur Draenor. Il rouvrit la Porte des T\xe9n\xe8bres et envoya des pillards sur Azeroth voler de puissants artefacts, dans l\u2019espoir d\u2019ouvrir des portails vers de nouveaux mondes o\xf9 son peuple pourrait s\u2019enfuir.","L\u2019Alliance r\xe9pondit par une exp\xe9dition \xe0 travers la Porte, sous les ordres de Turalyon et de Khadgar, rejoints par la foresti\xe8re Alleria Coursevent, le nain Kurdran Marteau-hardi et le guerrier Danath Trollemort. Ils combattirent la nouvelle Horde \xe0 travers tout Draenor, mais les portails de Ner'zhul d\xe9chiraient d\xe9j\xe0 le monde. Pour sauver Azeroth, l\u2019exp\xe9dition d\xe9truisit la Porte des T\xe9n\xe8bres depuis l\u2019autre c\xf4t\xe9, se pi\xe9geant elle-m\xeame dans les d\xe9bris de ce qui deviendrait l\u2019Outreterre.","Ner'zhul s\u2019\xe9chappa par l\u2019une de ses failles, droit entre les mains de Kil'jaeden. Le d\xe9mon lui arracha son corps mais garda son esprit, le lia \xe0 une armure enchant\xe9e et le scella dans un bloc de glace avec la lame runique Deuillegivre. Projet\xe9 dans les \xe9tendues glac\xe9es de Norfendre, le Tr\xf4ne de glace devint le si\xe8ge d\u2019une nouvelle puissance : le roi-liche, charg\xe9 de r\xe9pandre un fl\xe9au de non-mort et d\u2019affaiblir Azeroth en vue du retour de la L\xe9gion."]},"chapter:thrall-and-the-new-horde":{title:"Thrall et la nouvelle Horde",summary:"Un orc \xe9lev\xe9 en esclave s\u2019\xe9chappa de Durnholde, red\xe9couvrit le chamanisme et lib\xe9ra son peuple des camps d\u2019internement.",when:"Les ann\xe9es pr\xe9c\xe9dant la Troisi\xe8me Guerre",body:["Dans les camps d\u2019internement, les orcs sombr\xe8rent dans une \xe9trange l\xe9thargie \xe0 mesure que la fureur d\xe9moniaque les quittait. Lord Aedelas Blackmoore, du donjon de Durnholde dans les contreforts de Hautebrande, avait trouv\xe9 des ann\xe9es plus t\xf4t un nourrisson orc orphelin et l\u2019avait \xe9lev\xe9 comme gladiateur et future arme. Il nomma l\u2019enfant Thrall, un mot qui signifie esclave. Seule Taretha Foxton, une jeune servante, le traita avec bont\xe9, et c\u2019est gr\xe2ce \xe0 elle que Thrall finit par s\u2019\xe9vader.","Libre pour la premi\xe8re fois, Thrall partit \xe0 la recherche des l\xe9gendes de son propre peuple. Grom Hurlenfer lui montra ce qu\u2019un orc pouvait \xeatre, le vieil Orgrim Marteau-du-Destin fit de lui son second, et chez le clan Loup-de-givre, dans les montagnes d\u2019Alterac, le chaman Drek'Thar lui apprit \xe0 parler aux \xe9l\xe9ments. Il y d\xe9couvrit qu\u2019il \xe9tait le fils de Durotan, le chef des Loup-de-givre.","Thrall, Grom et Marteau-du-Destin lib\xe9r\xe8rent un camp apr\xe8s l\u2019autre. Marteau-du-Destin tomba au combat et transmit son armure noire et son marteau \xe0 Thrall, qui devint chef de guerre d\u2019une nouvelle Horde fond\xe9e sur l\u2019honneur et le chamanisme plut\xf4t que sur le sang d\xe9moniaque. \xc0 Durnholde, il vainquit Blackmoore, mais Taretha ne surv\xe9cut pas. D\xe9sormais, Thrall ne voulait plus qu\u2019une terre o\xf9 son peuple pourrait vivre en paix."]},"chapter:the-lich-king-and-the-plague":{title:"Le roi-liche et la peste",summary:"Depuis Norfendre, le roi-liche tendit la main vers le sud, et l\u2019archimage Kel'Thuzad r\xe9pandit une peste de non-mort par le grain de Lordaeron.",when:"\xc0 l\u2019approche de la Troisi\xe8me Guerre",body:["Prisonnier du Tr\xf4ne de glace, le roi-liche \xe9tendait pourtant son esprit sur tout Norfendre. Il conquit le royaume arachnide d\u2019Azjol-Nerub, en releva le peuple pour en faire ses serviteurs et b\xe2tit une forteresse autour de son tr\xf4ne, dans la Couronne de glace. Puis il tourna son regard vers le sud, vers les royaumes humains las de la guerre.","\xc0 Dalaran, le respect\xe9 archimage Kel'Thuzad \xe9tait devenu obs\xe9d\xe9 par la n\xe9cromancie. Quand le Kirin Tor rejeta ses travaux, il r\xe9pondit \xe0 l\u2019appel du roi-liche, se rendit en Norfendre et en revint en proph\xe8te. Il fonda le culte des Damn\xe9s, qui promettait aux pauvres de Lordaeron l\u2019\xe9galit\xe9 et la vie \xe9ternelle, et se servit de ses membres pour r\xe9pandre une peste cach\xe9e dans des cargaisons de grain.","La peste tuait ses victimes puis les relevait en morts-vivants sans volont\xe9 : le Fl\xe9au. Les villages du nord de Lordaeron tomb\xe8rent l\u2019un apr\xe8s l\u2019autre tandis que les royaumes se querellaient au sujet des imp\xf4ts et du co\xfbt des camps d\u2019internement. Quand le Kirin Tor et la Main d\u2019argent comprirent le danger, la peste s\u2019\xe9tait d\xe9j\xe0 r\xe9pandue dans les provinces septentrionales de Lordaeron. Des seigneurs de l\u2019effroi de la L\xe9gion ardente veillaient sur l\u2019\u0153uvre du roi-liche, car elle devait pr\xe9parer le retour de leurs ma\xeetres."]},"chapter:fall-of-lordaeron":{title:"La chute de Lordaeron",summary:"Le prince Arthas remonta la peste jusqu\u2019\xe0 sa source, s\u2019empara de Deuillegivre et revint d\xe9truire son propre royaume, Quel'Thalas et Dalaran.",when:"La Troisi\xe8me Guerre, environ 20 ans apr\xe8s la Porte des T\xe9n\xe8bres",body:["Le prince Arthas Menethil, jeune paladin de la Main d\u2019argent, partit avec la sorci\xe8re Jaina Portvaillant pour arr\xeater la peste. \xc0 Stratholme, il d\xe9couvrit que le grain de la ville \xe9tait d\xe9j\xe0 contamin\xe9 et ordonna d\u2019ex\xe9cuter ses habitants avant qu\u2019ils ne se rel\xe8vent en morts-vivants. Uther et Jaina refus\xe8rent de le suivre. Arthas poursuivit le seigneur de l\u2019effroi Mal'Ganis jusqu\u2019en Norfendre, br\xfbla ses propres navires pour que ses hommes ne puissent repartir et s\u2019empara de la lame runique Deuillegivre. L\u2019\xe9p\xe9e lui prit son \xe2me.","Arthas rentra chez lui en chevalier de la mort du roi-liche et assassina son p\xe8re, le roi Terenas, dans sa propre salle du tr\xf4ne. Le Fl\xe9au submergea Lordaeron. Uther tomba en d\xe9fendant l\u2019urne qui contenait les cendres de Terenas, et Arthas mena son arm\xe9e en Quel'Thalas, brisa les d\xe9fenses des elfes et se servit du Puits de soleil pour ramener Kel'Thuzad sous la forme d\u2019une liche. Sylvanas Coursevent, g\xe9n\xe9rale des forestiers de Lune-d\u2019argent, mourut en le combattant et fut relev\xe9e en banshee.","Kel'Thuzad invoqua ensuite le seigneur d\xe9mon Archimonde \xe0 Dalaran, et la L\xe9gion ardente revint sur Azeroth. Dalaran fut \xe9cras\xe9e, et Lordaeron, le plus grand des royaumes humains, n\u2019\xe9tait plus. Au nord ne restaient que des survivants \xe9pars, des r\xe9fugi\xe9s et des fanatiques, tandis que les morts-vivants d\u2019Arthas tenaient le pays."]},"chapter:battle-for-mount-hyjal":{title:"La bataille du mont Hyjal",summary:"Avertis par un proph\xe8te, orcs et humains firent voile vers Kalimdor, o\xf9 ils s\u2019unirent aux elfes de la nuit pour arr\xeater Archimonde au pied de l\u2019Arbre-Monde.",when:"La fin de la Troisi\xe8me Guerre",body:["Un myst\xe9rieux proph\xe8te, Medivh revenu d\u2019entre les morts, pressa Thrall et Jaina de faire voile vers l\u2019ouest, jusqu\u2019\xe0 Kalimdor. La Horde de Thrall d\xe9barqua sur ses rivages, se lia d\u2019amiti\xe9 avec les taurens de Cairne Sabot-de-Sang et se fraya un chemin \xe0 travers les Tarides, tandis que Jaina conduisait des r\xe9fugi\xe9s de Lordaeron vers le m\xeame continent. Dans les for\xeats d\u2019Orneval, Grom Hurlenfer et son clan Chanteguerre burent de nouveau le sang d\xe9moniaque et tu\xe8rent le demi-dieu Cenarius.","Thrall et Jaina unirent leurs forces pour la premi\xe8re fois afin de sauver Grom. Lors d\u2019un ultime duel, Grom terrassa Mannoroth, lib\xe9rant les orcs de la mal\xe9diction du sang au prix de sa propre vie. Pendant ce temps, Tyrande Murmevent r\xe9veilla les druides et lib\xe9ra Illidan des Barrow Deeps, esp\xe9rant que son pouvoir les aiderait. Au lieu de cela, il absorba le cr\xe2ne de Gul'dan, devint \xe0 moiti\xe9 d\xe9mon et fut banni par son propre fr\xe8re.","Archimonde marcha sur Nordrassil pour en drainer la puissance. Elfes de la nuit, humains et orcs tinrent ensemble les pentes du mont Hyjal, gagnant du temps pendant que Malfurion pr\xe9parait un pi\xe8ge. Lorsque le d\xe9mon atteignit l\u2019arbre, des milliers de feux follets fondirent sur lui et la puissance de Nordrassil le d\xe9chiqueta. L\u2019arm\xe9e de la L\xe9gion fut bris\xe9e, mais l\u2019Arbre-Monde \xe9tait gravement bless\xe9, et les elfes de la nuit perdirent l\u2019immortalit\xe9 qu\u2019il leur avait accord\xe9e."]},"chapter:rise-of-the-forsaken":{title:"L\u2019av\xe8nement des R\xe9prouv\xe9s",summary:"Tandis que le roi-liche faiblissait, Sylvanas Coursevent se lib\xe9ra avec d\u2019autres morts-vivants et revendiqua les ruines de Lordaeron au nom des R\xe9prouv\xe9s.",when:"Juste apr\xe8s la Troisi\xe8me Guerre",body:["Apr\xe8s la chute d\u2019Archimonde, l\u2019emprise du roi-liche commen\xe7a \xe0 se rel\xe2cher. Illidan, d\xe9sormais au service de Kil'jaeden, frappa le Tr\xf4ne de glace, et Arthas se h\xe2ta vers le nord pour d\xe9fendre son ma\xeetre. \xc0 Lordaeron, les seigneurs de l\u2019effroi tent\xe8rent de s\u2019approprier le Fl\xe9au, et dans le chaos, de nombreux morts-vivants retrouv\xe8rent leur libre arbitre.","Sylvanas Coursevent fut la premi\xe8re. Avec ses banshees et d\u2019autres morts-vivants libres, et avec le seigneur de l\u2019effroi Varimathras contraint de la servir, elle vainquit ses rivaux et revendiqua la capitale en ruine de Lordaeron. Dessous s\u2019\xe9tendaient les anciennes cryptes royales et les \xe9gouts, qui devinrent Fossoyeuse. Son peuple se nomma les R\xe9prouv\xe9s : plus tout \xe0 fait humains, rejet\xe9s par les vivants et lib\xe9r\xe9s du roi-liche.","Arthas atteignit la Couronne de glace, coiffa le heaume du roi-liche et fusionna avec lui sur le Tr\xf4ne de glace, puis se tut derri\xe8re la glace. Cern\xe9s d\u2019ennemis, les R\xe9prouv\xe9s rejoignirent la Horde de Thrall en alli\xe9s m\xe9fiants, tandis que le Fl\xe9au, la Croisade \xe9carlate et ce qui restait de la noblesse de Lordaeron se disputaient les Maleterres. L\u2019histoire de Forever reprend apr\xe8s la campagne \xab Forsaken Kingdom \xbb de Warcraft III: Reforged, dont ce guide ne couvre pas encore les \xe9v\xe9nements."],unknowns:["Ce qui se passe dans la campagne \xab Forsaken Kingdom \xbb de Warcraft III: Reforged, que Forever prolonge, n\u2019est pas d\xe9crit dans les sources de ce guide."]},"chapter:durotar-and-theramore":{title:"Durotar et Theramore",summary:"Thrall fonda Durotar et Orgrimmar, Jaina b\xe2tit Theramore, et tous deux maintinrent une paix fragile, m\xeame lorsque le p\xe8re de Jaina vint faire la guerre.",when:"Les ann\xe9es qui suivirent la Troisi\xe8me Guerre",body:["Apr\xe8s Hyjal, Thrall conduisit les orcs vers une rude terre rouge sur la c\xf4te est de Kalimdor et la nomma Durotar, en hommage \xe0 son p\xe8re. Leur capitale, Orgrimmar, honorait Orgrim Marteau-du-Destin. Les taurens de Cairne Sabot-de-Sang s\u2019\xe9tablirent dans les prairies de Mulgore, autour des mesas des Pitons-du-Tonnerre, et les trolls Sombrelance de Vol'jin, que Thrall avait secourus pendant son voyage vers l\u2019ouest, s\u2019install\xe8rent sur les \xeeles de l\u2019\xc9cho, au large de Durotar.","Jaina Portvaillant fonda Theramore sur une \xeele du mar\xe9cage d\u2019\xc2prefange pour les survivants humains qu\u2019elle avait ramen\xe9s de Lordaeron. Elle et Thrall avaient combattu c\xf4te \xe0 c\xf4te \xe0 Hyjal, et ils convinrent de pr\xe9server la paix. Cette paix fut mise \xe0 l\u2019\xe9preuve quand son p\xe8re, le grand amiral Daelin Portvaillant de Kul Tiras, arriva avec sa flotte, r\xe9solu \xe0 d\xe9truire les orcs.","Daelin attaqua la c\xf4te de Durotar. Rexxar, un vagabond demi-ogre des Mok'Nathal devenu le champion de la Horde, unit orcs, trolls et taurens contre lui, et Jaina, d\xe9chir\xe9e entre son peuple et son p\xe8re, laissa la Horde frapper ses troupes \xe0 Theramore. Daelin p\xe9rit dans la bataille. Jaina le pleura mais tint parole, et la tr\xeave fragile entre Theramore et Orgrimmar devint l\u2019un des rares ponts entre l\u2019Alliance et la Horde."]},"chapter:stormwind-in-shadow":{title:"Hurlevent dans l\u2019ombre",summary:"Reb\xe2tie, Hurlevent doit faire face \xe0 une guilde de ma\xe7ons trahie, \xe0 un roi disparu et \xe0 un dragon cach\xe9 \xe0 la cour, tandis que les gnomes ont perdu leur cit\xe9.",when:"An 25 apr\xe8s la Porte des T\xe9n\xe8bres",body:["Apr\xe8s la Deuxi\xe8me Guerre, la guilde des Tailleurs de pierre d\u2019Edwin VanCleef reb\xe2tit la cit\xe9 de Hurlevent sur ses cendres. Une fois le travail achev\xe9, la Chambre des nobles refusa de les payer. Les ma\xe7ons se soulev\xe8rent, furent chass\xe9s et devinrent la Confr\xe9rie d\xe9fias, qui s\u2019en prend d\xe9sormais \xe0 la marche de l\u2019Ouest depuis des mines cach\xe9es et complote contre la couronne.","Le roi Varian Wrynn, l\u2019enfant que Lothar avait jadis sauv\xe9, disparut en se rendant \xe0 une rencontre diplomatique \xe0 Theramore ; la rumeur veut que les D\xe9fias l\u2019aient enlev\xe9 et retenu sur l\u2019\xeele d\u2019Alcaz. Son jeune fils Anduin fut couronn\xe9, avec le g\xe9n\xe9ralissime Bolvar Fordragon pour r\xe9gent. \xc0 la cour, une gracieuse noble, dame Katrana Prestor, gagna une grande influence. Elle \xe9tait en v\xe9rit\xe9 Onyxia, fille d\u2019Aile-de-mort, qui menait discr\xe8tement le royaume \xe0 sa perte.","L\u2019Alliance a chang\xe9. Lordaeron est perdu, et les elfes de la nuit ont rejoint l\u2019Alliance apr\xe8s Hyjal. \xc0 Dun Morogh, des troggs ont surgi des profondeurs et envahi Gnomeregan ; la tentative d\xe9sesp\xe9r\xe9e des gnomes de les d\xe9loger par la radiation a empoisonn\xe9 leur propre cit\xe9, et le Grand Mekanicien Mekkanivelle a conduit les survivants \xe0 l\u2019abri de Forgefer. Le roi Magni Barbe-de-bronze y r\xe8gne, et sa Ligue des explorateurs fouille le monde entier \xe0 la recherche des secrets des titans."]},"chapter:fire-beneath-blackrock":{title:"Le feu sous Rochenoire",summary:"Au mont Rochenoire, les nains Sombrefer servent Ragnaros tandis que les orcs de Nefarian tiennent le pic au-dessus, et Onyxia garde sa couv\xe9e dans le mar\xe9cage d\u2019\xc2prefange.",when:"An 25 apr\xe8s la Porte des T\xe9n\xe8bres",body:["Deux si\xe8cles apr\xe8s l\u2019erreur de Thaurissan, ses descendants r\xe8gnent toujours sous le mont Rochenoire. L\u2019empereur Dagran Thaurissan tient sa cour dans la cit\xe9 sombrefer d\u2019Ombreforge, au fond des profondeurs de Rochenoire, tandis que Ragnaros br\xfble plus bas dans le c\u0153ur du Magma et que les nains peinent pour lui. La princesse Moira Barbe-de-bronze, fille du roi Magni, arriva dans la montagne en captive et y resta comme \xe9pouse de l\u2019empereur, \xe0 la fureur de son p\xe8re.","Les salles sup\xe9rieures appartiennent au vol noir. Nefarian, fils d\u2019Aile-de-mort, r\xe8gne sur le repaire de l\u2019Aile noire sous l\u2019apparence du seigneur Victor Nefarius et commande les orcs Rochenoire qui ne rejoignirent jamais Thrall, men\xe9s par le chef de guerre Rend Main-Noire au pic Rochenoire. Le feu et l\u2019ombre se livrent une guerre froide au sein de la m\xeame montagne, et les steppes Ardentes comme la gorge des Vents br\xfblants en p\xe2tissent.","La s\u0153ur de Nefarian, Onyxia, la fausse dame Prestor, a son repaire dans le mar\xe9cage d\u2019\xc2prefange, o\xf9 elle garde sa couv\xe9e. Pour l\u2019atteindre, il faut l\u2019amulette de Flammedrake, obtenue au terme d\u2019une longue suite de qu\xeates propre \xe0 chaque faction qui passe par le pic Rochenoire. Dans Forever, le repaire d\u2019Onyxia est l\u2019un des trois raids qui ouvrent le 9 d\xe9cembre, aux c\xf4t\xe9s de deux nouveaux raids sur le mont Hyjal."]},"chapter:plaguelands-and-the-scarlet-crusade":{title:"Les Maleterres et la Croisade \xe9carlate",summary:"Le Fl\xe9au de Kel'Thuzad tient le nord, les fanatiques de la Croisade \xe9carlate combattent morts-vivants et vivants, et quelques ordres in\xe9branlables tiennent bon.",when:"An 25 apr\xe8s la Porte des T\xe9n\xe8bres",body:["Le c\u0153ur de Lordaeron forme d\xe9sormais les Maleterres. Kel'Thuzad y commande le Fl\xe9au depuis la n\xe9cropole flottante de Naxxramas, le baron Vaillefendre r\xe8gne sur les morts-vivants de Stratholme en ruine, et dans l\u2019ancienne \xe9cole de la famille Barov, Scholomance, le culte des Damn\xe9s forme de nouveaux n\xe9cromanciens.","Les survivants de la Main d\u2019argent se regroup\xe8rent au sein de la Croisade \xe9carlate, qui a jur\xe9 de purger la terre de la peste par le feu. Son grand crois\xe9, Saidan Dathrohan, est en secret le seigneur de l\u2019effroi Balnazzar, et la Croisade est devenue si fanatique qu\u2019elle tue tout \xe9tranger soup\xe7onn\xe9 de souillure. Parmi ses bastions figurent le monast\xe8re \xc9carlate dans les clairi\xe8res de Tirisfal, \xc2treval, la Main de Tyr et une place forte \xe0 Stratholme. M\xeame ses h\xe9ros portent des histoires plus sombres : Renault Mograine a trahi son p\xe8re Alexandros, le Porte-cendres, et l\u2019a livr\xe9 \xe0 la mort.","Tous les paladins ne devinrent pas des fanatiques. Ceux qui refusaient la cruaut\xe9 de la Croisade fond\xe8rent l\u2019Aube d\u2019argent, qui travaille avec quiconque combat le Fl\xe9au depuis la chapelle de l\u2019Espoir de Lumi\xe8re. Le paladin exil\xe9 Tirion Fordring vit en ermite pr\xe8s d\u2019\xc2treval, et les R\xe9prouv\xe9s poussent vers le nord depuis Tirisfal. Le sort de Lordaeron n\u2019est pas encore scell\xe9."]},"chapter:azeroth-in-year-twenty-five":{title:"Azeroth en l\u2019an 25",summary:"Le monde de la premi\xe8re ann\xe9e de World of Warcraft, o\xf9 se d\xe9roule l\u2019histoire de Forever : une paix fragile, de vieilles menaces qui s\u2019\xe9veillent et de nouveaux lieux sur la carte.",when:"An 25 : l\u2019\xe9poque de Forever",body:["Vingt-cinq ans apr\xe8s la premi\xe8re ouverture de la Porte des T\xe9n\xe8bres, Azeroth est un monde de survivants. L\u2019Alliance de Hurlevent, de Forgefer, des gnomes et des elfes de la nuit fait face \xe0 une Horde d\u2019orcs, de trolls, de taurens et de R\xe9prouv\xe9s, et aucun camp ne fait confiance \xe0 l\u2019autre. De vieux ennemis s\u2019\xe9veillent aux confins de la carte : les serviteurs du Dieu tr\xe8s ancien C'Thun en Silithus, les pr\xeatres du dieu du sang Hakkar dans les ruines trolls du sud, et la corruption du Cauchemar d\u2019\xe9meraude qui s\u2019insinue dans les r\xeaves des druides.","World of Warcraft: Forever se d\xe9roule pr\xe9cis\xe9ment \xe0 ce moment. Blizzard l\u2019y maintient ind\xe9finiment, apr\xe8s la campagne \xab Forsaken Kingdom \xbb de Warcraft III: Reforged et avant The Burning Crusade, et pr\xe9cise que son histoire ne partage pas la continuit\xe9 du World of Warcraft actuel. Forever ajoute des lieux que le jeu d\u2019origine n\u2019a jamais eus : les Riverglades \xe0 l\u2019est des Terres ingrates, o\xf9 Farholde Keep r\xe9siste au Marteau du cr\xe9puscule ; une Dalaran en restauration dont la barri\xe8re protectrice est tomb\xe9e ; et des donjons allant des tombes royales du Hall of Thanes \xe0 l\u2019installation titanique de Shaper's Terrace.","Forever ouvre aussi un nouveau peuple aux joueurs : les Skyborne de Zephras Isle, une \xeele qui flotte dans Skywall, le plan \xc9l\xe9mentaire de l\u2019Air. Ses \xe9l\xe9mentaires d\u2019air ont disparu il y a des si\xe8cles et la magie qui maintient l\u2019\xeele dans les airs faiblit ; son High Order sert l\u2019Alliance et ses Windshapers la Horde. La fin de ces histoires reste \xe0 \xe9crire. Blizzard a annonc\xe9 de nouveaux raids, des donjons et une suite de qu\xeates l\xe9gendaire pour 2027, et les raids du mont Hyjal ouvrent le 9 d\xe9cembre."]},"chapter:after-classic":{title:"\xc9pilogue : apr\xe8s Classic",summary:"Dans la chronologie d\u2019origine, l\u2019histoire se poursuivit en Outreterre, en Norfendre et au-del\xe0 ; Forever reste en l\u2019an 25 et raconte la sienne.",when:"Extensions ult\xe9rieures (hors de Forever)",body:["Dans la chronologie d\u2019origine de World of Warcraft, l\u2019histoire continua d\u2019avancer. La Porte des T\xe9n\xe8bres se rouvrit, et The Burning Crusade mena les aventuriers en Outreterre, o\xf9 Illidan et Kael'thas Haut-Soleil tomb\xe8rent. Dans Wrath of the Lich King, l\u2019Alliance et la Horde march\xe8rent sur Norfendre, et Arthas fut vaincu au sommet de la citadelle de la Couronne de glace. Dans Cataclysm, Aile-de-mort jaillit des profondeurs et brisa la face du monde avant que les Aspects et leurs alli\xe9s mortels ne l\u2019abattent.","Les extensions suivantes emmen\xe8rent la saga en Pandarie, sur un Draenor alternatif, jusqu\u2019\xe0 la d\xe9faite finale de la L\xe9gion ardente sur Argus, dans une guerre ouverte entre les factions, dans les royaumes des morts, sur les \xeeles aux Dragons et dans la longue lutte autour de l\u2019\xe2me-monde d\u2019Azeroth elle-m\xeame. Bien des lieux de ce guide chang\xe8rent au point d\u2019en devenir m\xe9connaissables.","World of Warcraft: Forever ne prend aucune de ces routes. Il reste en l\u2019an 25, dans une \xab bulle temporelle \xbb hors de la continuit\xe9 du jeu actuel, et b\xe2tit son avenir sur les fondations du monde d\u2019origine. La feuille de route de Blizzard promet pour 2027 de nouveaux raids, des donjons, des qu\xeates et un raid embl\xe9matique remani\xe9 : les prochains chapitres de cette histoire appartiendront \xe0 Forever seul."]}}},1594,[]);
__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"classes",{enumerable:!0,get:function(){return s}});const s={"class:mage":{title:"Mage",summary:"H\xe9ritiers des Bien-n\xe9s et des premiers mages humains, les mages plient la puissance arcanique brute, et chaque \xe9poque de l\u2019histoire repose sur l\u2019un d\u2019eux.",body:["Les mages manient les arcanes, la magie brute de l\u2019ordre qui jaillissait autrefois du Puits d\u2019\xe9ternit\xe9. Les Bien-n\xe9s des elfes de la nuit furent les premiers grands sorciers, et leurs descendants exil\xe9s, les hauts-elfes de Quel'Thalas, enseign\xe8rent cet art \xe0 cent humains pendant les guerres des Trolls. Ces premiers mages humains fond\xe8rent ensuite Dalaran, o\xf9 le Kirin Tor garde encore les secrets de l\u2019art des sorts.","Chaque \xe9poque de l\u2019histoire repose sur un mage : Medivh, le dernier Gardien ; son apprenti Khadgar, qui d\xe9truisit la Porte des T\xe9n\xe8bres ; l\u2019archimage Antonidas, mort en d\xe9fendant Dalaran ; et Jaina Portvaillant, qui r\xe8gne aujourd\u2019hui sur Theramore. En l\u2019an 25, de nouveaux \xe9l\xe8ves se forment dans le quartier des Mages de Hurlevent et dans le quartier de la Magie de Fossoyeuse, et les mages gnomes et trolls se tiennent depuis longtemps aux c\xf4t\xe9s des humains et des R\xe9prouv\xe9s. Forever ouvre cette voie aux orcs, dont les lanceurs de sorts ne connaissaient jadis que le chamanisme et la magie gangren\xe9e, ainsi qu\u2019au High Order, les seuls Skyborne \xe0 pouvoir devenir mages."]},"class:warrior":{title:"Guerrier",summary:"Chaque peuple d\u2019Azeroth a ses guerriers, et une grande partie de l\u2019histoire du monde a \xe9t\xe9 \xe9crite avec leur acier.",body:["Chaque peuple d\u2019Azeroth a ses guerriers, et une grande partie de son histoire a \xe9t\xe9 \xe9crite avec leur acier. Les soldats d\u2019Arathor tinrent le mur de Thoradin face aux Amani ; des thanes nains combattirent pour Forgefer pendant la guerre des Trois Marteaux ; les clans orcs vivaient de la force de leurs champions bien avant que la Horde ne soit forg\xe9e. Les guerriers se fient \xe0 l\u2019entra\xeenement, \xe0 l\u2019armure et \xe0 la fureur du combat plut\xf4t qu\u2019aux sorts.","Leurs h\xe9ros emplissent les chroniques : Anduin Lothar, le Lion d\u2019Azeroth, qui mena l\u2019Alliance jusqu\u2019\xe0 sa chute au pic Rochenoire ; Grom Hurlenfer, dont le sacrifice sur le mont Hyjal lib\xe9ra les orcs du sang d\xe9moniaque ; et Danath Trollemort, rest\xe9 sur Draenor avec l\u2019exp\xe9dition de l\u2019Alliance. En l\u2019an 25, les guerriers servent sous toutes les banni\xe8res, des gardes de Hurlevent aux grunts d\u2019Orgrimmar, et toutes les races jouables peuvent prendre les armes. Forever ajoute \xe0 leurs rangs les Skyborne des deux ordres."]},"class:paladin":{title:"Paladin",summary:"Guerriers saints n\xe9s pendant la Deuxi\xe8me Guerre, les paladins de la Main d\u2019argent furent bris\xe9s par l\u2019un des leurs et combattent d\xe9sormais sous de nouvelles banni\xe8res.",body:["Les paladins sont des guerriers-pr\xeatres de la Lumi\xe8re sacr\xe9e. L\u2019archev\xeaque Alonsus Faol fonda leur ordre, les chevaliers de la Main d\u2019argent, pendant la Deuxi\xe8me Guerre, afin de donner \xe0 l\u2019Alliance des champions capables de soigner autant que de combattre. Uther le Porteur de Lumi\xe8re fut le premier d\u2019entre eux, et Turalyon, Tirion Fordring et le prince Arthas Menethil pr\xeat\xe8rent tous serment.","L\u2019ordre fut bris\xe9 par l\u2019un des siens. Arthas assassina Uther et contribua \xe0 d\xe9truire Lordaeron, et les survivants de la Main d\u2019argent se dispers\xe8rent : d\u2019un c\xf4t\xe9 les fanatiques de la Croisade \xe9carlate, de l\u2019autre l\u2019Aube d\u2019argent et Tirion l\u2019exil\xe9. Les nains de Forgefer portent eux aussi la Lumi\xe8re au combat. Le changement le plus surprenant de Forever est que les R\xe9prouv\xe9s peuvent d\xe9sormais devenir paladins, m\xeame si les sources utilis\xe9es ici n\u2019expliquent pas encore comment des morts-vivants en sont venus \xe0 manier la Lumi\xe8re."],unknowns:["Les sources de ce guide n\u2019expliquent pas comment les paladins r\xe9prouv\xe9s en sont venus \xe0 manier la Lumi\xe8re dans Forever."]},"class:hunter":{title:"Chasseur",summary:"Forestiers, fusiliers et ma\xeetres des b\xeates, les chasseurs vivent de l\u2019arc, du fusil et du lien avec un animal fid\xe8le.",body:["Les chasseurs vivent de l\u2019arc, du fusil et du lien avec une b\xeate. Les forestiers de Quel'Thalas, men\xe9s pendant des g\xe9n\xe9rations par la famille Coursevent, gardaient les for\xeats elfiques ; les fusiliers nains et les chevaucheurs de griffon des Marteau-hardi combattirent pendant la Deuxi\xe8me Guerre ; les Sentinelles elfes de la nuit et les chasseurs de t\xeates trolls arpentent les bois de Kalimdor et de Strangleronce.","Certains des survivants les plus tenaces de l\u2019histoire sont des chasseurs. Alleria Coursevent partit au-del\xe0 de la Porte des T\xe9n\xe8bres et ne revint jamais, sa s\u0153ur Sylvanas combattit Arthas jusqu\u2019\xe0 son dernier souffle, et le ma\xeetre des b\xeates Rexxar devint le champion de la Horde contre Daelin Portvaillant. Dans Forever, les humains peuvent eux aussi embrasser cette vocation, et les deux ordres skyborne comptent des chasseurs parmi leur peuple."]},"class:rogue":{title:"Voleur",summary:"Espions, voleurs et assassins, les voleurs agissent l\xe0 o\xf9 l\u2019honneur h\xe9siterait, et certaines de leurs guildes ont discr\xe8tement fa\xe7onn\xe9 l\u2019histoire.",body:["Les voleurs agissent l\xe0 o\xf9 l\u2019honneur h\xe9siterait. Voleurs, espions et assassins existent dans chaque cit\xe9, mais certaines de leurs organisations fa\xe7onnent l\u2019histoire : le service de renseignement de Hurlevent, le SI:7, dirig\xe9 par Mathias Shaw ; les assassins de Ravenholdt, cach\xe9s dans les montagnes d\u2019Alterac ; le Syndicat, n\xe9 de la noblesse d\xe9chue d\u2019Alterac ; et la Confr\xe9rie d\xe9fias, qui hante la marche de l\u2019Ouest.","La voleuse la plus c\xe9l\xe8bre des premi\xe8res guerres fut Garona Halforcen, l\u2019espionne demi-orque dont la lame tua le roi Llane. En l\u2019an 25, des ma\xeetres voleurs enseignent dans la vieille ville de Hurlevent et dans le quartier des Voleurs de Fossoyeuse, et toutes les races jouables sauf les taurens peuvent apprendre le m\xe9tier. Forever ajoute aux ombres les Skyborne des deux ordres."]},"class:priest":{title:"Pr\xeatre",summary:"Les pr\xeatres servent la Lumi\xe8re sacr\xe9e, la d\xe9esse lunaire \xc9lune ou des puissances plus anciennes et plus sombres ; ils soignent leurs alli\xe9s et, quand il le faut, an\xe9antissent leurs ennemis.",body:["Les pr\xeatres servent la foi sous bien des formes. L\u2019\xc9glise de la Lumi\xe8re sacr\xe9e des humains, centr\xe9e sur la cath\xe9drale de la Lumi\xe8re de Hurlevent et jadis dirig\xe9e par l\u2019archev\xeaque Alonsus Faol, enseigne que la Lumi\xe8re r\xe9side dans la vertu plut\xf4t que dans un dieu unique, et les nains l\u2019ont eux aussi embrass\xe9e. Les pr\xeatresses elfes de la nuit servent la d\xe9esse lunaire \xc9lune au sein d\u2019une confr\xe9rie que Tyrande Murmevent dirige depuis la guerre des Anciens.","D\u2019autres suivent des voies plus sombres. Les pr\xeatres des R\xe9prouv\xe9s entretiennent une foi aust\xe8re qui leur est propre, les pr\xeatres trolls honorent les loas de leurs anc\xeatres, et la magie de l\u2019ombre fait partie de l\u2019art de nombreux pr\xeatres. Dans Forever, les gnomes, longtemps connus comme un peuple d\u2019ing\xe9nieurs, peuvent devenir pr\xeatres pour la premi\xe8re fois, et Blizzard leur a donn\xe9 des sorts de pr\xeatre raciaux bien \xe0 eux."]},"class:shaman":{title:"Chaman",summary:"Les chamans demandent l\u2019aide des esprits de la terre, du feu, de l\u2019eau et de l\u2019air ; perdue pour les orcs pendant une g\xe9n\xe9ration, la tradition fut restaur\xe9e par Thrall.",body:["Les chamans parlent aux esprits de la terre, du feu, de l\u2019eau et de l\u2019air, et ils demandent plut\xf4t qu\u2019ils n\u2019ordonnent. Sur Draenor, les chamans orcs guidaient leur peuple jusqu\u2019\xe0 ce que la corruption de Ner'zhul les remplace par des d\xe9monistes, et pendant une g\xe9n\xe9ration les \xe9l\xe9ments ne r\xe9pondirent plus du tout aux orcs. Thrall restaura la tradition, instruit par Drek'Thar des Loup-de-givre, et reb\xe2tit la Horde autour d\u2019elle.","Les taurens de Mulgore et les trolls Sombrelance perp\xe9tuent leurs propres coutumes chamaniques, et Thrall dirige toujours les chamans d\u2019Orgrimmar. Forever ajoute deux nouveaux venus : les nains, qui n\u2019avaient pas de chamans dans le jeu d\u2019origine, et les Skyborne windshapers de Zephras Isle, dont l\u2019\xeele flotte dans Skywall, le plan \xc9l\xe9mentaire de l\u2019Air."],unknowns:["Les sources de ce guide n\u2019expliquent pas comment les nains se sont tourn\xe9s vers le chamanisme dans Forever."]},"class:warlock":{title:"D\xe9moniste",summary:"Ma\xeetres de la magie gangren\xe9e et des d\xe9mons asservis, les d\xe9monistes arriv\xe8rent sur Azeroth avec la Horde et marchent sur une ligne \xe9troite entre puissance et perdition.",body:["Les d\xe9monistes tirent leur pouvoir de la magie gangren\xe9e et soumettent les d\xe9mons \xe0 leur volont\xe9. Cet art arriva sur Azeroth avec la Horde : Kil'jaeden l\u2019enseigna \xe0 Gul'dan, dont le Conseil des ombres fit des chamans orcs des d\xe9monistes et \xe9puisa la vie de Draenor pour alimenter leurs sorts. Les chevaliers de la mort et la mal\xe9diction du sang d\xe9moniaque compt\xe8rent parmi ses fruits les plus sombres.","Tous les d\xe9monistes ne servent pas la L\xe9gion. Les d\xe9monistes humains se r\xe9unissent en secret sous la taverne de l\u2019Agneau \xe9gorg\xe9, \xe0 Hurlevent, les gnomes et les R\xe9prouv\xe9s \xe9tudient cet art, et la Horde de Thrall tol\xe8re avec m\xe9fiance ses d\xe9monistes orcs. Chaque d\xe9moniste suit la m\xeame ligne de cr\xeate : le pouvoir est r\xe9el, tout comme le risque d\u2019en \xeatre consum\xe9. Dans Forever, les trolls peuvent eux aussi devenir d\xe9monistes."]},"class:druid":{title:"Druide",summary:"Gardiens m\xe9tamorphes de la nature, form\xe9s d\u2019abord par le demi-dieu Cenarius, les druides pr\xe9servent l\u2019\xe9quilibre du monde, de Reflet-de-Lune au R\xeave d\u2019\xe9meraude.",body:["Les druides veillent sur l\u2019\xe9quilibre de la nature et peuvent prendre la forme de b\xeates. Malfurion Hurlorage apprit cet art aupr\xe8s du demi-dieu Cenarius et devint le premier druide ; ses disciples dormirent des si\xe8cles durant dans le R\xeave d\u2019\xe9meraude pendant que les Sentinelles veillaient sur les for\xeats des elfes de la nuit. Le Cercle c\xe9narien, \xe9tabli dans la clairi\xe8re sacr\xe9e de Reflet-de-Lune, rassemble aujourd\u2019hui des druides de toutes les races.","Apr\xe8s la Troisi\xe8me Guerre, Malfurion enseigna les arts druidiques aux taurens, et Hamuul Totem-runique devint le premier druide tauren. En l\u2019an 25, les druides ont de graves sujets d\u2019inqui\xe9tude : l\u2019Arbre-Monde Nordrassil est bless\xe9, Teldrassil a pouss\xe9 sans la b\xe9n\xe9diction des Aspects, et un cauchemar se r\xe9pand dans le R\xeave d\u2019\xe9meraude. Dans Forever, les deux ordres skyborne comptent des druides parmi leur peuple."]}}},1595,[]);
__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"races",{enumerable:!0,get:function(){return s}});const s={"race:human":{title:"Humains",summary:"H\xe9ritiers d\u2019Arathor et pilier de l\u2019Alliance, les humains ont pay\xe9 le prix de chaque guerre de l\u2019histoire d\u2019Azeroth et reb\xe2tissent malgr\xe9 tout.",body:["Les humains descendent des tribus que le roi Thoradin unit au sein d\u2019Arathor pr\xe8s de trois mille ans avant la Porte des T\xe9n\xe8bres. Les h\xe9ritiers d\u2019Arathor fond\xe8rent les sept royaumes humains, les elfes form\xe8rent leurs premiers mages, et leur foi en la Lumi\xe8re sacr\xe9e donna plus tard naissance aux paladins. L\u2019humanit\xe9 porta l\u2019Alliance \xe0 travers la Premi\xe8re, la Deuxi\xe8me et la Troisi\xe8me Guerre, et le paya cher : Hurlevent br\xfbla une fois, et Lordaeron tomba aux mains du Fl\xe9au.","En l\u2019an 25, Hurlevent est le c\u0153ur de la puissance humaine, reb\xe2tie en pierre blanche mais troubl\xe9e par les D\xe9fias, la disparition du roi Varian et une cour envo\xfbt\xe9e par dame Prestor. Les nouveaux humains commencent \xe0 l\u2019abbaye de Comt\xe9-du-Nord, dans la for\xeat d\u2019Elwynn. Forever permet aux humains de devenir chasseurs, une vocation que le jeu d\u2019origine r\xe9servait \xe0 d\u2019autres races."]},"race:gnome":{title:"Gnomes",summary:"Bricoleurs de g\xe9nie dont les anc\xeatres \xe9taient des machines forg\xe9es par les titans, les gnomes ont perdu leur cit\xe9 de Gnomeregan et vivent en exil \xe0 Forgefer.",body:["Les gnomes sont petits par la taille et immenses par l\u2019ing\xe9niosit\xe9. Leurs anc\xeatres, les m\xe9cagnomes, \xe9taient des machines forg\xe9es par les titans, frapp\xe9es plus tard par la mal\xe9diction de la chair, qui les changea en \xeatres vivants. \xc0 Dun Morogh, ils b\xe2tirent Gnomeregan, une cit\xe9 d\u2019engrenages et de vapeur, et devinrent les fid\xe8les alli\xe9s des nains de Forgefer toute proche, aux c\xf4t\xe9s desquels ils combattirent pendant la Deuxi\xe8me Guerre.","Cette cit\xe9 est perdue. Des troggs ont surgi des profondeurs, et le conseil du Mekg\xe9nieur Sicco Thermojoncteur, inonder Gnomeregan de radiations, l\u2019a empoisonn\xe9e \xe0 la place ; de nombreux gnomes sont morts, et certains survivants sont devenus des gnomes l\xe9preux difformes. Le Grand Mekanicien Gelbin Mekkanivelle a men\xe9 les autres en exil \xe0 Forgefer, tandis que Thermojoncteur r\xe8gne sur les ruines. Forever ouvre pour la premi\xe8re fois la pr\xeatrise aux gnomes."]},"race:night-elf":{title:"Elfes de la nuit",summary:"Les antiques kaldorei veill\xe8rent sur Kalimdor pendant dix mille ans ; d\xe9sormais mortels, ils ont plant\xe9 un nouvel Arbre-Monde et rejoint l\u2019Alliance.",body:["Les elfes de la nuit, ou kaldorei, sont le plus ancien des peuples jouables. Descendants de trolls transform\xe9s par le Puits d\u2019\xe9ternit\xe9, ils b\xe2tirent un empire de magie, surv\xe9curent \xe0 la guerre des Anciens et v\xe9curent dix mille ans en peuple reclus de druides et de Sentinelles, \xe0 l\u2019ombre du mont Hyjal. La magie arcanique leur reste interdite.","La Troisi\xe8me Guerre leur co\xfbta leur immortalit\xe9, quand Nordrassil fut bless\xe9 pour d\xe9truire Archimonde. Malfurion \xe9tant perdu dans le R\xeave d\u2019\xe9meraude, l\u2019archidruide Fandral Forteramure fit pousser un nouvel Arbre-Monde, Teldrassil, au large de Sombrivage, et la capitale Darnassus s\u2019\xe9leva dans ses branches. Sous la conduite de Tyrande Murmevent, les elfes de la nuit rejoignirent l\u2019Alliance. Les nouveaux elfes de la nuit commencent dans les clairi\xe8res de Teldrassil."]},"race:dwarf":{title:"Nains",summary:"Enfants des terrestres des titans, les nains de Forgefer sont des alli\xe9s t\xeatus, des explorateurs infatigables et les gardiens d\u2019un h\xe9ritage divis\xe9.",body:["Les nains sont t\xeatus, chaleureux et n\xe9s de la pierre : leurs anc\xeatres \xe9taient les terrestres, des gardiens forg\xe9s par les titans que la mal\xe9diction de la chair transforma. Forgefer, creus\xe9e dans une montagne de Dun Morogh, est leur capitale depuis des \xe2ges. La guerre des Trois Marteaux divisa les clans : les Barbe-de-bronze gard\xe8rent la cit\xe9, les Marteau-hardi s\u2019install\xe8rent dans les Hinterlands et les Sombrefer pass\xe8rent au service de Ragnaros.","Sous le roi Magni Barbe-de-bronze, les nains ont combattu dans chaque guerre de l\u2019Alliance, et la Ligue des explorateurs, dont son fr\xe8re Brann est une figure de proue, fouille des ruines titaniques comme Uldaman \xe0 la recherche des origines des nains. Moira, la fille de Magni, est devenue l\u2019\xe9pouse de l\u2019empereur sombrefer, une blessure que le roi vit comme une affaire personnelle. Forever ajoute le Hall of Thanes sous Forgefer, lieu de repos des souverains nains, aujourd\u2019hui forc\xe9 par des intrus que l\u2019on pense sombrefer, et les nains peuvent suivre la voie du chaman."]},"race:skyborne-high-order":{title:"Skyborne : High Order",body:["Les Skyborne sont le nouveau peuple jouable de World of Warcraft: Forever, et le High Order est la branche qui se tient aux c\xf4t\xe9s de l\u2019Alliance. Leur foyer est Zephras Isle, une \xeele qui flotte dans Skywall, le plan \xc9l\xe9mentaire de l\u2019Air ; elle est gouvern\xe9e par la Grande Ancienne Talaanis Shadowsong, et son principal \xe9tablissement est la ville de Valanaar. Les \xe9l\xe9mentaires d\u2019air qui vivaient autrefois sur l\u2019\xeele avec les Skyborne ont disparu il y a des si\xe8cles, la magie qui la soutient s\u2019affaiblit, et le contact avec les \xeeles s\u0153urs d\u2019Anvilas et de Siroccas est rompu tandis que des r\xe9fugi\xe9s affluent vers Zephras.","Les aventuriers du High Order quittent l\u2019\xeele en a\xe9ronef, de Valanaar jusqu\u2019\xe0 Dalaran dans les montagnes d\u2019Alterac. Ils peuvent \xeatre guerriers, chasseurs, voleurs, druides ou mages, et ce sont les seuls Skyborne \xe0 \xe9tudier les arcanes. Leurs dons refl\xe8tent leur foyer : ils descendent en planant sur le vent, agissent avec une h\xe2te accrue, frappent plus fort les \xe9l\xe9mentaires et lisent les lignes telluriques proches pour rendre de la vie et du mana. Pour les jouer, il faut le Skyborne Heroic ou Epic Pack, en option."]},"race:skyborne-windshaper":{title:"Skyborne : Windshapers",body:["Les Windshapers sont les Skyborne qui se tiennent aux c\xf4t\xe9s de la Horde. Comme le High Order, ils viennent de Zephras Isle dans Skywall, le plan \xc9l\xe9mentaire de l\u2019Air, une \xeele dont les \xe9l\xe9mentaires d\u2019air ont disparu il y a des si\xe8cles et dont la magie qui la soutient faiblit peu \xe0 peu. Tandis que des \xeeles comme Anvilas et Siroccas se taisent, les r\xe9fugi\xe9s s\u2019entassent sur Zephras, et m\xeame Zephras a commenc\xe9 \xe0 se d\xe9sagr\xe9ger.","Les Windshapers quittent Valanaar en a\xe9ronef pour le Skywatcher Plateau, en Mulgore. Ils peuvent \xeatre guerriers, chasseurs, voleurs, druides ou chamans, et ce sont les seuls Skyborne \xe0 suivre la voie du chaman. Ils planent sur le vent, combattent avec une h\xe2te accrue et frappent plus fort les \xe9l\xe9mentaires, et leur propre don, Skysight, acc\xe9l\xe8re leurs d\xe9placements et dure bien plus longtemps pr\xe8s d\u2019une convergence \xe9l\xe9mentaire. Comme le High Order, ils n\xe9cessitent le Skyborne Heroic ou Epic Pack, en option."]},"race:orc":{title:"Orcs",summary:"Jadis asservis par le sang d\xe9moniaque, les orcs furent lib\xe9r\xe9s par Thrall et reb\xe2tissent d\xe9sormais leur honneur dans la terre rouge de Durotar.",body:["Les orcs arriv\xe8rent de Draenor sur Azeroth sous la forme de la Horde, pouss\xe9s par le sang d\xe9moniaque et par les d\xe9monistes de Gul'dan. Vaincus pendant la Deuxi\xe8me Guerre, ils d\xe9p\xe9rirent dans des camps d\u2019internement jusqu\u2019\xe0 ce que Thrall, fils du chef Loup-de-givre Durotan, les lib\xe8re et restaure les voies chamaniques de leurs anc\xeatres.","Apr\xe8s la Troisi\xe8me Guerre, Thrall conduisit son peuple en Kalimdor et fonda Durotar et sa capitale, Orgrimmar, d\u2019o\xf9 le chef de guerre gouverne d\xe9sormais une Horde partag\xe9e avec les taurens, les trolls Sombrelance et les R\xe9prouv\xe9s. Les orcs sont fiers, directs et d\u2019une loyaut\xe9 farouche, mais leur pass\xe9 sanglant perdure chez les cultistes de la Lame ardente en Durotar et dans le clan Rochenoire, qui ne rejoignit jamais Thrall. Les nouveaux orcs commencent dans la vall\xe9e des \xc9preuves. Dans Forever, les orcs peuvent aussi devenir mages."]},"race:tauren":{title:"Taurens",summary:"Doux g\xe9ants des plaines qui honorent la Terre-M\xe8re, les taurens ont trouv\xe9 un foyer en Mulgore et rejoint la Horde par gratitude.",body:["Les taurens sont de paisibles nomades \xe0 la stature imposante, qui honorent la Terre-M\xe8re et parcourent les plaines de Kalimdor depuis des \xe2ges. Pendant les ann\xe9es de la Troisi\xe8me Guerre, ils furent traqu\xe9s par les centaures, jusqu\u2019\xe0 ce que la Horde de Thrall, tout juste arriv\xe9e, aide le peuple de Cairne Sabot-de-Sang \xe0 rejoindre la s\xe9curit\xe9 de Mulgore.","Cairne unit de nombreuses tribus dispers\xe9es et fonda les Pitons-du-Tonnerre sur de grandes mesas dominant les prairies de Mulgore, et les taurens rejoignirent la Horde par gratitude et par respect. Leurs druides furent instruits par Malfurion Hurlorage en personne, et leurs chamans et chasseurs perp\xe9tuent de vieilles traditions. Des tribus rivales comme les Totem-sinistre, qui voient d\u2019un mauvais \u0153il le lien avec les orcs, restent un souci constant. Les jeunes taurens commencent au camp Narache, en Mulgore."]},"race:troll":{title:"Trolls",summary:"H\xe9ritiers d\u2019empires d\xe9chus, la plupart des trolls ha\xefssent encore les autres races ; la tribu Sombrelance, elle, a jur\xe9 fid\xe9lit\xe9 \xe0 Thrall et \xe0 la Horde.",body:["Les trolls r\xe9gnaient jadis sur de vastes empires : les Gurubashi dans les jungles du sud, les Amani dans les for\xeats du nord et les Zandalari, qui se disent les premiers de tous les trolls. Les guerres contre les elfes de la nuit, les hauts-elfes et les humains bris\xe8rent ces empires, et la plupart des tribus nourrissent encore de vieilles haines et prient les loas, les dieux-esprits de leurs anc\xeatres.","La tribu Sombrelance est diff\xe9rente. Chass\xe9s de Strangleronce par des tribus rivales, les Sombrelance se battaient pour leur \xeele quand la flotte de Thrall, ballott\xe9e par la temp\xeate, arriva ; leur chef Sen'jin y mourut, et son fils Vol'jin lia la tribu \xe0 la Horde. Ils s\u2019install\xe8rent sur les \xeeles de l\u2019\xc9cho, au large de Durotar, mais la magie noire du sorcier-docteur Zalazane les a repouss\xe9s jusqu\u2019au village de Sen'jin, sur le continent. Dans Forever, des Darkspear Raiders se disputent aussi les Darkspear Islands, au large du mar\xe9cage d\u2019\xc2prefange, et les trolls peuvent devenir d\xe9monistes."]},"race:undead":{title:"Morts-vivants",summary:"Victimes relev\xe9es de la peste qui se sont lib\xe9r\xe9es du roi-liche, les R\xe9prouv\xe9s r\xe8gnent sur Fossoyeuse sous les ruines de Lordaeron et ne font confiance \xe0 personne.",body:["Les R\xe9prouv\xe9s \xe9taient jadis des citoyens de Lordaeron, tu\xe9s par la peste et relev\xe9s par le Fl\xe9au, qui retrouv\xe8rent leur libre arbitre quand le pouvoir du roi-liche vacilla. Men\xe9s par la reine banshee Sylvanas Coursevent, ils revendiqu\xe8rent les ruines de la capitale de Lordaeron et firent de Fossoyeuse, en dessous, leur foyer. Leurs terres, les clairi\xe8res de Tirisfal et la for\xeat des Pins-Argent\xe9s, sont disput\xe9es par le Fl\xe9au et la Croisade \xe9carlate.","Les R\xe9prouv\xe9s rejoignirent la Horde en alli\xe9s de circonstance ; peu de vivants leur font confiance, et les travaux secrets de la Soci\xe9t\xe9 royale des apothicaires sur une nouvelle peste donnent \xe0 leurs partenaires de bonnes raisons de s\u2019en m\xe9fier. Les nouveaux R\xe9prouv\xe9s se rel\xe8vent au Glas, dans les clairi\xe8res de Tirisfal. Forever ajoute le donjon Ruins of Lordaeron, o\xf9 les R\xe9prouv\xe9s s\u2019efforcent de reprendre la cit\xe9 bris\xe9e au-dessus de Fossoyeuse, et autorise les paladins r\xe9prouv\xe9s, une association que les sources utilis\xe9es ici n\u2019expliquent pas encore."],unknowns:["Les sources de ce guide n\u2019expliquent pas comment les R\xe9prouv\xe9s sont devenus paladins dans Forever."]}}},1596,[]);
__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"zones1",{enumerable:!0,get:function(){return s}});const s={"zone:dun-morogh":{title:"Dun Morogh",summary:"Des vall\xe9es enneig\xe9es autour de Forgefer, foyer des nains et des gnomes qui ont perdu leur cit\xe9.",body:["Cern\xe9e par les pics de Khaz Modan, Dun Morogh est une terre de champs de neige, de lacs gel\xe9s et de tours de guet naines. Son c\u0153ur est Forgefer, la cit\xe9 montagnarde du clan Barbe-de-bronze sous le roi Magni, tandis que les jeunes nains et gnomes prennent les armes pour la premi\xe8re fois dans la vall\xe9e abrit\xe9e de Coldridge et autour du village brasseur de Kharanos. Les trolls Crins-de-Givre et les troggs fouisseurs harc\xe8lent les vall\xe9es.","\xc0 l\u2019ouest se trouve Gnomeregan, la merveille de l\u2019ing\xe9nierie gnome, perdue quand les troggs ont surgi des profondeurs et que le flot d\xe9sesp\xe9r\xe9 de radiations l\xe2ch\xe9 par ses d\xe9fenseurs a empoisonn\xe9 la cit\xe9. Ses survivants vivent d\xe9sormais en invit\xe9s \xe0 Forgefer. Dans Forever, les tombes royales du Hall of Thanes, sous la cit\xe9, ont \xe9t\xe9 forc\xe9es, et l\u2019on soup\xe7onne des intrus sombrefer."]},"zone:durotar":{title:"Durotar",summary:"La rude c\xf4te rouge que Thrall nomma d\u2019apr\xe8s son p\xe8re et o\xf9 les orcs b\xe2tirent Orgrimmar.",body:["Quand Thrall mena la Horde en Kalimdor, il revendiqua cette bande de c\xf4te orientale craquel\xe9e par le soleil et la nomma Durotar, d\u2019apr\xe8s son p\xe8re Durotan. Sa terre rouge et ses canyons pierreux rappelaient Draenor aux orcs. Ils chass\xe8rent les huranes du pays et \xe9lev\xe8rent Orgrimmar, nomm\xe9e d\u2019apr\xe8s Orgrim Marteau-du-Destin, dans un creux de montagne au nord.","Les jeunes orcs et trolls font leurs preuves dans la vall\xe9e des \xc9preuves avant de gagner Razor Hill. Sur la c\xf4te, les trolls Sombrelance tiennent le village de Sen'jin depuis que le sorcier-docteur Zalazane a asservi les leurs sur les \xeeles de l\u2019\xc9cho, et des soldats kultirassiens s\u2019attardent au fort de Tiragarde. Les cultistes de la Lame ardente r\xf4dent dans les collines, et leur culte fr\xe8re, la Lame br\xfblante, se cache dans le gouffre de Ragefeu, sous la capitale."]},"zone:elwynn-forest":{title:"For\xeat d\u2019Elwynn",summary:"Le c\u0153ur verdoyant du royaume de Hurlevent, o\xf9 de nombreux h\xe9ros humains font leurs premiers pas.",body:["La for\xeat d\u2019Elwynn est le c\u0153ur paisible du royaume de Hurlevent : des bois de ch\xeanes, des fermes et des lacs autour des murs blancs de la cit\xe9 de Hurlevent, reb\xe2tie apr\xe8s que la Horde l\u2019eut ras\xe9e pendant la Premi\xe8re Guerre. Les novices se forment \xe0 l\u2019abbaye de Comt\xe9-du-Nord, et les voyageurs font halte \xe0 l\u2019auberge de la Fiert\xe9 du lion, \xe0 Comt\xe9-de-l\u2019Or.","La paix est plus fragile qu\u2019il n\u2019y para\xeet. Les kobolds ont pris les mines, les gnolls Rivepatte pillent les fermes de l\u2019ouest, les murlocs envahissent les lacs, et les bandits d\xe9fias se r\xe9pandent depuis la marche de l\u2019Ouest voisine. Dans la capitale m\xeame, la Prison est tomb\xe9e aux mains d\u2019une \xe9meute de d\xe9tenus d\xe9fias."]},"zone:mulgore":{title:"Mulgore",summary:"Les plaines balay\xe9es par le vent des taurens, couronn\xe9es par les mesas des Pitons-du-Tonnerre.",body:["Mulgore est la prairie ancestrale des taurens, une cuvette verte de plaines et de mesas ferm\xe9e par les montagnes, avec un seul col vers l\u2019est, vers les Tarides. Pendant des g\xe9n\xe9rations, les taurens nomades furent harcel\xe9s par les centaures, jusqu\u2019\xe0 ce que la Horde de Thrall aide le grand chef Cairne Sabot-de-Sang \xe0 ramener son peuple chez lui. Ils y \xe9lev\xe8rent leurs premiers \xe9tablissements durables : le village de Sabot-de-Sang et la capitale des Pitons-du-Tonnerre, b\xe2tie au sommet de mesas vertigineuses reli\xe9es par des ponts de corde.","Les jeunes taurens s\u2019entra\xeenent au camp Narache, sur la mesa de Nuage-Rouge, tandis que gnolls, huranes et prospecteurs de la Venture Company troublent les plaines. Dans Forever, les Skyborne de la Horde arrivent de Zephras Isle en a\xe9ronef au Skywatcher Plateau."]},"zone:teldrassil":{title:"Teldrassil",summary:"Le nouvel Arbre-Monde des elfes de la nuit, au large de la c\xf4te nord de Kalimdor, avec Darnassus dans ses branches.",body:["Apr\xe8s que la Troisi\xe8me Guerre leur eut co\xfbt\xe9 leur immortalit\xe9, les druides elfes de la nuit firent pousser un nouvel Arbre-Monde au large de la c\xf4te nord de Kalimdor. Ils le nomm\xe8rent Teldrassil, \xab couronne de la terre \xbb, et b\xe2tirent Darnassus dans ses branches, une cit\xe9 de temples baign\xe9s de lune o\xf9 la grande pr\xeatresse Tyrande Murmevent guide son peuple.","L\u2019arbre fut plant\xe9 sans la b\xe9n\xe9diction des Aspects draconiques, et sa croissance n\u2019a pas \xe9t\xe9 saine. La corruption s\u2019est insinu\xe9e dans sa faune et a rendu sauvages les furbolgs Gnarlpine. Les novices elfes de la nuit commencent \xe0 Sombrevallon, et des bateaux partant du village de Rut'theran, au pied de l\u2019arbre, relient l\u2019\xeele \xe0 Sombrivage."]},"zone:tirisfal-glades":{title:"Clairi\xe8res de Tirisfal",summary:"De sombres clairi\xe8res autour des ruines de la capitale de Lordaeron, d\xe9sormais le c\u0153ur du territoire des R\xe9prouv\xe9s.",body:["Les clairi\xe8res de Tirisfal abritaient jadis la capitale de Lordaeron, et le Conseil de Tirisfal, l\u2019ordre qui choisissait les Gardiens, tirait son nom de ses r\xe9unions secr\xe8tes dans ces collines paisibles. La peste et la chute du royaume ont laiss\xe9 la terre sous un ciel vert et maladif. Sous le palais en ruine, les R\xe9prouv\xe9s de Sylvanas Coursevent ont fait de Fossoyeuse leur foyer ; leurs morts r\xe9cemment relev\xe9s s\u2019\xe9veillent au Glas et se rassemblent au village de Brill.","Les ennemis pressent de toutes parts : des restes du Fl\xe9au hantent les fermes, et les fanatiques de la Croisade \xe9carlate tiennent le monast\xe8re \xc9carlate au nord-est. Dans Forever, les R\xe9prouv\xe9s tentent de reprendre la cit\xe9 bris\xe9e au-dessus d\u2019eux, o\xf9 un n\xe9cromancien rassemblerait des forces dans les Ruins of Lordaeron."]},"zone:zephras-isle":{title:"Zephras Isle",summary:"Une \xeele volante de Skywall, le plan \xc9l\xe9mentaire de l\u2019Air, et la zone de d\xe9part des Skyborne de Forever.",body:["Zephras Isle est la zone de d\xe9part des Skyborne, la race jouable nouvelle dans World of Warcraft: Forever, d\xe9bloqu\xe9e avec le Skyborne Heroic ou Epic Pack, en option. L\u2019\xeele flotte dans Skywall, le plan \xc9l\xe9mentaire de l\u2019Air, o\xf9 les Skyborne la partageaient autrefois avec des \xe9l\xe9mentaires d\u2019air. Ces \xe9l\xe9mentaires ont disparu il y a plusieurs si\xe8cles, et la magie qui maintient l\u2019\xeele dans les airs faiblit depuis. Avec eux s\u2019est perdu le contact avec les autres \xeeles skyborne, Anvilas et Siroccas.","Aujourd\u2019hui ces \xeeles s\u2019effondrent, des r\xe9fugi\xe9s fuient vers Zephras, et Zephras elle-m\xeame commence \xe0 se d\xe9sagr\xe9ger. La Grande Ancienne Talaanis Shadowsong gouverne depuis la ville de Valanaar, dont les quais a\xe9riens envoient des a\xe9ronefs vers Dalaran, dans les montagnes d\u2019Alterac, pour l\u2019Alliance, et vers le Skywatcher Plateau, en Mulgore, pour la Horde."],unknowns:["Les sources de ce guide n\u2019expliquent pas pourquoi les \xe9l\xe9mentaires d\u2019air ont disparu.","Les sources de ce guide ne traitent pas encore de l\u2019origine profonde des Skyborne et de leurs ordres.","Les anciens ma\xeetres de l\u2019\xeele, les Shal\u2019nan, sont seulement nomm\xe9s, pas d\xe9crits."]},"zone:darkshore":{title:"Sombrivage",summary:"Une c\xf4te brumeuse sem\xe9e de ruines, que les elfes de la nuit gardent depuis le port d\u2019Auberdine.",body:["Sombrivage est une longue bande de la c\xf4te nord-ouest de Kalimdor, assombrie par la pluie et parsem\xe9e des ruines croulantes de cit\xe9s kaldorei datant d\u2019avant la Fracture. Les elfes de la nuit la revendiquent comme partie de leur nouveau royaume, et les Sentinelles patrouillent la route qui part vers le sud, du port d\u2019Auberdine jusqu\u2019\xe0 Orneval.","Le danger guette hors de la route : des fant\xf4mes errent dans les vieilles ruines, nagas et murlocs r\xf4dent sur les plages, les furbolgs deviennent sauvages dans les bois, et des cultistes du Marteau du cr\xe9puscule et du Dark Strand se cachent dans les collines. Les navires d\u2019Auberdine font voile vers Teldrassil, le port de Menethil et, dans Forever, Hurlevent ; une nouvelle liaison propre \xe0 Forever arrive aussi d\u2019Austrivage."]},"zone:loch-modan":{title:"Loch Modan",summary:"Une vall\xe9e naine des hautes terres dont le grand loch est retenu par le Stonewrought Dam.",body:["\xc0 l\u2019est de Dun Morogh s\u2019\xe9tend le Loch Modan, une fra\xeeche vall\xe9e d\u2019altitude plant\xe9e de pins et de bouleaux autour d\u2019un grand loch retenu par le Stonewrought Dam, l\u2019une des merveilles de l\u2019ing\xe9nierie naine. Peu se souviennent qu\u2019un architecte sombrefer l\u2019a con\xe7u. Le village de Thelsamar garde la route, et le poste d\u2019Algaz surveille le col qui m\xe8ne au nord, vers les Paluns.","La vall\xe9e se souvient de la Deuxi\xe8me Guerre, quand la Horde l\u2019envahit avant que les nains de Forgefer ne la repoussent. Aujourd\u2019hui, le danger monte des profondeurs : des fouilles comme celle d\u2019Ironband ont r\xe9veill\xe9 les troggs, les ogres Mo'grosh tiennent les collines, et des nains sombrefer s\u2019en prennent au barrage lui-m\xeame."]},"zone:silverpine-forest":{title:"For\xeat des Pins-Argent\xe9s",summary:"Une for\xeat de pins hant\xe9e sur la c\xf4te ouest de Lordaeron, disput\xe9e par les R\xe9prouv\xe9s, les worgens et les derniers humains du pays.",body:["La for\xeat des Pins-Argent\xe9s longe la c\xf4te ouest d\xe9chiquet\xe9e de Lordaeron ; ses pins \xe0 l\u2019\xe9corce argent\xe9e sont aujourd\u2019hui malades et noy\xe9s dans la brume. Les R\xe9prouv\xe9s tiennent le nord depuis le S\xe9pulcre, tandis que des survivants humains et des mages envoy\xe9s par Dalaran s\u2019accrochent \xe0 Moulin-de-l\u2019Ambre et au sud. Au-del\xe0, Gilneas s\u2019est retranch\xe9e derri\xe8re le mur de Griset\xeate.","L\u2019ombre la plus profonde de la for\xeat est le donjon d\u2019Ombrecroc, autrefois le ch\xe2teau du baron d\u2019Argelaine. Pendant la Troisi\xe8me Guerre, l\u2019archimage dalaranien Arugal invoqua des worgens pour combattre le Fl\xe9au, en perdit le contr\xf4le et sombra dans la folie ; il appelle d\xe9sormais ces b\xeates ses enfants. Sa mal\xe9diction a gagn\xe9 le village voisin de Bois-du-B\xfbcher, dont les habitants se changent en worgens \xe0 la tomb\xe9e de la nuit."]},"zone:westfall":{title:"Marche de l\u2019Ouest",summary:"Le grenier abandonn\xe9 de Hurlevent, devenu le territoire de la Confr\xe9rie d\xe9fias.",body:["La marche de l\u2019Ouest \xe9tait autrefois le grenier de Hurlevent, une c\xf4te de champs dor\xe9s et de moulins \xe0 vent. Depuis la Deuxi\xe8me Guerre, elle est en grande partie laiss\xe9e en friche, et le royaume n\u2019a eu ni argent ni soldats \xe0 y consacrer. La Confr\xe9rie d\xe9fias s\u2019est engouffr\xe9e dans ce vide : les tailleurs de pierre qui avaient reb\xe2ti Hurlevent, devenus hors-la-loi apr\xe8s que les nobles eurent refus\xe9 de les payer, men\xe9s par Edwin VanCleef.","Les D\xe9fias r\xe8gnent sur le village en ruine de Ruisselune et cachent un chantier naval dans les Mortemines, en dessous, tandis que gnolls et golems de moisson d\xe9traqu\xe9s s\u2019en prennent aux fermes restantes. Seule la Milice populaire, lev\xe9e par Gryan Stoutmantle \xe0 la colline des Sentinelles, leur barre encore la route."]},"zone:barrens":{title:"Tarides",summary:"Une vaste savane au c\u0153ur de Kalimdor, travers\xe9e par la route de l\u2019Or et tenue surtout par la Horde.",body:["Les Tarides sont une immense savane d\u2019arbres \xe9pineux, d\u2019oasis et de lits de rivi\xe8re ass\xe9ch\xe9s au c\u0153ur de Kalimdor. Des cit\xe9s elfes de la nuit s\u2019y dressaient avant la Fracture ; aujourd\u2019hui, la Horde tient le pays depuis la Crois\xe9e et le camp Taurajo, les gobelins de Cabestan commercent par la mer avec Baie-du-Butin, et des soldats de l\u2019Alliance montent la garde \xe0 Northwatch Hold. Dans Forever, Durotar Supply and Logistics commerce depuis un camp \xe0 l\u2019ouest de la Crois\xe9e.","Centaures kolkar, huranes et harpies attaquent les voyageurs le long de la route de l\u2019Or. Sous terre se trouvent trois vieilles blessures : les cavernes des Lamentations, o\xf9 le r\xeave d\u2019un druide a tourn\xe9 au cauchemar, et les galeries \xe9pineuses du kraal de Tranchebauge et des souilles de Tranchebauge, sacr\xe9es pour les huranes."]},"zone:redridge-mountains":{title:"Les Carmines",summary:"Des collines rouges et un lac paisible \xe0 l\u2019est d\u2019Elwynn, o\xf9 Comt\xe9-du-Lac tient bon face aux gnolls et aux orcs Rochenoire.",body:["\xc0 l\u2019est d\u2019Elwynn s\u2019\xe9l\xe8vent les Carmines, un pays de pierre rouge, de grands ormes et de rivi\xe8res tumultueuses qui fournit bois, poisson et grain \xe0 Hurlevent. Sa ville principale, Comt\xe9-du-Lac, se trouve sur la rive du lac Placide, et le carrefour de Three Corners la relie \xe0 Elwynn et au bois de la P\xe9nombre.","La paix y est fragile. Les gnolls des Carmines pillent les fermes, et des orcs Rochenoire venus des steppes Ardentes ont pris Stonewatch Keep et campent dans la Render's Valley. Il y a longtemps, les nains sombrefer b\xe2tirent un royaume dans ces montagnes, jusqu\u2019\xe0 ce que l\u2019invocation de Ragnaros par Thaurissan calcine les terres au nord. Dans Forever, l\u2019Azeroth Commerce Authority commerce \xe0 Three Corners, et des cols m\xe8nent \xe0 l\u2019est vers les Riverglades."]},"zone:stonetalon-mountains":{title:"Les Serres-Rocheuses",summary:"Des pics escarp\xe9s \xe0 l\u2019ouest des Tarides, sacr\xe9s pour les elfes de la nuit et les taurens, et d\xe9figur\xe9s par l\u2019abattage des gobelins.",body:["Les Serres-Rocheuses s\u2019\xe9l\xe8vent \xe0 l\u2019ouest des Tarides ; c\u2019est le foyer ancestral des harpies, m\xeame si leurs nu\xe9es se sont depuis r\xe9pandues bien au-del\xe0. Le plus haut sommet, le pic des Serres-Rocheuses, est sacr\xe9 pour les elfes de la nuit comme pour les taurens ; les elfes de la nuit entretiennent un tertre et une clairi\xe8re pr\xe8s de sa cime, les taurens tiennent la retraite de Roche-Soleil sur les hauteurs centrales, et les trolls Sombrelance campent \xe0 Malaka'jin.","C\u2019est la Venture Company qui a fait le plus de mal au pays : ses gobelins ont d\xe9pouill\xe9 le Windshear Crag de presque tous ses arbres, \xe9touffant l\u2019air de suie et souillant l\u2019eau de p\xe9trole. Les taurens Totem-sinistre, les kobolds et les b\xeates dangereuses du Charred Vale ne rendent pas les routes plus s\xfbres."]},"zone:ashenvale":{title:"Orneval",summary:"La for\xeat ancestrale des elfes de la nuit, o\xf9 commen\xe7a la guerre contre la Horde pour son bois.",body:["Orneval est la for\xeat ancestrale des elfes de la nuit, un bois profond d\u2019ombres violettes et d\u2019arbres antiques qui s\u2019\xe9tend du rivage de Zoram jusqu\u2019aux confins des Tarides. Les Kaldorei tiennent Astranaar et une s\xe9rie d\u2019avant-postes, et les Sentinelles gardent farouchement leurs bosquets.","Pendant la Troisi\xe8me Guerre, les orcs Chanteguerre de Grom Hurlenfer entaill\xe8rent ces bois, burent de nouveau le sang d\xe9moniaque et tu\xe8rent le demi-dieu Cenarius ; Grom mourut plus tard en tuant le seigneur des ab\xeemes Mannoroth, \xe0 l\u2019endroit appel\xe9 aujourd\u2019hui Demon Fall Canyon. Les orcs abattent toujours l\u2019est de la for\xeat depuis le poste de Bois-Bris\xe9 et les camps Chanteguerre, et la vieille querelle couve encore. Des satyres hantent les ruines, et sur la c\xf4te se trouvent les profondeurs de Brassenoire, un temple d\u2019\xc9lune englouti."]},"zone:duskwood":{title:"Bois de la P\xe9nombre",summary:"Un coin autrefois lumineux d\u2019Elwynn englouti par une nuit sans fin, tenu par les habitants obstin\xe9s de Sombre-Comt\xe9.",body:["Le bois de la P\xe9nombre \xe9tait autrefois la partie sud de la for\xeat d\u2019Elwynn, o\xf9 se trouvaient les villages aujourd\u2019hui appel\xe9s Sombre-Comt\xe9 et Colline-aux-Corbeaux. Puis tomba une ombre qui ne s\u2019est jamais lev\xe9e, li\xe9e au sort de la Faux d\u2019\xc9lune des elfes de la nuit. Sous son cr\xe9puscule \xe9ternel, les arbres devinrent noueux, et worgens, morts-vivants et ogres venus du d\xe9fil\xe9 de Deuillevent se mirent \xe0 r\xf4der.","Hurlevent a largement laiss\xe9 la r\xe9gion se d\xe9brouiller seule. La Garde de nuit de Sombre-Comt\xe9 surveille la route principale, le cimeti\xe8re de Colline-aux-Corbeaux se remplit de morts sans repos, et au fond des bois, le bosquet du Cr\xe9puscule abrite un grand arbre et un portail vers le R\xeave d\u2019\xe9meraude."]},"zone:wetlands":{title:"Les Paluns",summary:"Des marais gris et d\xe9tremp\xe9s qui gardent la route entre Khaz Modan et Lordaeron.",body:["Les Paluns sont un marais froid et noy\xe9 de brume entre les montagnes de Khaz Modan et la mer. Des forteresses naines bordaient autrefois la r\xe9gion ; la guerre a bris\xe9 la plupart d\u2019entre elles. Le port de Menethil est ici le point d\u2019ancrage de l\u2019Alliance, un port dont les navires partent pour Theramore et, dans Forever, jusqu\u2019\xe0 Austrivage. Les voyageurs arrivent par Dun Algaz assi\xe9g\xe9e ou par le pont de Thandol endommag\xe9.","\xc0 l\u2019est se dresse Grim Batol, la cit\xe9 maudite des Marteau-hardi o\xf9 le clan Gueule-de-dragon retint les dragons rouges captifs pendant la Deuxi\xe8me Guerre ; des ren\xe9gats Gueule-de-dragon errent encore dans le marais, et des nains sombrefer tiennent Dun Modr. Dans Forever, une brume \xe9trange et des \xe9clairs de lumi\xe8re au-dessus du Whelgar's Excavation Site m\xe8nent \xe0 un donjon de cr\xe9ations des titans."]},"zone:hillsbrad-foothills":{title:"Contreforts de Hautebrande",summary:"Des collines verdoyantes o\xf9 Austrivage et Moulin-de-Tarren se toisent pr\xe8s des ruines de Durnholde.",body:["Les collines vertes et fertiles de Hautebrande s\u2019\xe9tendent juste au sud de l\u2019ancien royaume d\u2019Alterac. Deux bourgs s\u2019y font face : Austrivage, de l\u2019Alliance, sur la c\xf4te, et l\u2019avant-poste des R\xe9prouv\xe9s \xe0 Moulin-de-Tarren, dans les collines, et leur querelle ensanglante les champs. Murlocs et Syndicat ajoutent aux troubles.","Sur une hauteur \xe0 l\u2019est se dresse le donjon de Durnholde, autrefois quartier g\xe9n\xe9ral des camps d\u2019internement orcs, o\xf9 lord Aedelas Blackmoore \xe9leva le jeune Thrall comme gladiateur avant que celui-ci ne s\u2019\xe9vade pour lib\xe9rer son peuple ; le Syndicat occupe aujourd\u2019hui ses ruines. Dans Forever, les qu\xeates qui ouvrent l\u2019acc\xe8s \xe0 la City of Dalaran commencent dans les deux bourgs, et des navires font escale \xe0 Austrivage."]},"zone:thousand-needles":{title:"Mille pointes",summary:"Un canyon de fl\xe8ches de pierre et de salines, o\xf9 taurens, centaures et gobelins amateurs de course se partagent un terrain incertain.",body:["Mille pointes est un immense canyon aride h\xe9riss\xe9 de hautes mesas de pierre dans le sud de Kalimdor, auquel on acc\xe8de depuis les Tarides par le Grand \xe9l\xe9vateur. Les taurens du poste de Librevent vivent au sommet des mesas, tandis que les Totem-sinistre, un clan tauren hostile \xe0 Cairne Sabot-de-Sang, tiennent le Darkcloud Pinnacle. Les centaures galak parcourent le fond du canyon, et les harpies nichent parmi les pointes.","\xc0 l\u2019est, le canyon s\u2019ouvre sur les Shimmering Flats, une \xe9tendue de sel aveuglante o\xf9 des ing\xe9nieurs gobelins et gnomes font courir leurs machines sur la Mirage Raceway."]},"zone:alterac-mountains":{title:"Montagnes d\u2019Alterac",summary:"Le royaume bris\xe9 d\u2019Alterac et les ruines prot\xe9g\xe9es de Dalaran, disput\xe9s par les ogres et le Syndicat.",body:["Les montagnes d\u2019Alterac formaient jadis le royaume d\u2019Alterac, dont le seigneur, Aiden Perenolde, trahit l\u2019Alliance au profit de la Horde pendant la Deuxi\xe8me Guerre. Le royaume fut dissous ; aujourd\u2019hui, des ogres Crushridge squattent les ruines de la cit\xe9 d\u2019Alterac, et le Syndicat d\u2019Aliden Perenolde, h\xe9ritier de la maison d\xe9chue, r\xe8gne sur Strahnbrad. Les voleurs de Ravenholdt restent entre eux dans les collines.","Au bord du lac Lordamere reposent les vestiges de Dalaran, la cit\xe9 des mages qu\u2019Archimonde d\xe9truisit pendant la Troisi\xe8me Guerre. Le Kirin Tor la reb\xe2tit derri\xe8re une barri\xe8re magique. Dans Forever, cette barri\xe8re est tomb\xe9e et la cit\xe9 d\xe9borde de chaos arcanique ; c\u2019est aussi l\xe0 que les Skyborne de l\u2019Alliance arrivent en a\xe9ronef depuis Zephras Isle."]},"zone:arathi-highlands":{title:"Hautes-terres Arathies",summary:"L\u2019ancien c\u0153ur d\u2019Arathor, o\xf9 Stromgarde g\xeet en ruine et o\xf9 trois camps se disputent les restes.",body:["Les hautes-terres Arathies \xe9taient le c\u0153ur d\u2019Arathor, le premier empire humain, fond\xe9 par le roi Thoradin avec Strom pour capitale. Son h\xe9riti\xe8re, Stromgarde, g\xeet aujourd\u2019hui en grande partie en ruine au sud-ouest, o\xf9 les d\xe9fenseurs du prince Galen Trollemort m\xe8nent une gu\xe9rilla \xe0 trois camps contre le Syndicat et les ogres Boulderfist. Le mur de Thoradin marque toujours l\u2019ancienne fronti\xe8re \xe0 l\u2019ouest.","L\u2019Alliance se rassemble au refuge de l\u2019Orni\xe8re. La Horde tient Tr\xe9pas-d\u2019Orgrim, un ancien camp d\u2019internement nomm\xe9 en l\u2019honneur du chef de guerre Orgrim Marteau-du-Destin, tomb\xe9 en lib\xe9rant son peuple. Les trolls Witherbark hantent les collines, et le pont de Thandol relie les hautes-terres aux Paluns."]},"zone:desolace":{title:"D\xe9solace",summary:"Une terre d\xe9sol\xe9e, grise et couverte de cendres, jonch\xe9e d\u2019os de kodos et d\xe9chir\xe9e par les tribus centaures.",body:["D\xe9solace est une \xe9tendue lugubre de cendre grise, d\u2019arbres morts et de cr\xe2nes de kodos antiques, qui viennent mourir au cimeti\xe8re des Kodos. Les ruines de cit\xe9s des Bien-n\xe9s, pulv\xe9ris\xe9es par la Fracture, s\u2019effritent sur ses collines, et d\xe9mons et satyres se rassemblent encore l\xe0 o\xf9 subsiste une vieille magie.","C\u2019est la patrie des centaures, n\xe9s dans les cavernes de Maraudon de l\u2019union de Zaetar, fils de Cenarius, et de la princesse de la terre Theradras. Leurs quatre tribus, les Kolkar, les Gelkis, les Magram et les Maraudine, se combattent aussi farouchement qu\u2019elles combattent les \xe9trangers. L\u2019Alliance tient le point de Nijel et la Horde le village de Shadowprey."]}}},1597,[]);
__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"zones2",{enumerable:!0,get:function(){return s}});const s={"zone:stranglethorn-vale":{title:"Vall\xe9e de Strangleronce",summary:"Une jungle \xe9touffante de cit\xe9s trolls d\xe9chues, de chasseurs, de pirates et du port gobelin de Baie-du-Butin.",body:["La vall\xe9e de Strangleronce \xe9tait le c\u0153ur du territoire des trolls Gurubashi, dont l\u2019empire r\xe9gnait jadis sur la jungle depuis Zul'Gurub. Leurs cit\xe9s de pierre s\u2019effritent aujourd\u2019hui sous les lianes, toujours hant\xe9es par des trolls de la jungle, tandis qu\u2019ogres, nagas et les redoutables ronces \xe9trangleuses de la vall\xe9e rendent chaque sentier p\xe9rilleux. Les chasseurs affluent \xe0 l\u2019exp\xe9dition de Nesingwary, la Horde tient le camp de base de Grom'gol, et des rebelles de l\u2019Alliance campent au nord.","\xc0 la pointe sud, les gobelins de Baie-du-Butin tiennent un port sans foi ni loi aux c\xf4t\xe9s des pirates des Blackwater Raiders, et des combattants de toutes races se retrouvent dans la vieille ar\xe8ne des Gurubashi. Dans Forever, d\u2019antiques ruines trolls ont surgi de la mer \xe0 l\u2019ouest de Grom'gol : la Drowned City, o\xf9 r\xf4dent d\xe9sormais trolls et nagas."]},"zone:badlands":{title:"Terres ingrates",summary:"Un d\xe9sert craquel\xe9 de canyons o\xf9 les nains fouillent les secrets des titans et o\xf9 la Horde veille depuis Kargath.",body:["Les Terres ingrates sont un d\xe9sert craquel\xe9, br\xfbl\xe9 par le soleil, fait de rochers et de canyons sinueux dans le sud de Khaz Modan. Les prospecteurs de Forgefer le passent au peigne fin \xe0 la recherche de reliques des titans, attir\xe9s par Uldaman, une immense chambre forte enfouie qui a livr\xe9 les premiers indices sur l\u2019origine des nains, \xeatres de pierre vivante. Des troggs tir\xe9s d\u2019un long sommeil ont massacr\xe9 la premi\xe8re exp\xe9dition et d\xe9fendent d\xe9sormais ses salles.","Les nains sombrefer tiennent la forteresse d\u2019Angor, les ogres Dustbelcher campent dans toute la d\xe9solation, et la prog\xe9niture des dragons noirs niche dans le ravin de Lethlor. La Horde monte la garde depuis l\u2019avant-poste de Kargath, pr\xe8s de la route de la gorge des Vents br\xfblants."]},"zone:dustwallow-marsh":{title:"Mar\xe9cage d\u2019\xc2prefange",summary:"Un marais fumant qui cache Theramore, le repaire d\u2019Onyxia et la prison longtemps scell\xe9e de l\u2019\xeele d\u2019Alcaz.",body:["Le mar\xe9cage d\u2019\xc2prefange est un marais ancien et toujours d\xe9tremp\xe9 sur la c\xf4te est de Kalimdor, grouillant de crocilisques, de raptors et de murlocs. Au large se dresse l\u2019\xeele de Theramore, la cit\xe9-forteresse que Jaina Portvaillant fonda pour les survivants qui l\u2019avaient suivie vers l\u2019ouest ; la Horde lui r\xe9pond depuis le village de Brackenwall, en bordure du marais. Au sud, des dragons noirs infestent le Wyrmbog autour du repaire d\u2019Onyxia.","Des rumeurs entourent depuis longtemps l\u2019\xeele d\u2019Alcaz, dont la prison aurait d\xe9tenu des captifs de haut rang, jusqu\u2019au roi Varian Wrynn. Dans Forever, ses portes s\u2019ouvrent enfin et r\xe9v\xe8lent la Confr\xe9rie d\xe9fias et des nagas en guerre \xe0 l\u2019int\xe9rieur."]},"zone:riverglades":{title:"Riverglades",summary:"Un pays de rivi\xe8res disput\xe9 dans le sud-est de Khaz Modan, nouveau dans Forever, o\xf9 les chevaliers de Farholde m\xe8nent encore une guerre que Hurlevent a laiss\xe9e derri\xe8re elle.",body:["Les Riverglades s\u2019\xe9tendent \xe0 l\u2019est des Terres ingrates et des steppes Ardentes et appartenaient jadis au royaume de Hurlevent. Pendant la Premi\xe8re Guerre, la Horde pilla le village de Sunnyglade et r\xe9duisit ses habitants en esclavage. Quelques familles s\u2019enfuirent pour fonder Windstead, tandis que des chevaliers qui lib\xe9r\xe8rent les captifs fond\xe8rent Meadowsbrook, puis fortifi\xe8rent une \xeele c\xf4ti\xe8re sous le nom de Farholde. Croyant la r\xe9gion perdue, Hurlevent se tourna vers d\u2019autres soucis.","Vers la fin de la Deuxi\xe8me Guerre, des ogres du Marteau du cr\xe9puscule et des orcs Stormreaver fuyant la tombe de Sargeras s\u2019y r\xe9fugi\xe8rent, et des ann\xe9es de raids s\u2019achev\xe8rent par le si\xe8ge de Farholde. En l\u2019an 25, la Brotherhood of the Horse du chevalier-commandant Demar Brant combat toujours, le Marteau du cr\xe9puscule tient Sunnyglade en ruine, et les ogres Bolder'ok ont rejoint la Horde."],unknowns:["Les sources ne nomment pas qui commande les forces de la Horde \xe0 Rog'mar et \xe0 Bolder'ok.","Que Cho\u2019gall soit venu dans la r\xe9gion apr\xe8s la Deuxi\xe8me Guerre n\u2019est qu\u2019une rumeur.","La signification des chants entendus \xe0 la Krol\u2019dok Stronghold apr\xe8s la tomb\xe9e de la nuit reste ouverte."]},"zone:swamp-of-sorrows":{title:"Marais des Chagrins",summary:"Un marais saum\xe2tre o\xf9 les dragons verts gardent le temple englouti d\u2019Atal'Hakkar et o\xf9 la Horde tient Pierr\xeache.",body:["Le marais des Chagrins est une tourbi\xe8re stagnante d\u2019arbres pleureurs et d\u2019eau saum\xe2tre au sud des royaumes de l\u2019Est, pr\xe8s de l\u2019endroit o\xf9 la Porte des T\xe9n\xe8bres s\u2019ouvrit pour la premi\xe8re fois. La Horde a su tirer parti de son \xe9loignement de Hurlevent : la ville orque de Pierr\xeache y est son bastion. Crocilisques, b\xeates des marais et une bande de draene\xef exil\xe9s se partagent l\u2019eau trouble.","Au c\u0153ur du marais se trouve le temple d\u2019Atal'Hakkar, le sanctuaire englouti o\xf9 les pr\xeatres atal'ai tent\xe8rent jadis d\u2019invoquer leur dieu du sang, Hakkar. Les dragons verts de l\u2019Aspect Ysera le gardent d\xe9sormais, avertissant qu\u2019une terreur y remue encore."]},"zone:feralas":{title:"F\xe9ralas",summary:"Une for\xeat luxuriante nourrie par la pluie, faite d\u2019arbres g\xe9ants, de ruines tenues par les ogres et de l\u2019antique cit\xe9 bien-n\xe9e d\u2019Eldre'Thalas.",body:["F\xe9ralas est une for\xeat luxuriante et d\xe9tremp\xe9e d\u2019arbres g\xe9ants sur la c\xf4te sud-ouest de Kalimdor, autrefois partie de l\u2019antique royaume des elfes de la nuit. Sa plus grande ruine est Eldre'Thalas, aujourd\u2019hui appel\xe9e Hache-Tripes, o\xf9 les Shen'dralar, des Bien-n\xe9s qui surv\xe9curent \xe0 la Fracture, v\xe9curent repli\xe9s sur eux-m\xeames pendant dix mille ans. Les ogres Gordunni ont envahi les vieilles ruines elfiques et r\xe9pandu leur souillure dans tout le pays.","Les Sentinelles du bastion de Pennelune surveillent la c\xf4te depuis l\u2019\xeele de Sardor, tandis que les taurens du camp Mojache traquent les ren\xe9gats Totem-sinistre pour la Horde. Les nagas tiennent les \xeeles de l\u2019ouest, des ruches silithides sont apparues, et des dragons verts gardent le Dream Bough, une porte vers le R\xeave d\u2019\xe9meraude."]},"zone:hinterlands":{title:"Les Hinterlands",summary:"Des collines sauvages du nord, peupl\xe9es de chevaucheurs de griffon et de trolls des for\xeats, foyer des nains Marteau-hardi \xe0 Nid-de-l\u2019Aigle.",body:["Les Hinterlands sont des hautes terres escarp\xe9es et bois\xe9es au nord de Lordaeron. Apr\xe8s la guerre des Trois Marteaux, les nains Marteau-hardi abandonn\xe8rent Grim Batol, devenue maudite, et s\u2019install\xe8rent ici, \xe0 Nid-de-l\u2019Aigle, o\xf9 ils domptent les griffons sauvages de la r\xe9gion et restent de fid\xe8les alli\xe9s de l\u2019Alliance. Quelques hauts-elfes tiennent encore la Quel'Danil Lodge.","Les collines appartiennent tout autant aux trolls des for\xeats. La tribu Revantusk s\u2019est rang\xe9e du c\xf4t\xe9 de la Horde de Thrall, tandis que les Vilebranch r\xe8gnent sur la grande cit\xe9-temple de Jintha'Alor et que les Witherbark r\xf4dent autour de Shadra'Alor. Au nord, l\u2019arbre ancien Seradane abrite un portail vers le R\xeave d\u2019\xe9meraude, gard\xe9 par des dragons verts."]},"zone:tanaris":{title:"Tanaris",summary:"Une mer de dunes gouvern\xe9e depuis Gadgetzan, qui cache les grottes du Temps et la cit\xe9 troll de Zul'Farrak.",body:["Tanaris est un d\xe9sert sans fin de dunes et de temp\xeates de sable dans le sud-est de Kalimdor. Les gobelins du cartel Gentepression le dirigent depuis Gadgetzan et le port de Gentepression, maintenant une neutralit\xe9 fragile tandis que les bandits Wastewander, les pirates des Mers du Sud et les ogres Dunemaul s\u2019en prennent aux voyageurs.","Le d\xe9sert cache des puissances plus anciennes. Dans les grottes du Temps, le vol de bronze de Nozdormu veille sur le cours de l\u2019histoire ; loin au sud s\u2019\xe9tendent les ruines titaniques d\u2019Uldum ; et les trolls des sables de Zul'Farrak gardent leur cit\xe9 fortifi\xe9e au nord-ouest. Dans Forever, un navire du port de Gentepression relie le d\xe9sert \xe0 Powderfuse Port, dans les Riverglades."]},"zone:searing-gorge":{title:"Gorge des Vents br\xfblants",summary:"Une fosse calcin\xe9e de mines sombrefer et de travail forc\xe9, noircie par l\u2019invocation de Ragnaros.",body:["La gorge des Vents br\xfblants est une terre noircie de cendres et de roche en fusion au sud de Khaz Modan. Elle doit ses cicatrices \xe0 la m\xeame catastrophe que celle qui br\xfbla les steppes Ardentes : l\u2019invocation de Ragnaros par le thane-sorcier Thaurissan, qui mit fin \xe0 la guerre des Trois Marteaux. Aujourd\u2019hui, les nains sombrefer la dominent et forcent des esclaves \xe0 extraire du minerai dans la grande faille du Chaudron.","Tous les Sombrefer ne servent pas le seigneur du Feu. La Confr\xe9rie du thorium, des ma\xeetres forgerons qui ont rompu avec leur clan, commerce avec les \xe9trangers depuis la halte du Thorium. Au sud se dresse le mont Rochenoire, avec l\u2019empire sombrefer dans ses profondeurs et le pic, au-dessus, tenu par les orcs et les dragons noirs."]},"zone:azshara":{title:"Azshara",summary:"Une c\xf4te d\u2019automne \xe9ternel au-dessus des ruines englouties de la capitale de la reine Azshara.",body:["Azshara est une c\xf4te d\xe9chir\xe9e d\u2019automne \xe9ternel au nord-est de Kalimdor, aux arbres flamboyants de rouge et d\u2019or. Ici se dressait Zin-Azshari, la plus grande cit\xe9 des anciens elfes de la nuit, jusqu\u2019\xe0 ce que la Fracture en pr\xe9cipite la plus grande partie dans la mer. Des terrasses en ruine s\u2019accrochent encore aux falaises, hant\xe9es par les esprits sans repos des Bien-n\xe9s ; nagas et satyres r\xf4dent sur le rivage, et l\u2019Alliance, \xe0 la pointe de Talrendis, comme la Horde, \xe0 Valormok, y tiennent de petits camps.","Dans Forever, une porte longtemps scell\xe9e d\u2019Azshara s\u2019ouvre sur Blackmaw Hold, une grande cit\xe9 furbolg dont le clan combat une corruption qui se r\xe9pand dans ses bosquets et ses tunnels. Ses profondeurs communiquent avec les Barrow Deeps et descendent plus loin encore."]},"zone:blasted-lands":{title:"Terres Foudroy\xe9es",summary:"Un d\xe9sert rouge et d\xe9vast\xe9 autour de la Porte des T\xe9n\xe8bres muette, surveill\xe9 par les mages et les paladins du donjon de Garde-N\xe9ant.",body:["Les terres Foudroy\xe9es faisaient autrefois partie du Noir Mar\xe9cage, jusqu\u2019\xe0 ce que la magie qui ouvrit la Porte des T\xe9n\xe8bres les d\xe9forme en un d\xe9sert rouge d\u2019argile craquel\xe9e. La grande porte par laquelle la Horde envahit le monde pour la premi\xe8re fois se dresse toujours ici, son cadre de pierre sombre et muet depuis sa destruction. Le donjon de Garde-N\xe9ant, une forteresse de mages et de paladins de Hurlevent, veille sur elle.","Peu de choses vivent dans cette \xe9tendue calcin\xe9e, hormis des scorpions, des basilics, des ogres Dreadmaul et quelques draene\xef exil\xe9s. Des d\xe9mons s\u2019y attardent aussi : le seigneur funeste Kazzak rassemble ce qui reste de la L\xe9gion ardente dans la Tainted Scar."]},"zone:felwood":{title:"Gangrebois",summary:"Une for\xeat jadis splendide empoisonn\xe9e par les d\xe9mons, o\xf9 les furbolgs Grumegueules et les druides luttent contre la pourriture.",body:["Le Gangrebois \xe9tait autrefois un paradis de ruisseaux et de prairies entretenu par les elfes de la nuit. Pendant la Troisi\xe8me Guerre, la L\xe9gion ardente le souilla avec la puissance du cr\xe2ne de Gul'dan, et la terre ne s\u2019en est jamais remise : ses rivi\xe8res charrient un venin vert, ses anciens et ses tr\xe9ants pourrissent sur place, et satyres, infernaux et le Conseil des ombres de Jaedenar, adorateur de d\xe9mons, hantent ses clairi\xe8res.","Les elfes de la nuit de la Talonbranch Glade, la Horde au Bloodvenom Post et les druides du sanctuaire d\u2019\xc9meraude s\u2019efforcent de repousser la corruption. Au nord, les Grumegueules, l\u2019une des derni\xe8res tribus furbolgs \xe9pargn\xe9es par la corruption, gardent les tunnels qui m\xe8nent \xe0 Reflet-de-Lune et \xe0 Berceau-de-l\u2019Hiver."]},"zone:un-goro-crater":{title:"Crat\xe8re d\u2019Un'Goro",summary:"Un crat\xe8re de jungle primitive peupl\xe9 de dinosaures, d\u2019\xe9l\xe9ments vivants et de pyl\xf4nes titaniques silencieux.",body:["Le crat\xe8re d\u2019Un'Goro est une jungle primitive et fumante enfonc\xe9e entre les d\xe9serts du sud de Kalimdor, un monde \xe0 part o\xf9 chassent les diablosaures, o\xf9 des \xe9l\xe9mentaires surgissent des sources chaudes et o\xf9 le Fire Plume Ridge fume en son centre. Les explorateurs se rassemblent au refuge des Marshal pour \xe9tudier ses cristaux rouges, bleus, verts et jaunes et les myst\xe9rieux pyl\xf4nes des cr\xeates du crat\xe8re, qui semblent \xeatre l\u2019\u0153uvre des titans.","Des silithides sont apparus au sud, venus de Silithus tout proche. Dans Forever, une antique installation titanique perch\xe9e au-dessus du crat\xe8re, Shaper's Terrace, s\u2019ouvre aux aventuriers qui rapportent des cristaux d\u2019\xe9nergie r\xe9colt\xe9s dans tout Un'Goro."]},"zone:burning-steppes":{title:"Steppes Ardentes",summary:"Des hautes terres \xe9touff\xe9es de cendres sous le mont Rochenoire, tenues par les orcs Rochenoire, les ogres Fire-Gut et les dragons noirs.",body:["Les steppes Ardentes sont des hautes terres d\xe9vast\xe9es de cendres, de lave et de pierre fumante, calcin\xe9es quand l\u2019invocation de Ragnaros par Thaurissan mit fin \xe0 la guerre des Trois Marteaux ; les ruines de l\u2019ancienne cit\xe9 sombrefer de Thaurissan s\u2019y dressent encore. Les steppes portent la seule route terrestre entre Hurlevent et Khaz Modan, et pourtant le royaume les a pratiquement abandonn\xe9es.","Au-dessus d\u2019elles se dresse le mont Rochenoire. Le pic Rochenoire, la grande forteresse de la Horde pendant la Deuxi\xe8me Guerre, est tenu par les orcs Rochenoire et les dragons noirs sous les ordres de Nefarian, tandis que les nains sombrefer r\xe8gnent sur les profondeurs. Des ogres Fire-Gut parcourent les plaines, et seuls l\u2019avant-poste de l\u2019Alliance de la veille de Morgan et le camp de la Horde de Flame Crest tiennent bon."]},"zone:western-plaguelands":{title:"Maleterres de l\u2019Ouest",summary:"Les terres agricoles fl\xe9tries de Lordaeron, o\xf9 le Fl\xe9au tient Andorhal et o\xf9 la tombe d\u2019Uther est la derni\xe8re terre sacr\xe9e.",body:["Les Maleterres de l\u2019Ouest comptaient jadis parmi les terres agricoles les plus riches de Lordaeron ; aujourd\u2019hui, une brume grise p\xe8se sur des champs malades et les morts-vivants errent dans des fermes abandonn\xe9es. Le bourg en ruine d\u2019Andorhal, o\xf9 le culte de Kel'Thuzad distribua son grain pestif\xe9r\xe9, est ici le plus grand bastion du Fl\xe9au, et des chaudrons de peste empoisonnent les champs alentour. Sur une \xeele du lac Darrowmere, Caer Darrow, le fort de la famille Barov, cache Scholomance, une \xe9cole de n\xe9cromancie.","La Croisade \xe9carlate combat depuis \xc2treval, au nord, l\u2019Alliance depuis le camp du Noro\xeet, et les R\xe9prouv\xe9s tiennent le Rempart \xe0 la fronti\xe8re avec Tirisfal. La tombe d\u2019Uther, lieu de repos du Porteur de Lumi\xe8re, est le seul endroit consacr\xe9 o\xf9 r\xe8gne la paix."]},"zone:eastern-plaguelands":{title:"Maleterres de l\u2019Est",summary:"Le coin le plus ravag\xe9 de Lordaeron tomb\xe9, gouvern\xe9 par le Fl\xe9au depuis la cit\xe9 br\xfbl\xe9e de Stratholme.",body:["Les Maleterres de l\u2019Est sont le vestige le plus ravag\xe9 du royaume de Lordaeron : une terre brune et malade, des arbres boursoufl\xe9s en champignons g\xe9ants et un air charg\xe9 de brume orang\xe9e. En leur centre se trouve Stratholme, la ville dont le prince Arthas passa les habitants au fil de l\u2019\xe9p\xe9e pendant la Troisi\xe8me Guerre, aujourd\u2019hui partag\xe9e entre le Fl\xe9au et la Croisade \xe9carlate.","La principale arm\xe9e de la Croisade tient la Main de Tyr et combat les morts-vivants avec beaucoup de z\xe8le mais peu de succ\xe8s, tandis que l\u2019Aube d\u2019argent accueille \xe0 la chapelle de l\u2019Espoir de Lumi\xe8re quiconque veut bien aider. Des villes fant\xf4mes comme Darrowshire et la crois\xe9e de Corin rappellent des batailles perdues, et les trolls amani frappent depuis Zul'Mashar, au nord, pour reprendre leurs terres ancestrales."]},"zone:winterspring":{title:"Berceau-de-l\u2019Hiver",summary:"Une vall\xe9e enneig\xe9e sur les flancs d\u2019Hyjal, partag\xe9e entre marchands gobelins, sabres-de-givre, dragons bleus et d\xe9mons.",body:["Berceau-de-l\u2019Hiver est une vall\xe9e de neiges presque \xe9ternelles sur les pentes du mont Hyjal, o\xf9 les elfes de la nuit commenc\xe8rent \xe0 reb\xe2tir apr\xe8s la Fracture. La ville gobeline de Long-Guet commerce avec tout le monde, les elfes de la nuit tiennent encore le village de Starfall, et les dresseurs du Frostsaber Rock \xe9l\xe8vent les f\xe9lins blancs de la vall\xe9e. Des dragons bleus ont leur repaire dans les grottes de Mazthoril.","Le sud de la vall\xe9e est tomb\xe9 aux mains des d\xe9mons dans la Darkwhisper Gorge, et les furbolgs Winterfall sont devenus sauvages. Dans Forever, l\u2019une des entr\xe9es du raid des Barrow Deeps se trouve en passant par Berceau-de-l\u2019Hiver."]},"zone:deadwind-pass":{title:"D\xe9fil\xe9 de Deuillevent",summary:"Un col mort et balay\xe9 par le vent, domin\xe9 par Karazhan, la tour du dernier Gardien, Medivh.",body:["Le d\xe9fil\xe9 de Deuillevent est un canyon d\xe9chiquet\xe9 d\u2019arbres p\xe9trifi\xe9s et sans feuilles entre le bois de la P\xe9nombre et le marais des Chagrins, o\xf9 souffle sans cesse un vent g\xe9missant. En son centre se dresse Karazhan, la tour d\u2019ivoire de Medivh, le dernier Gardien de Tirisfal, dont la possession par Sargeras ouvrit la voie \xe0 la Horde. Bien que Medivh soit mort depuis longtemps, sa tour laisse encore s\u2019\xe9chapper une magie noire dans la r\xe9gion.","Ogres de Deuillevent, d\xe9mons et esprits sans repos parcourent le d\xe9fil\xe9, les tombes du Morgan's Plot ne reposent pas en paix, et les voyageurs murmurent qu\u2019une nouvelle puissance a pris possession de la tour. La plupart des gens le traversent en h\xe2te."]},"zone:moonglade":{title:"Reflet-de-Lune",summary:"Un paisible sanctuaire druidique au nord de Kalimdor, foyer du Cercle c\xe9narien.",body:["Reflet-de-Lune est un vallon cach\xe9 du nord de Kalimdor, sacr\xe9 pour les druides depuis des milliers d\u2019ann\xe9es. Malfurion Hurlorage y rassembla les druides pour fonder le Cercle c\xe9narien, et le reflet du vallon dans le R\xeave d\u2019\xe9meraude est le lieu le plus sacr\xe9 de ce royaume. Dans la ville de Havrenuit, le gardien Remulos, fils de Cenarius, veille sur l\u2019ordre.","Depuis la Troisi\xe8me Guerre, le Cercle a ouvert Reflet-de-Lune \xe0 tous ceux qui suivent la voie druidique, et taurens et elfes de la nuit en partagent d\xe9sormais les rives en paix. Les gardiens de Reflet-de-Lune ne tol\xe8rent aucune violence dans le sanctuaire, et chaque ann\xe9e Havrenuit c\xe9l\xe8bre la f\xeate lunaire."]},"zone:silithus":{title:"Silithus",summary:"Un d\xe9sert br\xfbl\xe9 par le soleil et h\xe9riss\xe9 de ruches d\u2019insectes au sud-ouest de Kalimdor, o\xf9 le Cercle c\xe9narien surveille les portes scell\xe9es d\u2019Ahn'Qiraj.",body:["Silithus est un d\xe9sert torride \xe0 l\u2019extr\xeame sud-ouest de Kalimdor, seulement interrompu par les ruches g\xe9antes des silithides. Depuis la guerre des Sables changeants, les Qiraji insecto\xefdes sont enferm\xe9s derri\xe8re le mur du Scarab\xe9e \xe9lev\xe9 par les vols draconiques, mais leurs essaims de silithides n\u2019ont cess\xe9 de se multiplier.","Le Cercle c\xe9narien surveille la menace depuis le fort C\xe9narien, tandis que des cultistes du Marteau du cr\xe9puscule se rassemblent dans des camps \xe0 travers les dunes pour des desseins bien \xe0 eux. Derri\xe8re le mur, le temple-forteresse d\u2019Ahn'Qiraj attend."]}}},1598,[]);
__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"instances1",{enumerable:!0,get:function(){return s}});const s={"instance:hall-of-thanes":{title:"Hall of Thanes",summary:"La crypte royale de Forgefer, profan\xe9e par des intrus que les nains soup\xe7onnent d\u2019\xeatre des Sombrefer.",body:["Sous Forgefer s\u2019\xe9tend le Hall of Thanes, o\xf9 les nains inhument leurs souverains et entretiennent les tombeaux avec soin. Son entr\xe9e se trouve au seuil du High Seat, au c\u0153ur de la cit\xe9 : une simple promenade pour l\u2019Alliance, une intrusion audacieuse pour tout groupe de la Horde. Des intrus se sont d\xe9sormais fray\xe9 un chemin jusqu\u2019aux tombeaux sacr\xe9s. Les nains soup\xe7onnent le clan Sombrefer, et la vieille pierre bruisse de murmures spectraux.","La plupart de ses qu\xeates sont destin\xe9es \xe0 l\u2019Alliance et commencent \xe0 Kharanos ou aux abords de Forgefer, mais l\u2019une des qu\xeates de l\u2019int\xe9rieur est propos\xe9e par un fant\xf4me neutre. Quatre ennemis barrent la route : Faldrim Anvilmar, Magmatus, Plunder et Durgen Dirgehammer."],unknowns:["L\u2019identit\xe9 r\xe9elle des intrus ; le texte officiel dit seulement que les nains soup\xe7onnent le clan Sombrefer.","Ce qui s\u2019est \xe9veill\xe9 dans les salles, et l\u2019histoire de chacun des quatre ennemis."]},"instance:ragefire-chasm":{title:"Gouffre de Ragefeu",summary:"Des cavernes volcaniques sous Orgrimmar, o\xf9 des troggs et un culte au service des d\xe9mons menacent la nouvelle capitale de la Horde.",body:["Un d\xe9dale de cavernes \xe9clair\xe9es par la lave s\u2019\xe9tend sous Orgrimmar, et la Horde a appris que sa nouvelle capitale ne dort pas tranquille. Des troggs appel\xe9s les Ragefeu sont remont\xe9s des tunnels profonds, et lorsque l\u2019ancienne tauren Magatha Totem-sinistre a voulu faire la paix avec eux, elle n\u2019a rencontr\xe9 que la violence.","Pire encore, une secte appel\xe9e la Lame br\xfblante, fid\xe8le au d\xe9moniaque Conseil des ombres, s\u2019est cach\xe9e dans le gouffre pour comploter contre tout ce que le peuple de Thrall a b\xe2ti. Elle est men\xe9e par Taragaman l\u2019Affameur, un gangregarde, avec \xe0 ses c\xf4t\xe9s le d\xe9moniste Jergosh l\u2019Invocateur et le satyre Bazzalan. Pour beaucoup de jeunes h\xe9ros de la Horde, ces cavernes sont leur premier donjon."]},"instance:ruins-of-lordaeron":{title:"Ruins of Lordaeron",summary:"La capitale en ruine au-dessus de Fossoyeuse, o\xf9 les R\xe9prouv\xe9s reprennent leur pass\xe9 tandis qu\u2019un n\xe9cromancien amasse du pouvoir.",body:["Les R\xe9prouv\xe9s tentent de reprendre la capitale en ruine qui s\u2019\xe9tend au-dessus de leur Fossoyeuse. Les d\xe9combres renferment encore des reliques de famille et des souvenirs pr\xe9cieux, mais le Fl\xe9au hante les rues d\xe9vast\xe9es, et l\u2019on dit qu\u2019un n\xe9cromancien amasse du pouvoir entre les murs. Des aventuriers sont appel\xe9s pour aider \xe0 s\xe9curiser la cit\xe9.","Les groupes de la Horde rejoignent facilement l\u2019entr\xe9e depuis Fossoyeuse, tandis que ceux de l\u2019Alliance doivent s\u2019aventurer en territoire de la Horde. Les deux factions y trouvent des qu\xeates : celles de la Horde commencent \xe0 Fossoyeuse, dans la for\xeat des Pins-Argent\xe9s et \xe0 Tirisfal, celles de l\u2019Alliance dans les ruines m\xeames. Le chemin passe par Witherfang, The Baron, Viktor the Vile, The Abandoned et Bjork avant le dernier ennemi, Rath'mael."],unknowns:["L\u2019identit\xe9 du n\xe9cromancien et le but du pouvoir qu\u2019il amasse.","La part de l\u2019ancienne capitale que les R\xe9prouv\xe9s comptent reconstruire."]},"instance:deadmines":{title:"Les Mortemines",summary:"La mine d\u2019or abandonn\xe9e de la marche de l\u2019Ouest, o\xf9 la Confr\xe9rie d\xe9fias d\u2019Edwin VanCleef construit en secret un navire de guerre.",body:["Avant la Premi\xe8re Guerre, ces galeries \xe9taient les mines d\u2019or les plus riches des terres humaines ; le sac de Hurlevent par les orcs les laissa vides. La Confr\xe9rie d\xe9fias en a d\xe9sormais fait sa forteresse secr\xe8te. Son chef, Edwin VanCleef, \xe9tait un ma\xeetre tailleur de pierre qui aida \xe0 reconstruire Hurlevent apr\xe8s la guerre, jusqu\u2019\xe0 ce que les nobles de la cit\xe9 refusent de payer sa guilde. Trahis, ses ouvriers devinrent hors-la-loi et se r\xe9pandirent dans toute la marche de l\u2019Ouest.","Le chemin commence dans le village en ruine de Ruisselune. Tout en bas, des gobelins comme Sneed et Gilnid aident les D\xe9fias \xe0 achever un grand navire dans une crique cach\xe9e, gard\xe9e par M. Ch\xe2timent et le capitaine Vertepeau."]},"instance:wailing-caverns":{title:"Cavernes des Lamentations",summary:"Des cavernes sous les Tarides, o\xf9 le r\xeave de renouveau du druide Naralex a vir\xe9 au cauchemar.",body:["Les cavernes des Lamentations doivent leur nom aux g\xe9missements du vent et de la vapeur qui s\u2019\xe9chappent des fissures de la roche. Le druide elfe de la nuit Naralex les d\xe9couvrit et esp\xe9ra relier leurs sources souterraines au R\xeave d\u2019\xe9meraude, afin que la vie verdoyante se r\xe9pande de nouveau sur les Tarides arides. Mais pendant qu\u2019il m\xe9ditait, c\u2019est le Cauchemar d\u2019\xe9meraude qui l\u2019a submerg\xe9.","Prisonnier du sommeil, Naralex d\xe9verse d\xe9sormais cette corruption dans les cavernes. Leurs cr\xe9atures sont devenues des b\xeates d\xe9viantes, et la plupart de ses disciples ont sombr\xe9 dans la folie pour devenir les druides du Croc, parmi lesquels dame Anacondra et les seigneurs Cobrahn, Pythas et Serpentis. R\xe9veiller Naralex, c\u2019est affronter Mutanus le D\xe9voreur."]},"instance:shadowfang-keep":{title:"Donjon d\u2019Ombrecroc",summary:"Un donjon hant\xe9 de la for\xeat des Pins-Argent\xe9s, o\xf9 l\u2019archimage fou Arugal abrite les worgens qu\u2019il a d\xe9cha\xeen\xe9s.",body:["Le Kirin Tor perdait sa lutte contre le Fl\xe9au pendant la Troisi\xe8me Guerre, et chaque sorcier tomb\xe9 se relevait bient\xf4t dans le camp de l\u2019ennemi. L\u2019archimage Arugal ignora les avertissements de ses coll\xe8gues et chercha de l\u2019aide au-del\xe0 du monde, invoquant les sauvages worgens. Ceux-ci d\xe9chiquet\xe8rent les morts-vivants, puis les rangs m\xeames de Dalaran, et envahirent le donjon du baron d\u2019Argelaine, sur la colline qui domine Bois-du-B\xfbcher.","La culpabilit\xe9 brisa l\u2019esprit d\u2019Arugal. Il appelle d\xe9sormais les hommes-loups ses enfants et se cache avec eux dans le donjon, rebaptis\xe9 Ombrecroc et gard\xe9 par le grand loup Fenrus. Le fant\xf4me du baron ne l\u2019a jamais quitt\xe9, et les R\xe9prouv\xe9s des Pins-Argent\xe9s veulent la mort de l\u2019archimage."]},"instance:excavation-site-wetlands":{title:"Excavation Site: Wetlands",summary:"Une fouille au-dessus du Whelgar's Excavation Site a ouvert un lieu que le temps n\u2019a pas touch\xe9, gard\xe9 par des cr\xe9ations des titans \xe9gar\xe9es.",body:["Quelque chose s\u2019est \xe9veill\xe9 dans les collines des Paluns, pr\xe8s du rocher de Thelgen et de Dun Algaz. La brume descend les pentes au-dessus du Whelgar's Excavation Site, et des lueurs vacillent \xe0 l\u2019horizon. Au-del\xe0 de la fouille, la terre semble intacte depuis des \xe2ges ; des machines des titans \xe9gar\xe9es et une faune f\xe9roce gardent des secrets que la Ligue des explorateurs br\xfble de mettre au jour.","Les qu\xeates de l\u2019Alliance commencent au port de Menethil, au Greenwarden's Grove et \xe0 Comt\xe9-du-Lac, celles de la Horde \xe0 Orgrimmar et \xe0 Tr\xe9pas-d\u2019Orgrim. Saltspine et Shadetooth barrent la route du Relic Guardian, dont la d\xe9faite livre une relique des titans qui lance une qu\xeate pour les deux factions."],unknowns:["Ce qui s\u2019est \xe9veill\xe9 au-del\xe0 de la fouille, et ce qui cause la brume et les lueurs.","Qui a b\xe2ti ce lieu, et \xe0 quoi sert la relique des titans."]},"instance:stormwind-stockade":{title:"La Prison",summary:"La prison de Hurlevent, prise par ses propres d\xe9tenus lors d\u2019une \xe9meute men\xe9e par les D\xe9fias.",body:["La Prison se trouve au c\u0153ur de la cit\xe9 de Hurlevent et enferme voleurs, meurtriers et prisonniers politiques. Il y a peu, les d\xe9tenus se sont soulev\xe9s, ont r\xe9v\xe9l\xe9 leur all\xe9geance \xe0 la Confr\xe9rie d\xe9fias et ont chass\xe9 les gardes ; ce sont d\xe9sormais eux qui dirigent les quartiers de cellules.","Leur meneur est Bazil Thredd, un agent d\xe9fias. Parmi les prisonniers figurent l\u2019orc rochenoire Targorr le Terrifiant, le nain sombrefer Kam Furie-du-fond et le pilleur de tombes Dextren Ward. Plusieurs ont \xe9t\xe9 condamn\xe9s \xe0 mort, mais les lenteurs administratives de la noblesse ne cessaient de retarder les sentences ; Comt\xe9-du-Lac, Sombre-Comt\xe9 et m\xeame Forgefer envoient donc discr\xe8tement des aventuriers r\xe9gler l\u2019affaire."]},"instance:city-of-dalaran":{title:"City of Dalaran",summary:"La cit\xe9 du Kirin Tor dans les montagnes d\u2019Alterac, o\xf9 la barri\xe8re qui masquait sa restauration est tomb\xe9e et o\xf9 la magie se d\xe9cha\xeene.",body:["Pendant un temps, une barri\xe8re magique a dissimul\xe9 les travaux de restauration de Dalaran. Ce bouclier est maintenant tomb\xe9, et la cit\xe9 appara\xeet en plein chaos arcanique : les sorts ratent, des cr\xe9ations s\u2019\xe9chappent et la magie brute se d\xe9verse dans les rues. Le Kirin Tor a besoin d\u2019aide, mais seulement de gens en qui il a confiance.","Les h\xe9ros de l\u2019Alliance gagnent cette confiance en commen\xe7ant aupr\xe8s d\u2019Emissary Jacques \xe0 Austrivage ; ceux de la Horde commencent aupr\xe8s de Magus Wordeen Voidglare \xe0 Moulin-de-Tarren. Les deux chemins m\xe8nent \xe0 une image de l\u2019archimage Modera sur la rive sud du lac Lordamere, qui remet la Dalaran Sewer Key. Depuis les \xe9gouts, les groupes choisissent leur propre itin\xe9raire \xe0 travers la cit\xe9 jusqu\u2019\xe0 la source des troubles ; le dernier ennemi est le Shade of the Archmage."],unknowns:["Ce qui a provoqu\xe9 le d\xe9r\xe8glement, et de qui le dernier ennemi est l\u2019ombre.","L\u2019\xe9tat d\u2019avancement de la restauration de Dalaran."]},"instance:blackfathom-deeps":{title:"Profondeurs de Brassenoire",summary:"Un temple englouti d\u2019\xc9lune sur la c\xf4te d\u2019Orneval, devenu un sanctuaire o\xf9 des cultistes veillent sur une b\xeate des Dieux tr\xe8s anciens.",body:["Sur le rivage de Zoram, en Orneval, un puits cern\xe9 d\u2019escaliers plonge vers des salles inond\xe9es qui formaient jadis un temple d\u2019\xc9lune, la d\xe9esse lunaire des elfes de la nuit. La Fracture brisa le sanctuaire et l\u2019entra\xeena sous la mer, o\xf9 il dormit pendant des \xe2ges jusqu\u2019\xe0 ce que des nagas et des satyres, avides du pouvoir qui s\u2019y attarde encore, viennent l\u2019explorer.","Aujourd\u2019hui, le culte du Marteau du cr\xe9puscule prie dans les bassins les plus profonds sous la conduite du seigneur du Cr\xe9puscule Kelris et veille sur Aku'mai, une b\xeate monstrueuse ch\xe9rie des Dieux tr\xe8s anciens. Des chamans du Cercle terrestre sont venus les arr\xeater, car ils savent que tout appel aux Dieux tr\xe8s anciens met le monde entier en danger."]},"instance:razorfen-kraul":{title:"Kraal de Tranchebauge",summary:"Le terrier ancestral des huranes, n\xe9 des ronces qui jaillirent du sang d\u2019un demi-dieu tomb\xe9.",body:["Les huranes v\xe9n\xe8rent Agamaggan, le grand demi-dieu sanglier tu\xe9 pendant la guerre des Anciens. L\xe0 o\xf9 son sang tomba, des ronces g\xe9antes jaillirent de la terre, et leur plus grand entrelacs, \xe0 l\u2019extr\xeame sud des Tarides, est Tranchebauge, le lieu que les huranes honorent comme sa tombe.","Le kraal de Tranchebauge est leur foyer ancestral, un d\xe9dale de tani\xe8res et de tunnels couverts de ronces que gouverne Charlga Trancheflanc, la M\xe9g\xe8re. Des pr\xeatres de la tribu Death's Head arpentent d\xe9j\xe0 ses galeries, et des \xe9claireurs signalent des morts-vivants qui se rassemblent dans la r\xe9gion, signe redout\xe9 que le Fl\xe9au a jet\xe9 son d\xe9volu sur Kalimdor."]},"instance:gnomeregan":{title:"Gnomeregan",summary:"La capitale perdue des gnomes \xe0 Dun Morogh, empoisonn\xe9e par une purge radioactive apr\xe8s une invasion de troggs et le conseil d\u2019un tra\xeetre.",body:["B\xe2tie au plus profond des montagnes de Dun Morogh, Gnomeregan \xe9tait la plus grande merveille d\u2019ing\xe9nierie des gnomes. Puis des troggs jaillirent des profondeurs et l\u2019envahirent. Le Grand Mekanicien Mekkanivelle suivit le conseil de son conseiller, Sicco Thermojoncteur, et inonda la cit\xe9 de radiations pour tuer les envahisseurs, mais la purge tua aussi la plupart des gnomes. Les survivants s\u2019enfuirent \xe0 Forgefer.","C\u2019\xe9tait une trahison. Thermojoncteur resta sur place, se couronna seigneur des ruines et commande d\xe9sormais des gnomes l\xe9preux, des troggs et des machines folles comme l\u2019\xc9lectrocuteur 6000 et le Bastonneur de foule 9-60. Les exil\xe9s ont jur\xe9 de reprendre leur foyer."]},"instance:scarlet-monastery-graveyard":{title:"Monast\xe8re \xc9carlate : Cimeti\xe8re",summary:"Les cryptes du monast\xe8re de la Croisade \xe9carlate, o\xf9 son interrogateur officie et o\xf9 les morts refusent le repos.",body:["Le monast\xe8re du nord des clairi\xe8res de Tirisfal fut b\xe2ti comme maison d\u2019\xe9tude pour les pr\xeatres de Lordaeron. Apr\xe8s que le Fl\xe9au eut balay\xe9 le royaume pendant la Troisi\xe8me Guerre, les fanatiques de la Croisade \xe9carlate s\u2019en empar\xe8rent et en firent leur bastion. Ils soup\xe7onnent tout non-humain de porter la peste et accueillent les \xe9trangers avec des lames plut\xf4t qu\u2019avec des questions.","Le Cimeti\xe8re est la premi\xe8re aile que visitent la plupart des groupes. Ses cellules appartiennent \xe0 l\u2019interrogateur Vishas, le mage de sang Thalnos r\xf4de parmi les tombes, et des morts sans repos comme Azshir le Sans-Sommeil, \xc9chine-de-fer et le Champion d\xe9chu hantent les cryptes."]},"instance:scarlet-monastery-library":{title:"Monast\xe8re \xc9carlate : Biblioth\xe8que",summary:"Les archives de la Croisade \xe9carlate, o\xf9 un ma\xeetre-chien et un arcaniste gardent les livres de l\u2019ordre.",body:["Autrefois, les pr\xeatres de Lordaeron venaient \xe9tudier dans ce monast\xe8re de Tirisfal. La Croisade \xe9carlate, qui s\u2019en empara apr\xe8s la Troisi\xe8me Guerre, a gard\xe9 les livres mais perdu la douceur : ses fanatiques croient que tout non-humain pourrait propager la peste, et ils gardent leurs archives aussi farouchement que leurs murs.","Le ma\xeetre-chien Loksey et ses chiens traquent les intrus dans les salles ext\xe9rieures, et l\u2019arcaniste Doan veille sur les rayonnages int\xe9rieurs. Beaucoup viennent pour les livres eux-m\xeames : des \xe9rudits de Forgefer veulent un volume sur la mythologie des titans, tandis que les R\xe9prouv\xe9s cherchent la chronique que la Croisade tient elle-m\xeame sur les morts."]},"instance:drowned-city":{title:"Drowned City",summary:"D\u2019anciennes ruines trolls sorties de la mer au large de la vall\xe9e de Strangleronce, o\xf9 r\xf4dent d\xe9sormais trolls et nagas.",body:["Au large de la vall\xe9e de Strangleronce, \xe0 l\u2019ouest de Grom'gol, une cit\xe9 troll que la mer avait engloutie est remont\xe9e \xe0 la surface. Des rues que personne n\u2019avait foul\xe9es depuis des \xe2ges s\u2019ouvrent d\xe9sormais \xe0 l\u2019air libre, trolls et nagas s\u2019y sont d\xe9j\xe0 install\xe9s, et un navire pirate tout proche semble avoir connu une tr\xe8s mauvaise fin.","Pour entrer, les groupes plongent et cherchent le passage sous la ligne de flottaison. Une fois \xe0 l\u2019int\xe9rieur, ils combattent \xe0 ciel ouvert pendant que le temps se g\xe2te : la brume se change en pluie, puis la pluie en v\xe9ritable temp\xeate lors du combat final."],unknowns:["Pourquoi la cit\xe9 est remont\xe9e maintenant, et quel peuple troll l\u2019a b\xe2tie.","Qui dirige les trolls et les nagas \xe0 l\u2019int\xe9rieur ; les donn\xe9es de ce guide n\u2019indiquent encore aucun boss.","Ce qui est arriv\xe9 au navire pirate."]},"instance:scarlet-monastery-armory":{title:"Monast\xe8re \xc9carlate : Armurerie",summary:"Le terrain d\u2019entra\xeenement et l\u2019arsenal de la Croisade \xe9carlate, sous la f\xe9rule de son champion Herod.",body:["Derri\xe8re les murs du monast\xe8re des clairi\xe8res de Tirisfal, la Croisade \xe9carlate entra\xeene ses soldats. L\u2019ordre est n\xe9 de la ruine de Lordaeron pendant la Troisi\xe8me Guerre et croit que quiconque n\u2019est pas humain peut porter la peste ; ses recrues apprennent donc \xe0 frapper les premi\xe8res.","L\u2019Armurerie abrite les cours d\u2019entra\xeenement, les casernes et les r\xe9serves d\u2019armes, et son ma\xeetre est Herod, le champion \xe9carlate, une brute colossale qui manie une hache \xe9norme et tournoie au milieu de ses assaillants. Le vaincre prouve qu\u2019un groupe est pr\xeat pour la cath\xe9drale, au c\u0153ur du monast\xe8re."]},"instance:razorfen-downs":{title:"Souilles de Tranchebauge",summary:"Les antiques terres fun\xe9raires des huranes, prises par le Fl\xe9au sous la conduite de la liche Amnennar le Porte-froid.",body:["Les souilles de Tranchebauge poussent des m\xeames ronces g\xe9antes que le kraal, et c\u2019est l\xe0 que les huranes enterrent leurs morts. Leurs grands pr\xeatres, les Death's Head, veillaient jadis sur la saintet\xe9 de ces lieux. Tout changea lorsque le Fl\xe9au atteignit Kalimdor : la liche Amnennar le Porte-froid prit les pr\xeatres de la tribu \xe0 son service et remplit les ronciers de morts relev\xe9s.","Les huranes libres luttent d\xe9sormais pour reprendre leur cit\xe9 fun\xe9raire avant que le pouvoir de la liche ne s\u2019\xe9tende au reste des Tarides. Un groupe doit se frayer un chemin au-del\xe0 de Tuten'kash, de Mordresh \u0152il-de-feu, de Glouton et de Gueule-de-peste le Pourrissant pour atteindre Amnennar lui-m\xeame."]},"instance:scarlet-monastery-cathedral":{title:"Monast\xe8re \xc9carlate : Cath\xe9drale",summary:"Le c\u0153ur du Monast\xe8re \xe9carlate, o\xf9 le commandant Mograine m\xe8ne les fid\xe8les et o\xf9 la grande inquisitrice Blanchet\xeate rel\xe8ve les morts.",body:["La cath\xe9drale est le c\u0153ur du monast\xe8re de la Croisade \xe9carlate dans les clairi\xe8res de Tirisfal et le si\xe8ge de ses dirigeants sur place. Le commandant \xe9carlate Mograine commande la garnison fanatique, mais la v\xe9ritable autorit\xe9 appartient \xe0 la grande inquisitrice Blanchet\xeate, une pr\xeatresse capable de rappeler son champion tomb\xe9 pour qu\u2019il combatte de nouveau.","La Croisade est n\xe9e de la chute de Lordaeron et voit toujours la peste en chaque \xe9tranger. C\u2019est ici que sa conviction br\xfble le plus fort : le commandant se bat jusqu\u2019au bout, et lorsqu\u2019il tombe, Blanchet\xeate quitte le ch\u0153ur pour poursuivre le combat et le relever encore."]}}},1599,[]);
__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"instances2",{enumerable:!0,get:function(){return s}});const s={"instance:kroldok-stronghold":{title:"Krol'dok Stronghold",summary:"Une forteresse ogre des Riverglades dont les pillards enl\xe8vent les voyageurs, et d\u2019o\xf9 montent des chants \xe0 la nuit tomb\xe9e.",body:["Krol'dok est la forteresse ogre des Riverglades, et son histoire remonte aux ann\xe9es qui suivirent la Deuxi\xe8me Guerre. Lorsque les forces de l\u2019ancienne Horde dans la r\xe9gion assi\xe9g\xe8rent Farholde Keep, Fern Crimsonleaf se glissa dans leur camp et tua leurs chefs. Priv\xe9e de commandement, l\u2019arm\xe9e, pourtant plus nombreuse, perdit une bataille co\xfbteuse face \xe0 la Brotherhood of the Horse et se replia sur Krol'dok.","Aujourd\u2019hui, ses \xe9claireurs ogres frappent partout dans les Riverglades, enlevant des voyageurs et pillant des colonies. Leur piste s\u2019ach\xe8ve \xe0 une vaste forteresse faite d\u2019ateliers, de camps et de passages \xe9troitement surveill\xe9s. Les groupes y p\xe9n\xe8trent pour mettre fin aux raids et comprendre le sens des chants \xe9tranges qui montent de la forteresse \xe0 la nuit tomb\xe9e."],unknowns:["Qui commande aujourd\u2019hui la forteresse ; les donn\xe9es de ce guide n\u2019indiquent encore aucun boss.","Ce que sont ces chants et qui les dirige.","Le lien entre ces ogres, le Marteau du cr\xe9puscule et les ogres Bolder'ok ailleurs dans les Riverglades."]},"instance:uldaman":{title:"Uldaman",summary:"Une chambre forte des titans dans les Terres ingrates, o\xf9 des fouilleurs nains r\xe9veill\xe8rent les troggs et trouv\xe8rent des indices sur leurs propres origines.",body:["Uldaman est une chambre forte que les gardiens des titans scell\xe8rent au plus profond des montagnes de Khaz Modan, dans ce qui forme aujourd\u2019hui les Terres ingrates. Elle devait renfermer les troggs, une cr\xe9ation ancienne que les titans jugeaient rat\xe9e. Avant la Troisi\xe8me Guerre, des fouilleurs de Forgefer y p\xe9n\xe9tr\xe8rent, et les troggs qu\u2019ils r\xe9veill\xe8rent massacr\xe8rent la plus grande partie de l\u2019exp\xe9dition.","Aujourd\u2019hui, la Ligue des explorateurs, des pillards sombrefer et des tribus de troggs se disputent ses salles. Tout au fond reposent les Disques de Norgannon, des archives des titans r\xe9v\xe9lant que les nains descendent des terrestres \xe0 la peau de pierre, gard\xe9s par Archaedas, forg\xe9 par les titans, qui se dresse encore contre quiconque trouble sa chambre forte."]},"instance:zulfarrak":{title:"Zul'Farrak",summary:"La cit\xe9 br\xfbl\xe9e par le soleil des trolls Furie-des-sables en Tanaris, o\xf9 un dieu hydre dort dans un bassin sacr\xe9.",body:["Tanaris \xe9tait autrefois une jungle et faisait partie des terres des trolls Gurubashi, et Zul'Farrak \xe9tait l\u2019une de leurs cit\xe9s. Lorsque la Fracture transforma la r\xe9gion en d\xe9sert, les trolls farraki rest\xe9s sur place s\u2019adapt\xe8rent et devinrent des trolls des sables. Aujourd\u2019hui, la cit\xe9 appartient \xe0 la tribu Furie-des-sables, redout\xe9e pour sa cruaut\xe9 et sa magie noire.","Les aventuriers y viennent pour bien des raisons. La rumeur place les deux moiti\xe9s de l\u2019\xe9p\xe9e troll bris\xe9e Sul'thraze la Flagelleuse entre ses murs, une bande de mercenaires en fuite depuis Gadgetzan s\u2019y est \xe9gar\xe9e et a \xe9t\xe9 captur\xe9e, et dans un bassin sacr\xe9, au c\u0153ur de la cit\xe9, dort Gahz'rilla, une hydre que les Furie-des-sables v\xe9n\xe8rent comme un demi-dieu et ne r\xe9veillent que lorsqu\u2019ils ont des sacrifices \xe0 offrir."]},"instance:alcaz-prison":{title:"Alcaz Prison",summary:"Une prison longtemps entour\xe9e de rumeurs sur l\u2019\xeele d\u2019Alcaz, dans le mar\xe9cage d\u2019\xc2prefange, enfin ouverte, o\xf9 D\xe9fias et nagas sont en guerre.",body:["Le mar\xe9cage d\u2019\xc2prefange bruisse depuis longtemps de rumeurs sur l\u2019\xeele d\u2019Alcaz et sur les captifs de haut rang qui y seraient d\xe9tenus ; certaines vont jusqu\u2019\xe0 citer le roi Varian Wrynn de Hurlevent. Personne n\u2019a jamais pu atteindre la prison pour d\xe9couvrir la v\xe9rit\xe9. Aujourd\u2019hui, ses portes sont ouvertes.","\xc0 l\u2019int\xe9rieur, la Confr\xe9rie d\xe9fias et les nagas se combattent. Les groupes profitent du chaos pour fouiller les cellules, affronter ceux qui les tiennent et recueillir de nouveaux indices sur un myst\xe8re que les royaumes connaissent d\xe9j\xe0 bien."],unknowns:["Si le roi Varian Wrynn est ou a \xe9t\xe9 d\xe9tenu ici ; le texte officiel ne rapporte que des rumeurs.","Qui dirige la prison, et pourquoi D\xe9fias et nagas se combattent.","Quels boss attendent \xe0 l\u2019int\xe9rieur ; les donn\xe9es de ce guide n\u2019en indiquent encore aucun."]},"instance:maraudon":{title:"Maraudon",summary:"Les cavernes sacr\xe9es des centaures en D\xe9solace, empoisonn\xe9es par le chagrin de la princesse de la terre Theradras.",body:["La l\xe9gende raconte une sombre histoire sur la naissance des centaures. Leur p\xe8re \xe9tait Zaetar, un fils du demi-dieu Cenarius ; leur m\xe8re \xe9tait la princesse Theradras, fille du seigneur \xe9l\xe9mentaire de la terre. Les premiers centaures se retourn\xe8rent contre Zaetar et le tu\xe8rent, et l\u2019on dit que Theradras, \xe9plor\xe9e, encha\xeena son esprit dans Maraudon, un acte dont la corruption empoisonne encore les cavernes.","Les clans centaures tiennent Maraudon pour une s\xe9pulture sacr\xe9e, mais des fant\xf4mes de centaures sans repos, des \xe9l\xe9mentaires d\xe9form\xe9s et des cr\xe9atures v\xe9g\xe9tales venimeuses envahissent d\xe9sormais la Wicked Grotto, la Foulspore Cavern et les Earth Song Falls. Celebras, le neveu de Zaetar, vint lib\xe9rer l\u2019esprit de son oncle et succomba lui-m\xeame \xe0 la corruption. Tout au fond attend Theradras."]},"instance:temple-of-atalhakkar":{title:"Temple d\u2019Atal'Hakkar",summary:"Le temple englouti du marais des Chagrins, o\xf9 des pr\xeatres atal'ai tentent toujours d\u2019appeler leur dieu du sang, Hakkar.",body:["Les Atal'ai \xe9taient des pr\xeatres trolls qui voulaient faire venir dans le monde Hakkar l\u2019\xc9corcheur d\u2019\xe2mes, le dieu du sang, et la lutte pour les arr\xeater d\xe9chira l\u2019empire gurubashi il y a plus de mille ans. Vaincus et chass\xe9s, ils b\xe2tirent un temple dans le marais des Chagrins pour pr\xe9parer son retour, jusqu\u2019\xe0 ce que l\u2019Aspect Ysera d\xe9couvre le projet et l\u2019engloutisse dans la fange.","Depuis, des dragons verts veillent sur les ruines englouties, mais les Atal'ai ont surv\xe9cu et prient toujours Hakkar sous la conduite de Jammal'an le proph\xe8te. Plus bas encore s\u2019attarde l\u2019ombre d\u2019Eranikus, le consort d\u2019Ysera, l\u2019esprit obscurci par le Cauchemar d\u2019\xe9meraude."]},"instance:blackrock-depths":{title:"Profondeurs de Rochenoire",summary:"La cit\xe9 d\u2019Ombreforge, capitale des nains sombrefer au c\u0153ur du mont Rochenoire, gouvern\xe9e par l\u2019empereur Dagran Thaurissan dans l\u2019ombre de Ragnaros.",body:["Il y a plus de deux si\xe8cles, le thane-sorcier sombrefer Thaurissan tenta de gagner une guerre perdue par une invocation d\xe9sesp\xe9r\xe9e et fit venir \xe0 la place Ragnaros, le seigneur du Feu. L\u2019explosion fit surgir le mont Rochenoire et lia son clan \xe0 la volont\xe9 du seigneur du Feu. Leurs descendants peinent encore pour Ragnaros dans les tunnels br\xfblants sous la montagne.","Les profondeurs de Rochenoire sont leur royaume : une prison, l\u2019ar\xe8ne appel\xe9e Ring of Law, la taverne du Grim Guzzler, la Forge noire et la cit\xe9 d\u2019Ombreforge elle-m\xeame. L\u2019empereur Dagran Thaurissan y si\xe8ge sur son tr\xf4ne aux c\xf4t\xe9s de la princesse Moira Barbe-de-bronze, dont le p\xe8re, le roi Magni de Forgefer, croit qu\u2019elle y est retenue par un sortil\xe8ge."]},"instance:warpwood-quarter":{title:"Warpwood Quarter",summary:"Le quartier est de l\u2019Eldre'Thalas en ruine, envahi de plantes corrompues sous la coupe du satyre Alzzin the Wildshaper.",body:["Hache-Tripes, en F\xe9ralas, \xe9tait autrefois Eldre'Thalas, une cit\xe9 o\xf9 les arcanistes les plus secrets de la reine Azshara gardaient son pr\xe9cieux savoir. La Fracture la laissa en ruine, et au fil des \xe2ges ogres, satyres et cr\xe9atures plus \xe9tranges encore s\u2019install\xe8rent dans ses quartiers.","Le Warpwood Quarter, \xe0 l\u2019est, est tomb\xe9 aux mains d\u2019Alzzin the Wildshaper, un satyre qui corrompit le Fruit de fertilit\xe9, lequel ne donne plus que d\u2019immondes gangrelianes. Anciens tordus, flagellants, d\xe9mons et satyres lui ob\xe9issent, et tout le quartier est retourn\xe9 \xe0 l\u2019\xe9tat sauvage. M\xeame le fac\xe9tieux diablotin Pusillin entra\xeene les intrus dans une joyeuse course-poursuite \xe0 travers ses salles."]},"instance:blackmaw-hold":{title:"Blackmaw Hold",summary:"Une grande cit\xe9 furbolg derri\xe8re une porte longtemps scell\xe9e en Azshara, o\xf9 le clan Blackmaw combat une corruption qui se r\xe9pand.",body:["Derri\xe8re une porte d\u2019Azshara rest\xe9e close pendant tr\xe8s longtemps s\u2019\xe9tend une grande cit\xe9 des furbolgs. Le clan Blackmaw qui y vit combat une corruption qui s\u2019infiltre dans ses bosquets et le long des tunnels sinueux sous les montagnes.","La forteresse est une longue aventure pour les groupes au niveau maximum, avec plusieurs itin\xe9raires et de nombreux boss. Ses profondeurs cacheraient un chemin menant plus loin encore sous Azeroth, et l\u2019aper\xe7u des raids de Blizzard cite Blackmaw Hold comme l\u2019une des entr\xe9es des Barrow Deeps."],unknowns:["Ce qu\u2019est la corruption et d\u2019o\xf9 elle vient.","Qui a scell\xe9 la porte, et pourquoi.","Quels boss attendent \xe0 l\u2019int\xe9rieur ; les donn\xe9es de ce guide n\u2019en indiquent encore aucun."]},"instance:lower-blackrock-spire":{title:"Pic Rochenoire inf\xe9rieur",summary:"Les salles basses du pic qui couronne le mont Rochenoire, casernes de la Horde noire de Rend Main-Noire.",body:["Pendant des si\xe8cles, le pic qui couronne le mont Rochenoire fut un bastion sombrefer. Cela prit fin lorsque Nefarian, fils d\u2019Aile-de-mort, s\u2019empara de ses niveaux sup\xe9rieurs avec ses dragonides et se retourna contre les nains. Il trouva un alli\xe9 en Rend Main-Noire, un orc qui se proclame chef de guerre d\u2019une Horde noire refusant de suivre Thrall.","Le pic Rochenoire inf\xe9rieur abrite les casernes de cette Horde noire. L\xe9gions d\u2019orcs rochenoires, ogres Spirestone du g\xe9n\xe9ralissime Omokk, trolls Smolderthorn du chasseur des ombres Vosh'gajin et araign\xe9es de Mother Smolderweb se partagent ses salles en ruine sous les ordres du seigneur Wyrmthalak. L\u2019\xe9lite et les dragons attendent plus haut encore, dans le pic Rochenoire sup\xe9rieur."]},"instance:capital-gardens":{title:"Capital Gardens",summary:"Le quartier ouest d\u2019Eldre'Thalas, o\xf9 les derniers Bien-n\xe9s shen'dralar se nourrissent d\u2019un d\xe9mon captif.",body:["Eldre'Thalas, aujourd\u2019hui appel\xe9e Hache-Tripes, fut b\xe2tie pour garder les secrets arcaniques de la reine Azshara, et ses gardiens, les Shen'dralar, surv\xe9curent \xe0 la Fracture. Priv\xe9s du pouvoir du Puits d\u2019\xe9ternit\xe9, leur chef, le prince Tortheldrin, fit dresser cinq pyl\xf4nes pour emprisonner le d\xe9mon Immol'thar, et son peuple puisa dans son \xe9nergie pour rester immortel.","Au fil des si\xe8cles, la prison s\u2019affaiblit. Pour conserver son propre pouvoir, Tortheldrin se retourna contre les autres Shen'dralar et les vida de leur \xe9nergie. Les Capital Gardens, autrefois parc et cour des Bien-n\xe9s, abritent d\xe9sormais ses derniers fid\xe8les, des arbres fl\xe9tris, des anciens furieux et le d\xe9mon captif lui-m\xeame."]},"instance:scholomance":{title:"Scholomance",summary:"L\u2019\xe9cole de n\xe9cromancie de Kel'Thuzad dans les cryptes de Caer Darrow, livr\xe9e au Fl\xe9au par la famille Barov.",body:["Sur une \xeele du lac Darrowmere, dans les Maleterres de l\u2019Ouest, se dresse Caer Darrow, autrefois le fort de la noble famille Barov. Lorsque le sorcier Kel'Thuzad rassembla des fid\xe8les pour son culte des Damn\xe9s, il promit l\u2019immortalit\xe9 au nom du roi-liche, et les Barov lui c\xe9d\xe8rent leur fort et ses cryptes. Le culte fit des cryptes la Scholomance, une \xe9cole o\xf9 les n\xe9cromanciens apprenaient \xe0 r\xe9pandre la peste.","Les Barov virent leur v\u0153u exauc\xe9 de la pire des fa\xe7ons et hantent d\xe9sormais les salles sous forme de morts-vivants. La liche Ras Murmegivre dirige l\u2019\xe9cole pour le Fl\xe9au, le sombre ma\xeetre Gandling en est le directeur, et le Voracien r\xf4de en contrebas, pr\xeat \xe0 d\xe9vorer les \xe9l\xe8ves trop faibles."]},"instance:shapers-terrace":{title:"Shaper's Terrace",summary:"Une ancienne installation des titans dans les collines nord du crat\xe8re d\u2019Un'Goro, aliment\xe9e par des cristaux de pouvoir r\xe9colt\xe9s dans tout le crat\xe8re.",body:["Sur les hauteurs nord du crat\xe8re d\u2019Un'Goro, une ancienne installation des titans domine une terre que le temps semble avoir \xe9pargn\xe9e. Dinosaures, fosses de goudron, structures titaniques et cristaux luisants font tous partie de cette exp\xe9dition, destin\xe9e aux groupes proches du niveau maximum.","Son \xe9nigme d\xe9passe ses murs : les groupes r\xe9coltent des cristaux de pouvoir dans le crat\xe8re et les utilisent sur des consoles \xe0 l\u2019int\xe9rieur de la terrasse, si bien que ce qu\u2019ils trouvent dans la nature fa\xe7onne les \xe9preuves qui les attendent."],unknowns:["Qui a b\xe2ti la terrasse et \xe0 quoi elle servait.","Ce que font les consoles et quels boss attendent \xe0 l\u2019int\xe9rieur ; les donn\xe9es de ce guide n\u2019en indiquent encore aucun."]},"instance:stratholme":{title:"Stratholme",summary:"La ruine en flammes de la grande cit\xe9 du nord de Lordaeron, partag\xe9e entre le Fl\xe9au du baron Vaillefendre et la Croisade \xe9carlate.",body:["Stratholme \xe9tait la cit\xe9 la plus fi\xe8re du nord de Lordaeron et le berceau de l\u2019ordre de la Main d\u2019argent. Pendant la Troisi\xe8me Guerre, le prince Arthas la fit passer au fil de l\u2019\xe9p\xe9e plut\xf4t que de laisser ses habitants touch\xe9s par la peste se relever en morts-vivants, rompant ainsi avec son mentor Uther. Le Fl\xe9au s\u2019y installa peu apr\xe8s, et la cit\xe9 br\xfble depuis.","Aujourd\u2019hui, deux ennemis se la partagent. La Croisade \xe9carlate tient un c\xf4t\xe9 sous les ordres du grand crois\xe9 Dathrohan, sans se douter qu\u2019il s\u2019agit du seigneur de l\u2019effroi Balnazzar d\xe9guis\xe9. L\u2019autre c\xf4t\xe9 appartient au Fl\xe9au et au chevalier de la mort baron Vaillefendre, riche propri\xe9taire terrien de Stratholme et ami de Kel'Thuzad avant de rejoindre le culte des Damn\xe9s."]},"instance:gordok-commons":{title:"Gordok Commons",summary:"Le quartier nord de Hache-Tripes, si\xe8ge du roi Gordok et de ses ogres, o\xf9 celui qui tue le roi prend la couronne.",body:["Des ogres du clan Gordunni ont pris le quartier nord de l\u2019antique Eldre'Thalas, la cit\xe9 des Bien-n\xe9s en ruine aujourd\u2019hui appel\xe9e Hache-Tripes. Leurs guerriers les plus forts, les Gordok, r\xe8gnent depuis les Commons, et leur roi prend le nom de roi Gordok.","La coutume ogre est ici simple : quiconque tue le roi devient le nouveau roi Gordok. Les groupes habiles se glissent entre les gardes Mol'dar, Fengus et Slip'kik, Kreeg le Marteleur et le capitaine Kromcrush pour ne frapper que le roi, et les ogres survivants traitent les vainqueurs comme leurs nouveaux ma\xeetres et leur versent un tribut. Cho'Rush l\u2019Observateur se tient aux c\xf4t\xe9s du roi."]},"instance:barrow-deeps":{title:"Barrow Deeps",summary:"Un raid \xe0 dix joueurs dans la prison sous Kalimdor qui retint Illidan Hurlorage pendant dix mille ans.",body:["Profond\xe9ment sous Kalimdor, les Barrow Deeps retinrent Illidan Hurlorage prisonnier pendant dix mille ans. Le chemin vers leurs tunnels est d\xe9sormais ouvert, et des raids y descendent pour d\xe9couvrir ce qu\u2019il est advenu de ceux rest\xe9s dans les t\xe9n\xe8bres et ce que les gardiennes comptent faire face \xe0 la menace qui s\u2019\xe9veille en dessous.","Trois chemins y m\xe8nent, reli\xe9s au mont Hyjal, \xe0 Berceau-de-l\u2019Hiver et \xe0 Blackmaw Hold. Dix joueurs affrontent huit boss pendant la descente, de la Deepscar Matriarch et de Khalith the Dreadspinner jusqu\u2019\xe0 Del'lynar Songwood et, tout \xe0 la fin, Sonya Darkhallow."],unknowns:["Qui a ouvert les passages, et quel est le danger qui guette en dessous.","Qui sont les gardiennes, et l\u2019histoire des huit boss."]},"instance:hyjal-summit":{title:"Hyjal Summit",summary:"Un raid \xe0 vingt joueurs au sommet du mont Hyjal, pr\xe8s de l\u2019Arbre-Monde Nordrassil, avec treize boss et de nombreux chemins.",body:["Hyjal Summit se trouve au sommet du mont Hyjal, pr\xe8s de l\u2019Arbre-Monde Nordrassil. Un antique gardien barre le passage au d\xe9part ; ensuite, les raids choisissent leurs propres itin\xe9raires \xe0 travers la montagne, parmi des ruines \xe0 la surface et sous terre, et combattent tout ce qui menace Hyjal jusqu\u2019\xe0 ce que s\u2019ouvre le chemin des derniers affrontements.","Vingt joueurs affrontent treize boss, parmi lesquels Bandalar, le Time-Lost Battalion, le Council of Thorns, le Wild King et l\u2019Ancient of Decay. Le dernier de tous est Nythus the Dreambound."],unknowns:["Quelle force menace Hyjal ; l\u2019aper\xe7u officiel ne la nomme pas.","Qui est l\u2019antique gardien, et qui est Nythus the Dreambound."]},"instance:onyxias-lair":{title:"Repaire d\u2019Onyxia",summary:"Le repaire d\u2019Onyxia, m\xe8re de la couv\xe9e du Vol noir, dans le mar\xe9cage d\u2019\xc2prefange ; seuls les porteurs de l\u2019amulette Feu-du-drake peuvent y entrer.",body:["Dans le Wyrmbog du mar\xe9cage d\u2019\xc2prefange, Onyxia, fille d\u2019Aile-de-mort et s\u0153ur de Nefarian, garde sa couv\xe9e dans une caverne de feu. Sa meilleure arme est la tromperie. Sous forme humaine, sous les traits de dame Katrana Prestor, elle murmure \xe0 la cour de Hurlevent et s\u2019emploie \xe0 dresser les royaumes mortels les uns contre les autres.","Quarante joueurs l\u2019affrontent dans un combat de flammes en trois phases ; les raids r\xe9unissent donc d\u2019abord de la r\xe9sistance au feu. Chaque membre doit aussi porter l\u2019amulette Feu-du-drake, obtenue au terme d\u2019une longue suite de qu\xeates : pour l\u2019Alliance, l\u2019\xe9vasion du mar\xe9chal Windsor des profondeurs de Rochenoire et la r\xe9v\xe9lation \xe0 Hurlevent ; pour la Horde, Rexxar et le drake Emberstrife. Les deux s\u2019ach\xe8vent avec le g\xe9n\xe9ral Drakkisath, dans le pic Rochenoire sup\xe9rieur."]}}},1600,[]);
__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"items",{enumerable:!0,get:function(){return n}});const n={"item:demon-soul":{title:"L\u2019\xc2me des dragons (\xc2me du d\xe9mon)",summary:"Un disque d\u2019or forg\xe9 par Neltharion pour dominer tous les dragons ; il donna naissance \xe0 Aile-de-mort et, des \xe2ges plus tard, encha\xeena le Vol rouge \xe0 la Horde.",body:["Avant la guerre des Anciens, le Gardien de la Terre Neltharion fit fabriquer par ses serviteurs gobelins un disque d\u2019or d\u2019apparence banale, secr\xe8tement impr\xe9gn\xe9 de la corruption des Dieux tr\xe8s anciens. Il persuada les autres Aspects d\u2019y verser une part de leur pouvoir pour combattre la L\xe9gion ardente, puis le retourna contre les d\xe9mons comme contre ses alli\xe9s. Les \xe9nergies de l\u2019\xc2me des dragons d\xe9chir\xe8rent son corps, et Neltharion devint Aile-de-mort.","Apr\xe8s la Fracture, les Aspects cach\xe8rent le disque au plus profond de ce qui forme aujourd\u2019hui les Carmines. Guid\xe9 par les visions d\u2019Aile-de-mort, le clan Gueule-de-dragon le retrouva, le rebaptisa \xc2me du d\xe9mon et s\u2019en servit pour asservir Alexstrasza \xe0 Grim Batol. C\u2019est l\xe0 qu\u2019il fut finalement bris\xe9, et les dragons rouges retrouv\xe8rent leur libert\xe9."]},"item:atiesh":{title:"Atiesh, grand b\xe2ton du Gardien",summary:"Le b\xe2ton des Gardiens de Tirisfal, port\xe9 en dernier par Medivh, puis bris\xe9 et recherch\xe9 par Kel'Thuzad.",body:["Atiesh passa de Gardien en Gardien pendant des g\xe9n\xe9rations, jusqu\u2019\xe0 Medivh, le dernier d\u2019entre eux. La l\xe9gende veut qu\u2019il soit n\xe9 d\u2019une \xab graine de haine \xbb et qu\u2019il accorde \xe0 son porteur un pouvoir sans fin ; les corbeaux se rassemblent autour de lui, et il peut ouvrir un chemin vers Karazhan. Apr\xe8s la chute de Medivh, le Kirin Tor enferma le b\xe2ton \xe0 Dalaran, o\xf9 chaque mage qui le toucha connut une fin funeste.","Quand Archimonde d\xe9truisit Dalaran, Atiesh se brisa en des dizaines de fragments \xe9parpill\xe9s \xe0 travers Azeroth, et Kel'Thuzad entreprit de les rassembler. Dans le jeu d\u2019origine, les raids arrachaient ses \xe9clats \xe0 sa n\xe9cropole de Naxxramas, faisaient restaurer l\u2019armature avec l\u2019aide du dragon de bronze Anachronos, puis devaient purifier le b\xe2ton \xe0 Stratholme en vainquant le d\xe9mon emprisonn\xe9 \xe0 l\u2019int\xe9rieur."]},"item:scepter-of-the-shifting-sands":{title:"Le sceptre des Sables changeants",summary:"La cl\xe9 du mur du Scarab\xe9e qui scellait Ahn'Qiraj, bris\xe9e par un Fandral Forteramure fou de chagrin.",body:["Pr\xe8s de mille ans avant la Premi\xe8re Guerre, les qiraji insecto\xefdes d\xe9ferl\xe8rent hors d\u2019Ahn'Qiraj, pouss\xe9s par le Dieu tr\xe8s ancien C'Thun. L\u2019archidruide Fandral Forteramure mena les elfes de la nuit contre eux, mais son fils Valstann fut abattu sous ses yeux, et la guerre tourna. Ce n\u2019est qu\u2019avec l\u2019aide de quatre vols draconiques que les essaims furent repouss\xe9s et scell\xe9s derri\xe8re le mur du Scarab\xe9e.","Le mur ne pouvait s\u2019ouvrir qu\u2019en frappant le gong du Scarab\xe9e avec ce sceptre. Fandral, dans la fureur de son chagrin, le brisa, et ses morceaux furent dispers\xe9s. Dans le jeu d\u2019origine, des aventuriers reconstitu\xe8rent le sceptre, firent sonner le gong et ouvrirent de nouveau Ahn'Qiraj."]},"item:doomhammer":{title:"Marteau-du-Destin",summary:"Le marteau de guerre ancestral de la lign\xe9e Marteau-du-Destin, port\xe9 par Orgrim pendant deux guerres puis remis \xe0 Thrall.",body:["Forg\xe9 il y a longtemps sur Draenor, le grand marteau de pierre noire se transmettait de p\xe8re en fils au sein d\u2019une seule famille orque, et une vieille proph\xe9tie rochenoire pesait sur lui : le dernier de la lign\xe9e apporterait aux orcs d\u2019abord le salut, puis la ruine, avant qu\u2019un \xe9tranger ne l\xe8ve le marteau au nom de la justice. Orgrim Marteau-du-Destin le mania pendant la Premi\xe8re et la Deuxi\xe8me Guerre et abattit avec lui Anduin Lothar, brisant la lame runique du chevalier.","Apr\xe8s la d\xe9faite de la Horde, Orgrim s\u2019\xe9vada et lutta pour lib\xe9rer son peuple des camps d\u2019internement. Mortellement bless\xe9 au cours de l\u2019une de ces batailles, il remit le marteau \xe0 Thrall, qui n\u2019\xe9tait ni de son clan ni de son sang. Thrall le porta comme le symbole d\u2019une Horde renaissante, et la proph\xe9tie trouva son \xe9tranger."]},"item:book-of-medivh":{title:"Le Livre de Medivh",summary:"Le dernier grimoire de Medivh \xe0 avoir surv\xe9cu, utilis\xe9 deux fois pour ouvrir de force le passage entre les mondes.",body:["Apr\xe8s la mort de Medivh, son grimoire fut conserv\xe9 dans la biblioth\xe8que royale de Hurlevent reconstruite, jusqu\u2019\xe0 ce que des agents d\u2019Alterac le d\xe9robent. Par un march\xe9 conclu entre le roi d\u2019Alterac et le chevalier de la mort de la Horde Teron Fielsang, il passa aux orcs, et sur Draenor, Ner'zhul s\u2019en servit avec d\u2019autres reliques pour ouvrir de nouveaux portails, des failles qui d\xe9chir\xe8rent son monde. Avant la chute de la Porte des T\xe9n\xe8bres, Khadgar r\xe9cup\xe9ra le livre et le renvoya chez lui \xe0 dos de griffon.","Le Kirin Tor le scella dans une chambre forte de Dalaran. Pendant la Troisi\xe8me Guerre, Kel'Thuzad brisa cette chambre forte et, gr\xe2ce au pouvoir du livre, ouvrit la faille par laquelle Archimonde et la L\xe9gion ardente entr\xe8rent en Azeroth. Par la suite, le livre resta entre les mains de la liche."]},"item:frostmourne":{title:"Deuillegivre",summary:"La lame runique du roi-liche, qui prit l\u2019\xe2me d\u2019Arthas Menethil dans les glaces de Norfendre.",body:["Deuillegivre \xe9tait li\xe9e \xe0 la prison du roi-liche dans la Couronne de glace, et Ner'zhul la fit sortir du Tr\xf4ne de glace pour attirer un champion. Elle attendait, gard\xe9e, dans une caverne gel\xe9e de Norfendre, avec un avertissement : son pouvoir marquerait l\u2019\xe2me de quiconque s\u2019en emparerait. Le prince Arthas, d\xe9sesp\xe9r\xe9 d\u2019arr\xeater la peste, ignora l\u2019avertissement et saisit la lame tandis que Muradin Barbe-de-bronze gisait \xe0 terre, frapp\xe9 par un \xe9clat de glace.","L\u2019\xe9p\xe9e d\xe9vore l\u2019\xe2me de ceux qu\u2019elle tue. Avec elle, Arthas tua le seigneur de l\u2019effroi Mal'Ganis, puis son propre p\xe8re, le roi Terenas, et son ancien mentor Uther. En l\u2019an 25, elle repose aux c\xf4t\xe9s du roi-liche en personne. Dans des r\xe9cits plus tardifs, au-del\xe0 de Classic, Tirion Fordring la brisa avec le Porte-cendres."]},"item:ashbringer":{title:"Le Porte-cendres",summary:"Une lame sacr\xe9e forg\xe9e \xe0 Forgefer pour r\xe9duire les morts-vivants en cendres, puis trahie et corrompue dans les Maleterres.",body:["Pendant la Deuxi\xe8me Guerre, le g\xe9n\xe9ralissime Alexandros Mograine de la Main d\u2019argent trouva un cristal sombre sur un d\xe9moniste orc abattu. Quand le Fl\xe9au mena\xe7a Lordaeron, les chefs de l\u2019ordre tent\xe8rent de le d\xe9truire par la magie sacr\xe9e ; au lieu de quoi le cristal absorba la Lumi\xe8re et devint radieux. Le roi Magni Barbe-de-bronze en forgea une \xe9p\xe9e sur la Grande Enclume de Forgefer, et entre les mains de Mograine, le Porte-cendres r\xe9duisait les morts-vivants en cendres.","Le seigneur de l\u2019effroi Balnazzar et Kel'Thuzad complot\xe8rent sa chute. Renault, le fils de Mograine, l\u2019attira dans une embuscade du Fl\xe9au \xe0 Stratholme et le tua avec sa propre \xe9p\xe9e, ce qui la corrompit. En l\u2019an 25, Alexandros sert Kel'Thuzad en tant que chevalier de la mort, tandis que Renault commande le Monast\xe8re \xe9carlate. Ce n\u2019est que dans des r\xe9cits plus tardifs que la lame fut purifi\xe9e."]},"item:skull-of-guldan":{title:"Le cr\xe2ne de Gul'dan",summary:"Le cr\xe2ne du d\xe9moniste, une relique d\xe9moniaque qui ouvrit des portails, empoisonna Orneval et transforma Illidan.",body:["Gul'dan fut mis en pi\xe8ces par des d\xe9mons dans la tombe de Sargeras, mais son cr\xe2ne conserva un \xe9clat de sa malveillance. Il passa entre plusieurs mains orques jusqu\u2019\xe0 ce que Grom Hurlenfer l\u2019apporte \xe0 Ner'zhul, qui s\u2019en servit pour aider \xe0 rouvrir la Porte des T\xe9n\xe8bres. Khadgar l\u2019envoya plus tard \xe0 Dalaran avec le Livre de Medivh, et le Kirin Tor garda les deux.","Quand Dalaran tomba pendant la Troisi\xe8me Guerre, le seigneur de l\u2019effroi Tichondrius vola le cr\xe2ne, et son pouvoir souilla les for\xeats d\u2019Orneval et du Gangrebois. Illidan Hurlorage en consuma la magie, devint \xe0 moiti\xe9 d\xe9mon et tua Tichondrius gr\xe2ce \xe0 ce pouvoir. La coquille vide du cr\xe2ne resta aupr\xe8s d\u2019Illidan."]},"item:gorehowl":{title:"Hurlesang",summary:"La hache hurlante de la famille Hurlenfer, qui abattit \xe0 la fois Cenarius et Mannoroth.",body:["Hurlesang fut forg\xe9e des g\xe9n\xe9rations avant que Grom Hurlenfer n\u2019en h\xe9rite, et une l\xe9gende chanteguerre raconte que la hache fut tremp\xe9e dans le c\u0153ur de puissants gronns. Grom, chef du clan Chanteguerre, fut le premier \xe0 boire le sang du seigneur des ab\xeemes Mannoroth, liant les orcs \xe0 la L\xe9gion ardente. En Orneval, il but de nouveau et tua avec Hurlesang le demi-dieu Cenarius.","Thrall le lib\xe9ra de l\u2019emprise du d\xe9mon, et ensemble ils affront\xe8rent Mannoroth. Grom fendit l\u2019arme du seigneur des ab\xeemes et le tua d\u2019un seul coup, brisant la mal\xe9diction qui pesait sur son peuple au prix de sa propre vie. Thrall garda ensuite la hache \xe0 Orgrimmar."]},"item:horn-of-cenarius":{title:"Le cor de Cenarius",summary:"Le cor du demi-dieu, qui tira les druides de leur long sommeil et appela les anc\xeatres des elfes de la nuit sur l\u2019Hyjal.",body:["Apr\xe8s la chute de Cenarius, son cor resta \xe0 Reflet-de-Lune sous la garde d\u2019antiques protecteurs. Lorsque la L\xe9gion ardente revint pendant la Troisi\xe8me Guerre, la pr\xeatresse Tyrande Murmevent le r\xe9cup\xe9ra et s\u2019en servit pour tirer Malfurion Hurlorage de son long r\xeave. Malfurion le fit sonner \xe0 son tour pour r\xe9veiller les druides endormis de la Serre et de la Griffe.","Au plus fort de la bataille du mont Hyjal, Malfurion sonna du cor une fois encore. Des milliers d\u2019esprits ancestraux r\xe9pondirent et fondirent sur Archimonde, an\xe9antissant le seigneur d\xe9mon au pied de l\u2019Arbre-Monde, m\xeame si le pouvoir d\xe9cha\xeen\xe9 laissa Nordrassil bless\xe9."]},"item:sulfuras":{title:"Sulfuras, la Main de Ragnaros",summary:"Le marteau ardent du seigneur du Feu, et la copie plus petite que les ma\xeetres forgerons apprirent \xe0 forger \xe0 son image.",body:["Sulfuras est le marteau colossal de Ragnaros, une masse d\u2019\xe9l\xe9mentium rouge en flammes que le seigneur du Feu ne l\xe2che jamais. Lors des guerres \xe9l\xe9mentaires d\u2019un pass\xe9 lointain, il en frappa Thunderaan, le prince des Airs. Depuis l\u2019invocation de Thaurissan, Ragnaros r\xe8gne, marteau en main, sur le C\u0153ur du Magma, sous le mont Rochenoire.","L\u2019arme v\xe9ritable est bien trop vaste pour des mains mortelles, mais on peut en faire une r\xe9plique. Dans le jeu d\u2019origine, un ma\xeetre forgeron obtenait les plans d\u2019un marteau de Sulfuron aupr\xe8s de Lokhtos Sombrescompte, de la Confr\xe9rie du thorium, dans les profondeurs de Rochenoire, puis l\u2019assemblait avec le rare \u0152il de Sulfuras pris \xe0 Ragnaros lui-m\xeame, cr\xe9ant ainsi une Main de Ragnaros \xe0 la taille d\u2019un mortel."]},"item:thunderfury":{title:"Lame-tonnerre, \xe9p\xe9e b\xe9nie du Cherchevent",summary:"Une \xe9p\xe9e forg\xe9e autour de la derni\xe8re essence de Thunderaan, le prince des Airs, que Ragnaros avait emprisonn\xe9.",body:["Lors d\u2019une antique guerre entre le feu et l\u2019air, Ragnaros et ses lieutenants Garr et le baron Geddon vainquirent Thunderaan, le prince des Airs. Le seigneur du Feu se nourrit de son essence sans parvenir \xe0 la d\xe9vorer enti\xe8rement ; il scella donc le reste dans un talisman, le brisa en deux et en remit une moiti\xe9 \xe0 chacun de ses lieutenants : les Liens du Cherchevent.","Dans le jeu d\u2019origine, les raids prenaient les deux moiti\xe9s \xe0 Garr et \xe0 Geddon dans le C\u0153ur du Magma et les apportaient au g\xe9n\xe9ralissime Demitrian, en Silithus. Avec l\u2019essence m\xeame du seigneur du Feu et des barres d\u2019\xe9l\xe9mentium enchant\xe9, les liens invoquaient le prince affaibli ; une fois celui-ci vaincu, Demitrian forgeait le pouvoir qui lui restait pour en faire Lame-tonnerre, une \xe9p\xe9e cr\xe9pitant d\u2019un orage vivant."]},"item:seal-of-ascension":{title:"Sceau d\u2019ascension",summary:"Un anneau forg\xe9 dans le feu d\u2019un dragon noir, qui ouvrait la citadelle sup\xe9rieure du pic Rochenoire.",body:["Les salles sup\xe9rieures du pic Rochenoire, o\xf9 Rend Main-Noire et le Vol noir tenaient leur cour, \xe9taient scell\xe9es contre les intrus. Dans le pic inf\xe9rieur, un \xe9tranger d\xe9guis\xe9 nomm\xe9 Vaelan, en v\xe9rit\xe9 le dragon rouge Vaelastrasz, qui avait jur\xe9 de traquer Nefarian, apprenait aux aventuriers \xe0 fabriquer une cl\xe9 : un sceau sans ornement serti de trois gemmes prises aux chefs Smolderthorn, Spirestone et Hache-sanglante du pic.","Le sceau devait ensuite \xeatre forg\xe9 dans le feu d\u2019un dragon noir. Les h\xe9ros se rendaient au Wyrmbog, dans le mar\xe9cage d\u2019\xc2prefange, et contraignaient le drake Emberstrife \xe0 souffler dessus. L\u2019anneau achev\xe9 ouvrait la citadelle sup\xe9rieure et, lors du combat contre Rend, pouvait appeler une projection de Vaelastrasz aux c\xf4t\xe9s des h\xe9ros."]},"item:drakefire-amulet":{title:"Amulette Feu-du-drake",summary:"Le talisman bris\xe9 d\u2019Onyxia, refait avec le sang d\u2019un dragon noir pour devenir la cl\xe9 de son propre repaire.",body:["D\xe9guis\xe9e en dame Katrana Prestor, Onyxia s\u2019introduisit \xe0 la cour de Hurlevent gr\xe2ce \xe0 un pendentif appel\xe9 l\u2019\u0152il du dragon. Il ne contr\xf4lait pas directement les esprits, mais \xe9veillait des d\xe9sirs cach\xe9s et d\xe9tournait les soup\xe7ons d\u2019elle. Lorsque le mar\xe9chal Windsor r\xe9v\xe9la la mascarade, le pendentif se brisa, et le dragon bleu Haleh en refa\xe7onna les morceaux, avec le sang du g\xe9n\xe9ral Drakkisath, pour en faire l\u2019amulette Feu-du-drake.","Les h\xe9ros de la Horde obtiennent la m\xeame amulette par un autre chemin, en passant par Rexxar et les \xe9preuves de l\u2019antique drake Emberstrife. Chaque membre d\u2019un raid qui entre dans le repaire d\u2019Onyxia doit la porter, et Forever conserve cette harmonisation sous la forme d\u2019une suite de qu\xeates distincte pour chaque faction."]},"item:head-of-onyxia":{title:"T\xeate d\u2019Onyxia",summary:"La preuve de la mort de la m\xe8re de la couv\xe9e, hiss\xe9e au-dessus des portes de Hurlevent ou d\u2019Orgrimmar comme \xe9tendard de ralliement.",body:["Onyxia, fille d\u2019Aile-de-mort et s\u0153ur cadette de Nefarian, garde sa couv\xe9e dans une caverne du mar\xe9cage d\u2019\xc2prefange tout en complotant pour plier les royaumes mortels d\u2019Azeroth \xe0 sa volont\xe9. Sa d\xe9faite mit fin \xe0 l\u2019une des plus longues supercheries du Vol noir.","Dans le jeu d\u2019origine, sa t\xeate \xe9tait rapport\xe9e comme troph\xe9e : les champions de l\u2019Alliance la pr\xe9sentaient \xe0 Hurlevent, ceux de la Horde \xe0 Thrall, \xe0 Orgrimmar. Hiss\xe9e au-dessus des portes de la ville, elle accordait le Cri de ralliement du tueur de dragons \xe0 tous ceux qui se trouvaient en ville, et toute la capitale c\xe9l\xe9brait la victoire."]},"item:quel-serrar":{title:"Quel'Serrar",summary:"Une antique lame des elfes de la nuit, gard\xe9e par les Shen'dralar et achev\xe9e seulement dans le souffle d\u2019un dragon.",body:["Quel'Serrar est l\u2019une des lames prismatiques que les forgerons elfes de la nuit forg\xe8rent il y a longtemps avec l\u2019aide des vols draconiques ; sa jumelle, Quel'Delar, fut offerte aux hauts-elfes. Pendant des milliers d\u2019ann\xe9es, les Shen'dralar d\u2019Eldre'Thalas la gard\xe8rent, attendant un porteur assez fort pour l\u2019\xe9veiller.","Dans le jeu d\u2019origine, un guerrier ou un paladin qui avait trouv\xe9 un vieux trait\xe9 sur la chasse aux dragons l\u2019apportait au gardien du savoir Lydros, dans la biblioth\xe8que de Hache-Tripes, et recevait une lame non tremp\xe9e. Chauff\xe9 par le souffle profond d\u2019Onyxia puis plong\xe9 dans le dragon abattu, l\u2019acier devenait Quel'Serrar une fois rapport\xe9 \xe0 Lydros."]},"item:rhokdelar":{title:"Rhok'delar et Lok'delar",summary:"Un arc long et un b\xe2ton vivants, fa\xe7onn\xe9s par les Anciens corrompus du Gangrebois pour le chasseur qui les vengea.",body:["Lorsque la L\xe9gion ardente d\xe9ferla sur Kalimdor, elle empoisonna la vall\xe9e qui devint le Gangrebois. Ses plus puissants Anciens se dess\xe9ch\xe8rent en coquilles p\xe9trifi\xe9es, mais leurs esprits demeur\xe8rent. Une feuille de l\u2019un d\u2019eux, Vartrus, finit dans le tr\xe9sor du seigneur du Feu, au C\u0153ur du Magma.","Dans le jeu d\u2019origine, le chasseur qui rapportait la feuille \xe0 Vartrus \xe9tait envoy\xe9 traquer seul quatre agents de la L\xe9gion, sans m\xeame un familier. En r\xe9compense, les Anciens fa\xe7onnaient Rhok'delar, un arc long qui se couvre de fleurs de lui-m\xeame, et son compagnon Lok'delar, un b\xe2ton qui luit de la puissance de la nature."]},"item:taelans-hammer":{title:"Le marteau de Taelan",summary:"Le marteau-jouet d\u2019un enfant, qui aida Tirion Fordring \xe0 retrouver le fils que la Croisade \xe9carlate lui avait pris.",body:["Pour son septi\xe8me anniversaire, le jeune Taelan re\xe7ut de son p\xe8re, Tirion Fordring, un marteau de guerre miniature, r\xe9plique de celui de Tirion. Apr\xe8s que Tirion eut \xe9t\xe9 exil\xe9 pour avoir d\xe9fendu l\u2019orc Eitrigg, la m\xe8re de Taelan dit au gar\xe7on que son p\xe8re \xe9tait mort et l\u2019emmena devant une fausse tombe \xe0 l\u2019Undercroft, dans les Maleterres de l\u2019Est, o\xf9 il enterra le marteau, et le souvenir avec lui.","Des ann\xe9es plus tard, Taelan devint g\xe9n\xe9ralissime de la Croisade \xe9carlate \xe0 \xc2treval. Dans le jeu d\u2019origine, des aventuriers rapportaient le marteau au vieux Tirion et aidaient Taelan \xe0 voir ce que la Croisade \xe9tait devenue. Alors qu\u2019il fuyait \xc2treval, le grand inquisiteur Isillien l\u2019abattit sous les yeux de son p\xe8re ; Tirion tua Isillien et fit le serment de reforger la Main d\u2019argent."]},"item:heart-of-hakkar":{title:"C\u0153ur d\u2019Hakkar",summary:"Le c\u0153ur toujours br\xfblant du dieu du sang, port\xe9 aux Zandalari apr\xe8s la mort d\u2019Hakkar \xe0 Zul'Gurub.",body:["Environ quinze si\xe8cles avant la Porte des T\xe9n\xe8bres, les trolls gurubashi affam\xe9s se tourn\xe8rent vers Hakkar l\u2019\xc9corcheur d\u2019\xe2mes, un loa du sang. Il leur donna puissance et empire, puis exigea toujours plus de vies, jusqu\u2019\xe0 ce que les tribus se soul\xe8vent contre lui et exilent ses pr\xeatres atal'ai. Lorsque les pr\xeatres \xe9lev\xe8rent un temple pour le faire revenir, Ysera le fracassa et l\u2019engloutit sous les marais du marais des Chagrins.","Dans le jeu d\u2019origine, les pr\xeatres hakkari parvinrent enfin \xe0 attirer l\u2019\xc9corcheur d\u2019\xe2mes \xe0 Zul'Gurub. Des h\xe9ros ralli\xe9s par la tribu Zandalar l\u2019y tu\xe8rent et port\xe8rent son c\u0153ur encore luisant \xe0 Molthor, sur l\u2019\xeele de Yojamba, dont le rite accordait \xe0 tous ceux qui se trouvaient sur l\u2019\xeele et \xe0 Baie-du-Butin l\u2019Esprit des Zandalar."]},"item:phylactery-of-kelthuzad":{title:"Le phylact\xe8re de Kel'Thuzad",summary:"Le r\xe9ceptacle qui renferme l\u2019\xe2me de l\u2019archiliche, emport\xe9 de Naxxramas apr\xe8s sa d\xe9faite.",body:["Kel'Thuzad, jadis archimage du Kirin Tor, fonda le culte des Damn\xe9s et r\xe9pandit la peste pour le roi-liche. Tu\xe9 par Arthas puis port\xe9 jusqu\u2019au Puits de soleil pour rena\xeetre en liche, il en vint \xe0 gouverner le Fl\xe9au en Lordaeron depuis la n\xe9cropole flottante de Naxxramas.","Une liche perdure tant que survit le r\xe9ceptacle qui contient son \xe2me. Dans le jeu d\u2019origine, les raids qui avaient vaincu Kel'Thuzad r\xe9cup\xe9raient son phylact\xe8re et le confiaient \xe0 l\u2019Aube d\u2019argent pour qu\u2019elle le garde. Des r\xe9cits plus tardifs r\xe9v\xe9l\xe8rent que l\u2019un de ses pr\xeatres, le p\xe8re Inigo Montoy, trahit cette confiance et l\u2019emporta en Norfendre, laissant \xe0 l\u2019archiliche le temps de revenir."]}}},1601,[]);
__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"terms",{enumerable:!0,get:function(){return s}});const s={"term:argent-dawn":{title:"Aube d\u2019argent",summary:"Un ordre qui a jur\xe9 de d\xe9fendre Azeroth contre le Fl\xe9au, sans la haine aveugle de la Croisade \xe9carlate.",body:["Quand les survivants de la Main d\u2019argent en Lordaeron se fig\xe8rent pour former la fanatique Croisade \xe9carlate, certains refus\xe8rent de les suivre. Men\xe9s par des figures comme le seigneur Maxwell Tyrosus, ils fond\xe8rent l\u2019Aube d\u2019argent, qui accueille quiconque est pr\xeat \xe0 combattre les morts-vivants. Depuis la chapelle de l\u2019Espoir de Lumi\xe8re, dans les Maleterres de l\u2019Est, l\u2019ordre surveille le Fl\xe9au et r\xe9compense ceux qui aident \xe0 tenir la ligne."]},"term:burning-legion":{title:"L\xe9gion ardente",summary:"L\u2019arm\xe9e infinie de d\xe9mons du titan d\xe9chu Sargeras, qui a jur\xe9 de br\xfbler toute la cr\xe9ation.",body:["Autrefois champion du Panth\xe9on des titans, Sargeras apprit que les puissances du Vide cherchaient \xe0 corrompre les \xe2mes-mondes et, de d\xe9sespoir, r\xe9solut de br\xfbler la cr\xe9ation plut\xf4t que de la leur laisser. Il lib\xe9ra les d\xe9mons qu\u2019il avait emprisonn\xe9s et rallia les seigneurs \xe9r\xe9dars Kil'jaeden et Archimonde pour les commander. La L\xe9gion envahit Azeroth pendant la guerre des Anciens, puis de nouveau pendant la Troisi\xe8me Guerre, et ses agents r\xf4dent encore dans des lieux comme le Gangrebois et les terres Foudroy\xe9es."]},"term:cenarion-circle":{title:"Cercle c\xe9narien",summary:"L\u2019ordre druidique des elfes de la nuit et des taurens, qui veille sur l\u2019\xe9quilibre de la nature depuis Reflet-de-Lune.",body:["Nomm\xe9 d\u2019apr\xe8s le demi-dieu Cenarius, qui enseigna aux premiers druides, le Cercle unit les druides elfes de la nuit et taurens en un seul ordre. Son c\u0153ur est le village de Havrenuit, \xe0 Reflet-de-Lune, un sanctuaire o\xf9 les combats sont interdits, et ses membres surveillent aussi les dangers de Silithus depuis le fort C\xe9narien."]},"term:cult-of-the-damned":{title:"Culte des Damn\xe9s",summary:"Le culte des Damn\xe9s, vou\xe9 au roi-liche par Kel'Thuzad, qui promettait la vie \xe9ternelle et apporta la peste.",body:["L\u2019archimage Kel'Thuzad tourna le dos au Kirin Tor pour \xe9tudier la n\xe9cromancie et rassembla les pauvres et les d\xe9sesp\xe9r\xe9s de Lordaeron en leur promettant une vie meilleure, affranchie de la mort. Le culte cacha la peste du roi-liche dans des cargaisons de grain, transformant des villages entiers en Fl\xe9au. Ses n\xe9cromanciens enseignent encore \xe0 Scholomance, dans l\u2019ancien fort de la famille Barov, Caer Darrow."]},"term:dark-portal":{title:"Porte des T\xe9n\xe8bres",summary:"Le passage entre Draenor et Azeroth par lequel la Horde orque envahit le monde.",body:["Le d\xe9moniste orc Gul'dan et le Gardien poss\xe9d\xe9 Medivh ouvrirent la Porte des T\xe9n\xe8bres, reliant Draenor au Noir Mar\xe9cage d\u2019Azeroth. Son ouverture d\xe9clencha la Premi\xe8re Guerre, et les ann\xe9es de l\u2019histoire de Warcraft se comptent encore \xe0 partir d\u2019elle. L\u2019Alliance la d\xe9truisit apr\xe8s la Deuxi\xe8me Guerre, Ner'zhul la rouvrit de force, et Khadgar la fit s\u2019effondrer depuis Draenor. Son armature endormie domine encore les terres Foudroy\xe9es."]},"term:defias-brotherhood":{title:"Confr\xe9rie d\xe9fias",summary:"Des tailleurs de pierre de Hurlevent jamais pay\xe9s, devenus bandits sous la conduite d\u2019Edwin VanCleef.",body:["La guilde des tailleurs de pierre reconstruisit Hurlevent apr\xe8s la Deuxi\xe8me Guerre, mais les nobles refus\xe8rent de la payer. Son chef, Edwin VanCleef, entra\xeena les ma\xe7ons en col\xe8re dans la marche de l\u2019Ouest et en fit la Confr\xe9rie d\xe9fias, une bande de voleurs et de saboteurs cach\xe9e dans les Mortemines. Dans Forever, ses membres apparaissent aussi dans Alcaz Prison, engag\xe9s dans une lutte contre les nagas."]},"term:dragon-aspects":{title:"Aspects dragons",summary:"Cinq grands dragons investis par les titans de la garde d\u2019Azeroth, chacun \xe0 la t\xeate d\u2019un vol draconique.",body:["Les titans choisirent cinq dragons et donn\xe8rent \xe0 chacun une part de leur pouvoir : Alexstrasza la Lieuse-de-vie, du vol rouge ; Ysera la R\xeaveuse, du vert ; Nozdormu l\u2019Intemporel, du bronze ; Malygos le Tisse-sort, du bleu ; et Neltharion le Gardien de la Terre, du noir. La trahison de Neltharion fit de lui Aile-de-mort, et ses enfants Onyxia et Nefarian complotent encore en Azeroth."]},"term:elemental-lords":{title:"Seigneurs \xe9l\xe9mentaires",summary:"Les quatre souverains du feu, de la terre, de l\u2019air et de l\u2019eau, jadis serviteurs des Dieux tr\xe8s anciens.",body:["Ragnaros du feu, Therazane de la terre, Al'Akir de l\u2019air et Neptulon de l\u2019eau men\xe8rent les \xe9l\xe9mentaires dans la guerre des Dieux tr\xe8s anciens contre les serviteurs des titans. Quand l\u2019Empire noir tomba, les gardiens les encha\xeen\xe8rent dans le plan \xc9l\xe9mentaire. Les chamans s\u2019efforcent de maintenir les \xe9l\xe9ments en \xe9quilibre, tandis que la b\xe9vue du sorcier sombrefer Thaurissan a ramen\xe9 Ragnaros dans le monde, sous le mont Rochenoire."]},"term:elune":{title:"\xc9lune",summary:"La d\xe9esse lunaire des elfes de la nuit, dont les pr\xeatresses guident leur peuple.",body:["Les elfes de la nuit v\xe9n\xe8rent \xc9lune depuis l\u2019aube de leur civilisation et trouvent un guide dans la lumi\xe8re de la lune. La Sororit\xe9 d\u2019\xc9lune, men\xe9e par la grande pr\xeatresse Tyrande Murmevent, sert \xe0 la fois de clerg\xe9 et de gouvernement \xe0 Darnassus, et les pr\xeatres elfes de la nuit tirent leur pouvoir de gu\xe9rison de la d\xe9esse."]},"term:emerald-dream":{title:"R\xeave d\u2019\xe9meraude",summary:"Un reflet onirique des \xe9tendues sauvages et intactes d\u2019Azeroth, veill\xe9 par Ysera et parcouru par les druides.",body:["Le R\xeave d\u2019\xe9meraude refl\xe8te le monde tel qu\u2019il aurait pu \xeatre sans les mains des mortels. Ysera et son vol vert le gardent, et les druides y entrent en esprit, dormant parfois des si\xe8cles durant. Dans le pr\xe9sent d\u2019Azeroth, quelque chose aigrit le R\xeave : un cauchemar rampant tord les r\xeaves de Naralex dans les cavernes des Lamentations et a rendu fous les dragons verts du temple englouti."]},"term:explorers-league":{title:"Ligue des explorateurs",summary:"La soci\xe9t\xe9 d\u2019arch\xe9ologues nains de Forgefer, qui fouille \xe0 la recherche des secrets des titans.",body:["Depuis la salle des Explorateurs de Forgefer, la Ligue envoie des nains aux quatre coins du monde \xe0 la recherche de reliques susceptibles d\u2019expliquer l\u2019origine de leur peuple. Son membre le plus c\xe9l\xe8bre est Brann Barbe-de-bronze, le fr\xe8re infatigable du roi. Les fouilleurs de la Ligue ont mis au jour les chambres fortes titaniques d\u2019Uldaman, et dans Forever, les \xe9tranges ruines fig\xe9es dans le temps au-del\xe0 du Whelgar's Excavation Site, dans les Paluns, sont exactement le genre de myst\xe8re que poursuit la Ligue."]},"term:fel":{title:"Gangr\xe8ne",summary:"La magie br\xfblante et corruptrice de la L\xe9gion ardente.",body:["La gangr\xe8ne est la magie des d\xe9mons : puissante, addictive et ruineuse pour tout ce qu\u2019elle touche. Les d\xe9monistes de Gul'dan s\u2019en servirent pour vider Draenor de sa vie et lier les orcs \xe0 la L\xe9gion, et sa souillure leur verdit la peau. Les d\xe9monistes la manient encore aujourd\u2019hui, et ses cicatrices marquent le Gangrebois, o\xf9 la corruption d\xe9moniaque a empoisonn\xe9 une for\xeat ancestrale."]},"term:guardian-of-tirisfal":{title:"Gardien de Tirisfal",summary:"Un mage investi du pouvoir r\xe9uni d\u2019un conseil secret pour combattre seul la L\xe9gion ardente.",body:["Des magiciens hauts-elfes et humains fond\xe8rent le conseil secret de Tirisfal pour emp\xeacher les d\xe9mons de se glisser dans le monde \xe0 la faveur d\u2019une magie imprudente. \xc0 chaque \xe9poque, le conseil versait son pouvoir dans un unique champion, le Gardien. Aegwynn tint ce r\xf4le pendant des si\xe8cles ; son fils Medivh, le dernier Gardien, \xe9tait secr\xe8tement poss\xe9d\xe9 par Sargeras et ouvrit la voie aux orcs."]},"term:highborne":{title:"Bien-n\xe9s",summary:"L\u2019aristocratie arcanique de l\u2019antique empire elfe de la nuit, dont la soif de magie attira la L\xe9gion.",body:["Les Bien-n\xe9s servaient la reine Azshara comme courtisans et comme sorciers, puisant toujours plus profond\xe9ment dans le Puits d\u2019\xe9ternit\xe9 jusqu\u2019\xe0 ce que leurs sorts attirent l\u2019attention de Sargeras. Apr\xe8s la Fracture, la plupart des survivants furent exil\xe9s et fond\xe8rent Quel'Thalas en tant que hauts-elfes. D\u2019autres, les Shen'dralar, rest\xe8rent cach\xe9s dans Eldre'Thalas, la cit\xe9 aujourd\u2019hui appel\xe9e Hache-Tripes."]},"term:holy-light":{title:"La Lumi\xe8re sacr\xe9e",summary:"La puissance de l\u2019espoir et de la vertu que canalisent les paladins et les pr\xeatres.",body:["Les humains v\xe9n\xe8rent la Lumi\xe8re \xe0 travers l\u2019\xc9glise de la Lumi\xe8re sacr\xe9e, dont les clercs soignent les bless\xe9s et dont les cath\xe9drales s\u2019\xe9l\xe8vent \xe0 Hurlevent et s\u2019\xe9levaient autrefois en Lordaeron. Les nains l\u2019adopt\xe8rent eux aussi. Pendant la Deuxi\xe8me Guerre, l\u2019archev\xeaque Alonsus Faol unit la foi et l\u2019acier en fondant les paladins de la Main d\u2019argent, et la Lumi\xe8re reste le fl\xe9au des morts-vivants."]},"term:kaldorei":{title:"Kaldorei",summary:"Les elfes de la nuit, \xab enfants des \xe9toiles \xbb, l\u2019une des plus anciennes civilisations de Kalimdor.",body:["Descendants de trolls transform\xe9s par le Puits d\u2019\xe9ternit\xe9, les elfes de la nuit b\xe2tirent sous la reine Azshara un empire \xe9blouissant avant qu\u2019il ne sombre lors de la Fracture. Pendant dix mille ans, ils v\xe9curent en druides et en Sentinelles, pr\xe9serv\xe9s de l\u2019\xe2ge par Nordrassil, jusqu\u2019\xe0 ce que la Troisi\xe8me Guerre leur co\xfbte leur immortalit\xe9. Aujourd\u2019hui, ils gouvernent depuis Darnassus, au sommet de Teldrassil, et se tiennent aux c\xf4t\xe9s de l\u2019Alliance."]},"term:kirin-tor":{title:"Kirin Tor",summary:"Le conseil de mages qui gouverne Dalaran et met sous cl\xe9 la magie dangereuse.",body:["Fond\xe9 \xe0 Dalaran, la cit\xe9 des mages, le Kirin Tor supervise l\u2019\xe9tude de la magie des arcanes et enferme les artefacts trop dangereux pour le monde. Archimonde laissa Dalaran en ruine pendant la Troisi\xe8me Guerre, et dans le jeu d\u2019origine, la cit\xe9 restait cach\xe9e sous un d\xf4me violet. Dans Forever, cette barri\xe8re est tomb\xe9e et r\xe9v\xe8le une restauration submerg\xe9e par un chaos arcanique d\xe9r\xe9gl\xe9."]},"term:ley-lines":{title:"Lignes telluriques",summary:"Des courants d\u2019\xe9nergie arcanique qui parcourent Azeroth comme des veines.",body:["Les lignes telluriques portent la puissance arcanique brute \xe0 travers le monde, et l\xe0 o\xf9 elles se croisent, la magie gagne en force. Les hauts-elfes \xe9lev\xe8rent le Puits de soleil \xe0 l\u2019un de ces n\u0153uds, et les mages recherchent ces courants depuis longtemps. Dans Forever, les Skyborne du High Order peuvent y puiser gr\xe2ce \xe0 leur aptitude raciale Read Ley Line, qui dure bien plus longtemps lorsqu\u2019on l\u2019utilise pr\xe8s de l\u2019une d\u2019elles."]},"term:lich-king":{title:"Roi-liche",summary:"Le ma\xeetre immortel du Fl\xe9au, qui tr\xf4ne dans les glaces de Norfendre.",body:["Kil'jaeden arracha l\u2019esprit du chaman orc Ner'zhul \xe0 son corps et l\u2019enferma dans un bloc de glace au sommet de la Couronne de glace, le Tr\xf4ne de glace, afin de pr\xe9parer Azeroth pour la L\xe9gion. De l\xe0, le roi-liche leva le Fl\xe9au et r\xe9pandit la peste. Apr\xe8s la Troisi\xe8me Guerre, le prince Arthas gravit le tr\xf4ne et fusionna avec lui, et le roi-liche ainsi uni attend d\xe9sormais en Norfendre."]},"term:loa":{title:"Loa",summary:"Les puissants esprits animaux et dieux que v\xe9n\xe8rent les trolls.",body:["Chaque tribu troll honore les loas, des esprits antiques qui prennent souvent la forme de grandes b\xeates, et marchande avec eux pour obtenir de la force. Certains sont capricieux mais justes ; d\u2019autres sont cruels. Hakkar l\u2019\xc9corcheur d\u2019\xe2mes, le loa du sang, faillit d\xe9vorer l\u2019empire gurubashi, et ses fid\xe8les s\u2019agitent encore dans la vall\xe9e de Strangleronce et le marais des Chagrins."]},"term:nathrezim":{title:"Nathrezim",summary:"Les seigneurs de l\u2019effroi : des d\xe9mons vampiriques et rus\xe9s qui servent la L\xe9gion par la tromperie.",body:["Les nathrezim pr\xe9f\xe8rent les murmures \xe0 la guerre ouverte. La L\xe9gion chargea des seigneurs de l\u2019effroi comme Mal'Ganis, Tichondrius et Balnazzar de surveiller le roi-liche et de guider la conqu\xeate de Lordaeron par le Fl\xe9au. Quand le roi-liche se lib\xe9ra de leur emprise, ils se dispers\xe8rent, mais certains se cachent encore au vu de tous : Balnazzar porte le visage du grand crois\xe9 de la Croisade \xe9carlate."]},"term:nordrassil":{title:"Nordrassil",summary:"L\u2019Arbre-Monde du mont Hyjal, plant\xe9 par les Aspects pour sceller le second Puits d\u2019\xe9ternit\xe9.",body:["Apr\xe8s la Fracture, Illidan versa en secret de l\u2019eau vol\xe9e au Puits d\u2019\xe9ternit\xe9 dans un lac du mont Hyjal. Pour sceller ce nouveau puits, les Aspects dragons plant\xe8rent une graine enchant\xe9e qui devint Nordrassil, et sa b\xe9n\xe9diction rendit les elfes de la nuit insensibles \xe0 l\u2019\xe2ge. La chute d\u2019Archimonde \xe0 ses racines blessa l\u2019arbre, et le raid Hyjal Summit de Forever grimpe jusqu\u2019au sommet, \xe0 ses c\xf4t\xe9s."]},"term:old-gods":{title:"Dieux tr\xe8s anciens",summary:"D\u2019antiques \xeatres du Vide qui s\u2019enfouirent dans Azeroth pour corrompre son \xe2me-monde.",body:["Bien avant que les mortels ne foulent le monde, les Dieux tr\xe8s anciens, parmi lesquels C'Thun, Yogg-Saron, N'Zoth et Y'Shaarj, s\u2019\xe9cras\xe8rent sur Azeroth et dress\xe8rent un Empire noir. Arracher Y'Shaarj blessa le monde lui-m\xeame ; les titans choisirent donc d\u2019emprisonner les autres sous terre. Leurs murmures poussent encore des cultes comme le Marteau du cr\xe9puscule, et C'Thun s\u2019agite sous Ahn'Qiraj, en Silithus."]},"term:silver-hand":{title:"Ordre de la Main d\u2019argent",summary:"Le premier ordre de paladins, fond\xe9 en Lordaeron pendant la Deuxi\xe8me Guerre.",body:["L\u2019archev\xeaque Alonsus Faol comprit que les clercs seuls ne survivraient pas \xe0 la Horde ; il forma donc des guerriers aux voies de la Lumi\xe8re. Uther le Porteur de Lumi\xe8re devint le premier des chevaliers de la Main d\u2019argent. L\u2019ordre combattit pendant toute la Deuxi\xe8me Guerre, mais la chute d\u2019Arthas le brisa : Uther mourut de la main de son ancien \xe9l\xe8ve, et de nombreux survivants rejoignirent peu \xe0 peu la Croisade \xe9carlate."]},"term:queldorei":{title:"Quel'dorei",summary:"Les hauts-elfes de Quel'Thalas, h\xe9ritiers des Bien-n\xe9s exil\xe9s.",body:["Pr\xe8s de sept mille ans avant la Porte des T\xe9n\xe8bres, des Bien-n\xe9s exil\xe9s travers\xe8rent la mer, fond\xe8rent Quel'Thalas et allum\xe8rent le Puits de soleil. Ils s\u2019alli\xe8rent aux humains d\u2019Arathor pendant les guerres des Trolls et leur enseign\xe8rent la magie. Quand le Fl\xe9au d\u2019Arthas ravagea leur royaume et souilla le Puits de soleil, la plupart des survivants prirent un nouveau nom en m\xe9moire de leurs morts : les sin'dorei, ou elfes de sang."]},"term:scarlet-crusade":{title:"Croisade \xe9carlate",summary:"Des fanatiques qui traquent les morts-vivants et quiconque ils soup\xe7onnent de porter la peste, secr\xe8tement men\xe9s par un seigneur de l\u2019effroi.",body:["N\xe9e des paladins et soldats survivants de Lordaeron, la Croisade jura d\u2019\xe9radiquer le Fl\xe9au, mais devint si fanatique qu\u2019elle attaque aussi bien les R\xe9prouv\xe9s que les voyageurs vivants. Son grand crois\xe9 est secr\xe8tement le seigneur de l\u2019effroi Balnazzar. Parmi ses bastions figurent le Monast\xe8re \xe9carlate, dans les clairi\xe8res de Tirisfal, \xc2treval et la Main de Tyr."]},"term:scourge":{title:"Fl\xe9au",summary:"L\u2019arm\xe9e de morts-vivants du roi-liche, propag\xe9e par la peste et la n\xe9cromancie.",body:["Le Fl\xe9au est li\xe9 \xe0 la volont\xe9 du roi-liche : goules, abominations, liches et chevaliers de la mort relev\xe9s parmi les tomb\xe9s. La peste qui l\u2019a engendr\xe9 balaya Lordaeron pendant la Troisi\xe8me Guerre et laissa derri\xe8re elle les Maleterres. Sous Kel'Thuzad, le Fl\xe9au tient encore Stratholme et Scholomance, et son emprise s\u2019\xe9tend jusqu\u2019aux souilles de Tranchebauge, dans les Tarides."]},"term:skywall":{title:"Skywall",summary:"Le plan \xc9l\xe9mentaire de l\u2019air, royaume d\u2019Al'Akir, le seigneur des Vents.",body:["Quand les serviteurs des titans encha\xeen\xe8rent les \xe9l\xe9mentaires, les seigneurs de l\u2019air furent confin\xe9s \xe0 Skywall, un royaume de ciel sans fin gouvern\xe9 par Al'Akir. Dans Forever, Skywall abrite aussi Zephras Isle, la zone de d\xe9part flottante des Skyborne. Les \xe9l\xe9mentaires d\u2019air de l\u2019\xeele ont disparu il y a des si\xe8cles, et la magie qui la maintient dans les airs s\u2019affaiblit lentement."]},"term:sunwell":{title:"Puits de soleil",summary:"La source de pouvoir arcanique au c\u0153ur de Quel'Thalas.",body:["Dath'Remar Haut-Soleil versa une fiole vol\xe9e au Puits d\u2019\xe9ternit\xe9 dans un lac o\xf9 se croisent des lignes telluriques, et le Puits de soleil s\u2019embrasa. Pendant des mill\xe9naires, il nourrit la magie et la culture des hauts-elfes. Pendant la Troisi\xe8me Guerre, Arthas se servit de ses eaux pour relever Kel'Thuzad en liche et profana la source ; sa perte laissa aux survivants une faim durable de magie."]},"term:titan-forged":{title:"Forg\xe9s par les titans",summary:"Les gardiens et autres serviteurs que les titans cr\xe9\xe8rent pour ordonner Azeroth.",body:["Les titans fa\xe7onn\xe8rent des serviteurs pour achever leur \u0153uvre : d\u2019immenses gardiens et des races de pierre et de m\xe9tal comme les terrestres et les m\xe9cagnomes. Au fil des \xe2ges, la mal\xe9diction de la chair des Dieux tr\xe8s anciens rendit nombre d\u2019entre eux mortels, et les nains et les gnomes en descendent. Des gardiens forg\xe9s par les titans veillent encore sur des chambres fortes comme Uldaman, et Forever ajoute d\u2019autres sites titaniques, de la fouille des Paluns \xe0 Shaper's Terrace, dans le crat\xe8re d\u2019Un'Goro."]},"term:titans":{title:"Titans",summary:"Des \xe2mes-mondes colossales qui cherchaient \xe0 mettre de l\u2019ordre dans le cosmos et qui fa\xe7onn\xe8rent Azeroth.",body:["Les titans sont des \xe2mes-mondes \xe9veill\xe9es en \xeatres divins. Leur Panth\xe9on, men\xe9 par Aman'Thul, parcourut le cosmos \xe0 la recherche d\u2019\xe2mes-mondes endormies et en trouva une tr\xe8s prometteuse au sein d\u2019Azeroth. Ils arrach\xe8rent du monde le Dieu tr\xe8s ancien Y'Shaarj, emprisonn\xe8rent les autres et laiss\xe8rent \xe0 leurs serviteurs le soin de fa\xe7onner la terre. Leur plus puissant champion, Sargeras, chuta plus tard et fonda la L\xe9gion ardente."]},"term:twilights-hammer":{title:"Marteau du cr\xe9puscule",summary:"Autrefois un clan orc, aujourd\u2019hui un culte apocalyptique au service des Dieux tr\xe8s anciens.",body:["Men\xe9 par le mage ogre \xe0 deux t\xeates Cho'gall, le Marteau du cr\xe9puscule combattit pendant la Deuxi\xe8me Guerre en tant que clan orc avant de devenir un culte qui aspire \xe0 la fin du monde. Ses membres, issus de toutes les races, se rassemblent dans des lieux comme les profondeurs de Brassenoire et Silithus. Dans Forever, le culte tient aussi les ruines de Sunnyglade, dans les Riverglades."]},"term:well-of-eternity":{title:"Puits d\u2019\xe9ternit\xe9",summary:"Le lac de pure puissance arcanique au c\u0153ur de l\u2019antique Kalimdor, dont l\u2019implosion fractura le monde.",body:["Le Puits se forma l\xe0 o\xf9 les titans arrach\xe8rent Y'Shaarj du monde, et les gardiens apais\xe8rent la plaie b\xe9ante pour en faire un lac de puissance pure. Les elfes de la nuit b\xe2tirent leur empire sur ses rives, et les sorts imprudents des Bien-n\xe9s y attir\xe8rent la L\xe9gion. Son effondrement pendant la guerre des Anciens provoqua la Fracture, et le Maelstr\xf6m tourbillonne l\xe0 o\xf9 il se trouvait autrefois."]}}},1602,[]);